static func from_data(data: Variant) -> CharacterState:
	if not data is Dictionary:
		return null
	for field: String in ["id", "name", "currentHealth", "maximumHealth"]:
		if not data.has(field):
			return null
	if not data["id"] is String or data["id"].is_empty() or not data["name"] is String:
		return null
	var health := _integer(data["currentHealth"])
	var maximum := _integer(data["maximumHealth"])
	if health < -32_768 or maximum < 1:
		return null
	if health > maximum:
		return null
	var result := CharacterState.new(data["id"], data["name"], health, maximum)
	if not data.has("raceId"):
		return result
	for field: String in ["raceId", "casteId", "gender", "level", "experience", "ageDays", "attributes", "toHit", "dodge", "missile", "handToHand", "damageBonus", "armor", "magicResistance", "movement", "maximumMovement", "normalAttacks", "attacksRemaining", "spellcasterType", "spellPoints", "maximumSpellPoints", "load", "maximumLoad", "conditions", "money", "saves", "specials", "inventory", "knownSpells"]:
		if not data.has(field):
			return null
	if not data["raceId"] is String or data["raceId"].is_empty() or not data["casteId"] is String or data["casteId"].is_empty() or not data["attributes"] is Array or data["attributes"].size() != 6 or not data["saves"] is Array or data["saves"].size() != 8 or not data["specials"] is Array or data["specials"].size() != 12 or not data["inventory"] is Array or not data["knownSpells"] is Array:
		return null
	var numeric_values: Dictionary = {}
	for field: String in ["gender", "level", "experience", "ageDays", "toHit", "dodge", "missile", "handToHand", "damageBonus", "armor", "magicResistance", "movement", "maximumMovement", "normalAttacks", "attacksRemaining", "spellcasterType", "spellPoints", "maximumSpellPoints", "load", "maximumLoad"]:
		var value := _signed_integer(data[field])
		if value == -100_000:
			return null
		numeric_values[field] = value
	for field: String in ["attackBonus", "maximumSpellAttacks", "prestigePenalty"]:
		var value := _signed_integer(data.get(field, 0))
		if value == -100_000:
			return null
		numeric_values[field] = value
	var loaded_conditions := ConditionSet.from_data(data["conditions"], ConditionSet.CHARACTER_COUNT)
	var loaded_money := WealthState.from_data(data["money"])
	if loaded_conditions == null or loaded_money == null:
		return null
	var attributes: Array[int] = []
	var saves: Array[int] = []
	var specials: Array[int] = []
	for value: Variant in data["attributes"]:
		var parsed := _signed_integer(value)
		if parsed == -100_000:
			return null
		attributes.append(parsed)
	for value: Variant in data["saves"]:
		var parsed := _signed_integer(value)
		if parsed == -100_000:
			return null
		saves.append(parsed)
	for value: Variant in data["specials"]:
		var parsed := _signed_integer(value)
		if parsed == -100_000:
			return null
		specials.append(parsed)
	var items: Array[ItemInstance] = []
	for item_data: Variant in data["inventory"]:
		var item := ItemInstance.from_data(item_data)
		if item == null:
			return null
		items.append(item)
	var spells: Array[String] = []
	for spell_id: Variant in data["knownSpells"]:
		if not spell_id is String or spell_id.is_empty():
			return null
		spells.append(spell_id)
	result.race_id = data["raceId"]
	result.caste_id = data["casteId"]
	result.gender = numeric_values["gender"]
	result.portrait_id = String(data.get("portraitId", ""))
	result.combat_icon_id = String(data.get("combatIconId", ""))
	result.level = numeric_values["level"]
	result.experience = numeric_values["experience"]
	result.age_days = numeric_values["ageDays"]
	result.brawn = attributes[0]
	result.knowledge = attributes[1]
	result.judgment = attributes[2]
	result.agility = attributes[3]
	result.vitality = attributes[4]
	result.luck = attributes[5]
	result.to_hit = numeric_values["toHit"]
	result.dodge = numeric_values["dodge"]
	result.missile = numeric_values["missile"]
	result.hand_to_hand = numeric_values["handToHand"]
	result.damage_bonus = numeric_values["damageBonus"]
	result.armor = numeric_values["armor"]
	result.magic_resistance = numeric_values["magicResistance"]
	result.movement = numeric_values["movement"]
	result.maximum_movement = numeric_values["maximumMovement"]
	result.normal_attacks = numeric_values["normalAttacks"]
	result.attack_bonus = numeric_values["attackBonus"]
	result.attacks_remaining = numeric_values["attacksRemaining"]
	result.maximum_spell_attacks = numeric_values["maximumSpellAttacks"]
	result.spellcaster_type = numeric_values["spellcasterType"]
	result.spell_points = numeric_values["spellPoints"]
	result.maximum_spell_points = numeric_values["maximumSpellPoints"]
	result.carried_load = numeric_values["load"]
	result.maximum_load = numeric_values["maximumLoad"]
	result.prestige_penalty = numeric_values["prestigePenalty"]
	result.conditions = loaded_conditions
	result.money = loaded_money
	result._saves = saves
	result._specials = specials
	result._inventory = items
	result._known_spells = spells
	return result

static func finalize_character(spec: CharacterCreationSpec) -> PlayerIntent:
	var intent := PlayerIntent.new(Kind.FINALIZE_CHARACTER)
	if spec != null:
		intent.party_members = [spec]
	return intent

static func _signed_integer(input: Variant) -> int:
	if input is int:
		return input
	if input is float and is_equal_approx(input, round(input)):
		return int(input)
	return -100_000

func set_quest_value(quest_id: int, value: int) -> bool:
	if quest_id < 0 or quest_id >= 100:
		return false
	_quest_values[quest_id] = clampi(value, -32_768, 32_767)
	return true

func adjust_quest_value(quest_id: int, amount: int) -> int:
	if not set_quest_value(quest_id, quest_value(quest_id) + amount):
		return 0
	return quest_value(quest_id)

func set_selected_character_ids(ids: Array[String]) -> bool:
	var known: Dictionary = {}
	for character: CharacterState in party.characters():
		known[character.id] = true
	var unique: Array[String] = []
	for id: String in ids:
		if not known.has(id) or unique.has(id):
			return false
		unique.append(id)
	_selected_character_ids = unique
	return true

func selected_characters(living_only: bool = false) -> Array[CharacterState]:
	var result: Array[CharacterState] = []
	for id: String in _selected_character_ids:
		var character := party.character_by_id(id)
		if character != null and (not living_only or character.current_health > 0):
			result.append(character)
	return result

func set_turn_order(order: Array[String]) -> void:
	_turn_order = order.duplicate()
	turn_index = 0

func set_value(index: int, amount: int) -> bool:
	if index < 0 or index >= _values.size():
		return false
	_values[index] = clampi(amount, -32_768, 32_767)
	return true

func decay_positive() -> Array[int]:
	var expired: Array[int] = []
	for index: int in _values.size():
		if _values[index] <= 0:
			continue
		_values[index] -= 1
		if _values[index] == 0:
			expired.append(index)
	return expired

static func from_data(data: Variant, expected_count: int = 0) -> ConditionSet:
	if not data is Dictionary or not data.has("count") or not data.has("values"):
		return null
	var count := _integer(data["count"])
	if count < 1 or (expected_count > 0 and count != expected_count) or not data["values"] is Array or data["values"].size() != count:
		return null
	var result := ConditionSet.new(count)
	for index: int in count:
		var amount := _signed_integer(data["values"][index])
		if amount < -32_768 or amount > 32_767:
			return null
		result._values[index] = amount
	return result

static func _integer(input: Variant) -> int:
	if input is int:
		return input
	if input is float and is_equal_approx(input, round(input)):
		return int(input)
	return -1

func _init(count: int = CHARACTER_COUNT) -> void:
	_values.resize(maxi(1, count))
	_values.fill(0)

class_name RealmzRuntimeApi
extends RefCounted

const SUPPORTED_SAFE_CAPABILITIES: Array[String] = [
	"core.combat.start",
	"core.economy.grant-treasure",
	"core.economy.take-gold",
	"core.inventory.grant-item",
	"core.party.camp",
	"core.presentation.choice",
	"core.presentation.text",
	"core.state.read",
	"core.state.write",
	"core.time.advance",
]

var _content: RealmzContent
var _game_state: GameState
var _rng: RealmzRng
var _action_state: ScenarioActionState
var _rules: RealmzRules
var _character_operations: ClassicCharacterOperations
var _combat_operations: ClassicCombatOperations
var _control_flow_operations: ClassicControlFlowOperations
var _inventory_operations: ClassicInventoryOperations


func _init(content: RealmzContent, game_state: GameState, rng: RealmzRng, action_state: ScenarioActionState, rules: RealmzRules = null) -> void:
	_content = content
	_game_state = game_state
	_rng = rng
	_action_state = action_state
	_rules = rules if rules != null else RealmzRules.new()
	_character_operations = ClassicCharacterOperations.new(_content, _game_state, _rng, _rules)
	_combat_operations = ClassicCombatOperations.new(_content, _game_state, _rules)
	_control_flow_operations = ClassicControlFlowOperations.new(_content, _game_state)
	_inventory_operations = ClassicInventoryOperations.new(_content, _game_state, _rules)


func execute_classic(action: ClassicActionDefinition, request_id: String, context: Dictionary = {}) -> ScenarioRuntimeOperationResult:
	match action.opcode:
		-23, 23:
			return _mutate_random_region(action, action.opcode == -23)
		-14, 14:
			return _request_character_selection(action, request_id, action.opcode == -14)
		1:
			var message_id := absi(action.operand_id)
			var message := _content.message_by_id(message_id)
			if message == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Classic opcode 1 references unavailable message %d." % action.operand_id)
			var event := DomainEvent.new(&"message_shown", {"messageId": message_id, "text": message.text, "source": "classic", "classicClick": action.operand_id > 0})
			if action.operand_id > 0:
				var request := InteractionRequest.new(request_id, &"acknowledge", {"prompt": message.text, "messageId": message_id, "presentation": "classic-textbox"})
				return ScenarioRuntimeOperationResult.waiting(request, {"kind": "classic-textbox", "messageId": message_id}, [event])
			return ScenarioRuntimeOperationResult.completed(null, [event])
		4:
			var encounter := _content.simple_encounter_by_id(action.operand_id)
			if encounter == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_encounter", "Classic opcode 4 references unavailable Simple Encounter %d." % action.operand_id)
			var prompt := _content.message_by_id(absi(encounter.prompt_message_id))
			if prompt == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Simple Encounter %d references unavailable prompt message %d." % [encounter.id, encounter.prompt_message_id])
			var options: Array[Dictionary] = []
			var option_indexes: Array[int] = []
			var responses := encounter.responses()
			for option_index: int in responses.size():
				if _game_state.simple_option_is_eliminated(encounter.id, option_index):
					continue
				var response: SimpleEncounterResponse = responses[option_index]
				options.append({"id": response.id, "label": response.label})
				option_indexes.append(option_index)
			if options.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"encounter_has_no_options", "Simple Encounter %d has no remaining responses." % encounter.id)
			var request := InteractionRequest.new(request_id, &"encounter_choice", {"encounterKind": "simple", "encounterId": encounter.id, "prompt": prompt.text, "options": options, "canBackOut": encounter.can_back_out})
			return ScenarioRuntimeOperationResult.waiting(request, {"kind": "classic-simple-encounter", "encounterId": encounter.id, "gosub": action.gosub, "optionIndexes": option_indexes})
		5:
			return _request_complex_encounter(action, request_id)
		3:
			return _request_classic_choice(action, request_id)
		6:
			return _request_shop(action.operand_id, request_id)
		7:
			return _control_flow_operations.replace_scenario_program(action, context)
		8:
			return _control_flow_operations.branch_to_trigger_program(action, context)
		2, 48, 56, 107:
			return _start_classic_battle(action, request_id)
		9:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"sound_requested", {"soundId": absi(action.operand_id), "waitForCompletion": action.operand_id < 0, "source": "classic"})])
		10:
			return _grant_treasure(action.operand_id)
		11:
			var experience := maxi(0, action.operand_id)
			for character: CharacterState in _game_state.party.characters():
				if character.current_health > 0:
					character.experience += experience
			return ScenarioRuntimeOperationResult.completed(experience, [DomainEvent.new(&"experience_granted", {"amount": experience, "target": "living-party", "source": "classic"})])
		12:
			return _mutate_tile(action)
		13:
			return _mutate_triggers(action)
		15, 16:
			return _apply_health(action, action.opcode == 16)
		17, 18:
			return _character_operations.apply_scenario_spell(action, action.opcode == 18)
		19:
			return _show_random_message(action)
		20:
			return _move_between_maps(action, false, true)
		21:
			return _branch_on_item(action)
		22:
			return _mutate_items(action)
		24:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"action_point_kept", {"triggerId": String(context.get("triggerId", "")), "source": "classic"})], {"kind": "finish"})
		25:
			var trigger_id := String(context.get("triggerId", ""))
			if trigger_id.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"missing_trigger_context", "Classic opcode 25 requires an Action Point origin.")
			_game_state.world.disable_trigger(trigger_id)
			return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"trigger_disabled", {"triggerId": trigger_id, "source": "classic"})])
		26:
			return ScenarioRuntimeOperationResult.waiting(InteractionRequest.new(request_id, &"acknowledge", {"prompt": "Continue", "soundId": 30005}), {"kind": "classic-acknowledge"})
		27:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"picture_requested", {"pictureId": absi(action.operand_id), "source": "classic"})])
		28:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"map_redraw_requested", {"source": "classic"})])
		29:
			var map := _content.world.map_by_type_and_index(&"land", absi(action.operand_id))
			if map == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_map", "Classic opcode 29 references unavailable land map %d." % action.operand_id)
			_game_state.world.acquire_map(map.id)
			return ScenarioRuntimeOperationResult.completed(map.id, [DomainEvent.new(&"map_acquired", {"mapId": map.id, "display": action.operand_id < 0})])
		30:
			return _filter_character_selection(action)
		31:
			return _request_character_ability(action, request_id)
		32:
			return _request_temple(action, request_id)
		33:
			var values := action.extra_code
			var amount := absi(action.operand_id) if values.is_empty() else absi(values[0])
			var kind := WealthState.Kind.GOLD if values.size() < 2 else clampi(values[1], WealthState.Kind.GOLD, WealthState.Kind.JEWELRY) as WealthState.Kind
			var paid := _rules.economy.take(_game_state.party, amount, kind)
			return ScenarioRuntimeOperationResult.completed(paid, [DomainEvent.new(&"wealth_taken", {"amount": amount, "kind": kind, "paid": paid, "source": "classic"})])
		34:
			return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"encounter_loop_finished", {"source": "classic"})], {"kind": "finish"})
