extends RealmzTestCase

const FIXTURE_PATH: String = "res://tests/fixtures/packages/realmz2-synthetic-fixture.realmz2"


func run() -> void:
	var loaded := PackageRepository.new().load_package(FIXTURE_PATH)
	assert_true(loaded.is_ok(), "topology fixture loads: %s" % loaded.error_message)
	if not loaded.is_ok():
		return
	var world_state := WorldState.new()
	var land := loaded.content.world.map_by_id("land:0")
	var hidden_cell := land.topology.cell_at(Vector2i(0, 1))
	var hidden_feature := hidden_cell.feature_by_kind(&"secret")
	assert_not_null(hidden_feature, "land secret is an explicit feature")
	assert_equal(land.topology.probe_entry(hidden_cell.coordinate, Vector2i.LEFT, world_state).reason, &"secret_hidden", "hidden land secret blocks movement through topology")
	world_state.discover_secret(hidden_feature.id)
	assert_true(land.topology.probe_entry(hidden_cell.coordinate, Vector2i.LEFT, world_state).allowed, "discovery overlay changes the same topology query")
	assert_true(land.topology.probe_land_entry(Vector2i.ZERO, world_state).allowed, "land entry checks the destination tile without inventing a diagonal edge")
	assert_equal(land.topology.probe_entry(Vector2i.ZERO, Vector2i(-1, -1), world_state).reason, &"invalid_direction", "edge-based topology entry remains cardinal for dungeons and pathfinding")
	assert_equal(land.topology.visible_cells(Vector2i(1, 1), 8, world_state, false).size(), 9, "non-LOS land view derives every visible cell from topology")

	var dungeon := loaded.content.world.map_by_id("dungeon:0")
	assert_equal(dungeon.topology.probe_entry(Vector2i.ZERO, Vector2i.LEFT, world_state).reason, &"terrain_blocked", "dungeon wall blocks movement")
	var door_probe := dungeon.topology.probe_entry(Vector2i(1, 0), Vector2i.LEFT, world_state)
	assert_true(door_probe.allowed, "dungeon door permits the Classic movement attempt")
	assert_equal(door_probe.door_id, "dungeon:0:cell:1,0:door", "movement and rendering share the explicit door identity")
	assert_equal(dungeon.topology.find_path(Vector2i(2, 0), Vector2i(1, 0), world_state), [Vector2i(1, 0)], "pathfinding traverses the same explicit door edge")
	assert_true(dungeon.topology.find_path(Vector2i(2, 0), Vector2i.ZERO, world_state).is_empty(), "pathfinding cannot route into blocked wall terrain")
	var secret_probe := dungeon.topology.probe_entry(Vector2i(0, 1), Vector2i.RIGHT, world_state)
	assert_true(secret_probe.allowed, "matching directional secret passage permits entry")
	assert_equal(secret_probe.secret_id, "dungeon:0:cell:0,1:secret:east", "secret passage returns its stable overlay identity")
	assert_false(dungeon.topology.probe_entry(Vector2i(0, 1), Vector2i.UP, world_state).allowed, "nonmatching secret direction remains blocked")

	world_state.open_door(door_probe.door_id)
	world_state.mark_visited("dungeon:0", Vector2i(1, 0))
	var restored := WorldState.from_data(world_state.to_data())
	assert_not_null(restored, "world overlays serialize as typed state")
	assert_true(restored.door_is_open(door_probe.door_id), "door overlay survives serialization")
	assert_true(restored.secret_is_discovered(hidden_feature.id), "secret discovery survives serialization")
	assert_true(restored.was_visited("dungeon:0", Vector2i(1, 0)), "minimap visitation survives serialization")

param(
    [string]$SourcePng = "",
    [string]$SpriteCookAssetId = "",
    [string]$SpriteCookLabel = "",
    [switch]$RebuildFromCommittedSurface
)

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Drawing
$toolRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent (Split-Path -Parent $toolRoot)
$outputRoot = Join-Path $repoRoot "src/presentation/assets/ui"
$committedSurfacePath = Join-Path $outputRoot "classic-charcoal-slate.png"
$committedManifestPath = Join-Path $outputRoot "spritecook-assets.json"
$stagingRoot = Join-Path ([IO.Path]::GetTempPath()) ("realmz2-ui-surfaces-" + [Guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $stagingRoot | Out-Null

function Save-Png([Drawing.Bitmap]$bitmap, [string]$path) {
    $bitmap.Save($path, [Drawing.Imaging.ImageFormat]::Png)
    $bytes = [IO.File]::ReadAllBytes($path)
    if ($bytes.Length -lt 24 -or [Text.Encoding]::ASCII.GetString($bytes, 1, 3) -ne "PNG") {
        throw "Generated surface is not a valid PNG: $path"
    }
}

function New-SeamlessTile([Drawing.Bitmap]$source, [int]$blendWidth = 64) {
    if ($source.Width -lt $blendWidth * 2 -or $source.Height -lt $blendWidth * 2) {
        throw "The selected surface is too small for a $blendWidth-pixel edge feather."
    }
    $horizontal = [Drawing.Bitmap]$source.Clone()
    for ($y = 0; $y -lt $source.Height; $y++) {
        for ($offset = 0; $offset -lt $blendWidth; $offset++) {
            $opposite = $source.Width - 1 - $offset
            $weight = 0.25 * (1.0 + [Math]::Cos([Math]::PI * $offset / $blendWidth))
            $left = $source.GetPixel($offset, $y)
            $right = $source.GetPixel($opposite, $y)
            $horizontal.SetPixel($offset, $y, [Drawing.Color]::FromArgb(
                [int][Math]::Round($left.A * (1.0 - $weight) + $right.A * $weight),
                [int][Math]::Round($left.R * (1.0 - $weight) + $right.R * $weight),
                [int][Math]::Round($left.G * (1.0 - $weight) + $right.G * $weight),
                [int][Math]::Round($left.B * (1.0 - $weight) + $right.B * $weight)
            ))
            $horizontal.SetPixel($opposite, $y, [Drawing.Color]::FromArgb(
                [int][Math]::Round($right.A * (1.0 - $weight) + $left.A * $weight),
                [int][Math]::Round($right.R * (1.0 - $weight) + $left.R * $weight),
                [int][Math]::Round($right.G * (1.0 - $weight) + $left.G * $weight),
                [int][Math]::Round($right.B * (1.0 - $weight) + $left.B * $weight)
            ))
        }
    }
    $result = [Drawing.Bitmap]$horizontal.Clone()
    try {
        for ($x = 0; $x -lt $horizontal.Width; $x++) {
            for ($offset = 0; $offset -lt $blendWidth; $offset++) {
                $opposite = $horizontal.Height - 1 - $offset
                $weight = 0.25 * (1.0 + [Math]::Cos([Math]::PI * $offset / $blendWidth))
                $top = $horizontal.GetPixel($x, $offset)
                $bottom = $horizontal.GetPixel($x, $opposite)
                $result.SetPixel($x, $offset, [Drawing.Color]::FromArgb(
                    [int][Math]::Round($top.A * (1.0 - $weight) + $bottom.A * $weight),
                    [int][Math]::Round($top.R * (1.0 - $weight) + $bottom.R * $weight),
                    [int][Math]::Round($top.G * (1.0 - $weight) + $bottom.G * $weight),
                    [int][Math]::Round($top.B * (1.0 - $weight) + $bottom.B * $weight)
                ))
                $result.SetPixel($x, $opposite, [Drawing.Color]::FromArgb(
                    [int][Math]::Round($bottom.A * (1.0 - $weight) + $top.A * $weight),
                    [int][Math]::Round($bottom.R * (1.0 - $weight) + $top.R * $weight),
                    [int][Math]::Round($bottom.G * (1.0 - $weight) + $top.G * $weight),
                    [int][Math]::Round($bottom.B * (1.0 - $weight) + $top.B * $weight)
                ))
            }
        }
    }
    finally { $horizontal.Dispose() }
    return $result
}

try {
    $selectedAsset = $null
    $basePath = Join-Path $stagingRoot "classic-charcoal-slate.png"
    if ($RebuildFromCommittedSurface) {
        if (-not [string]::IsNullOrWhiteSpace($SourcePng) -or -not [string]::IsNullOrWhiteSpace($SpriteCookAssetId) -or -not [string]::IsNullOrWhiteSpace($SpriteCookLabel)) {
            throw "RebuildFromCommittedSurface cannot be combined with source-import arguments."
        }
        if (-not (Test-Path -LiteralPath $committedSurfacePath) -or -not (Test-Path -LiteralPath $committedManifestPath)) {
            throw "The committed selected surface and manifest are required for an offline rebuild."
        }
        $existingManifest = Get-Content -Raw -LiteralPath $committedManifestPath | ConvertFrom-Json
        $selectedAsset = [ordered]@{
