$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot
if (-not (Test-Path -LiteralPath $ManifestPath)) {
    throw "Corpus manifest does not exist: $ManifestPath"
}
if ([string]::IsNullOrWhiteSpace($GodotPath)) {
    $godotCommand = Get-Command Godot_v4.7.1-stable_win64_console.exe -ErrorAction SilentlyContinue
    if ($null -eq $godotCommand) {
        $godotCommand = Get-Command godot -ErrorAction Stop
    }
    $GodotPath = $godotCommand.Source
}

$manifest = Get-Content -Raw -LiteralPath $ManifestPath | ConvertFrom-Json
if ($manifest.schemaVersion -ne 1 -or $null -eq $manifest.campaigns -or $manifest.campaigns.Count -eq 0) {
    throw "Corpus manifest must use schemaVersion 1 and declare at least one campaign."
}

$failures = @()
foreach ($campaign in $manifest.campaigns) {
    foreach ($field in @("id", "package", "route", "report")) {
        if ([string]::IsNullOrWhiteSpace($campaign.$field)) {
            throw "Corpus entry is missing $field."
        }
    }
    foreach ($inputPath in @($campaign.package, $campaign.route)) {
        if (-not (Test-Path -LiteralPath $inputPath)) {
            throw "Corpus input does not exist: $inputPath"
        }
    }
    $reportDirectory = Split-Path -Parent $campaign.report
    if (-not [string]::IsNullOrWhiteSpace($reportDirectory)) {
        New-Item -ItemType Directory -Force -Path $reportDirectory | Out-Null
    }
    Write-Host "CERTIFY $($campaign.id)"
    & $GodotPath --headless --path $repoRoot --script res://tools/route_acceptance.gd -- $campaign.package $campaign.route $campaign.report
    if ($LASTEXITCODE -ne 0) {
        $failures += $campaign.id
    }
}

if ($failures.Count -gt 0) {
    throw "Campaign route certification failed: $($failures -join ', ')"
}
Write-Host "Corpus route certification passed for $($manifest.campaigns.Count) campaign(s)."

param(
    [Parameter(Mandatory = $true)]
    [string]$SourcePackage,
    [Parameter(Mandatory = $true)]
    [string]$DestinationPackage
)

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.IO.Compression

$sourcePath = (Resolve-Path -LiteralPath $SourcePackage).Path
$destinationPath = [System.IO.Path]::GetFullPath($DestinationPackage)
$destinationDirectory = [System.IO.Path]::GetDirectoryName($destinationPath)
[System.IO.Directory]::CreateDirectory($destinationDirectory) | Out-Null
if ([System.IO.File]::Exists($destinationPath)) {
    [System.IO.File]::Delete($destinationPath)
}

$sourceStream = [System.IO.File]::OpenRead($sourcePath)
$destinationStream = [System.IO.File]::Open($destinationPath, [System.IO.FileMode]::CreateNew)
try {
    $sourceArchive = [System.IO.Compression.ZipArchive]::new($sourceStream, [System.IO.Compression.ZipArchiveMode]::Read, $false)
    $destinationArchive = [System.IO.Compression.ZipArchive]::new($destinationStream, [System.IO.Compression.ZipArchiveMode]::Create, $true)
    try {
        foreach ($sourceEntry in ($sourceArchive.Entries | Sort-Object FullName)) {
            $input = $sourceEntry.Open()
            $buffer = [System.IO.MemoryStream]::new()
            try {
                $input.CopyTo($buffer)
                [byte[]]$bytes = $buffer.ToArray()
            }
            finally {
                $buffer.Dispose()
                $input.Dispose()
            }
            if ($sourceEntry.FullName -eq "content.json") {
                $utf8 = [System.Text.UTF8Encoding]::new($false)
                $text = $utf8.GetString($bytes)
                if (-not $text.Contains("Fixture Wand")) {
                    throw "The positive fixture does not contain the expected synthetic mutation target."
                }
                $bytes = $utf8.GetBytes($text.Replace("Fixture Wand", "Fixture Band"))
            }
            $destinationEntry = $destinationArchive.CreateEntry($sourceEntry.FullName, [System.IO.Compression.CompressionLevel]::Optimal)
            $destinationEntry.LastWriteTime = $sourceEntry.LastWriteTime
            $output = $destinationEntry.Open()
            try {
                $output.Write($bytes, 0, $bytes.Length)
            }
            finally {
                $output.Dispose()
            }
        }
    }
    finally {
        $destinationArchive.Dispose()
        $sourceArchive.Dispose()
    }
}
finally {
    $destinationStream.Dispose()
    $sourceStream.Dispose()
}

