static func from_data(data: Variant) -> ItemInstance:
	if not data is Dictionary:
		return null
	for field: String in ["id", "definitionId", "equipped", "identified", "charges"]:
		if not data.has(field):
			return null
	if not data["id"] is String or data["id"].is_empty() or not data["definitionId"] is String or data["definitionId"].is_empty() or not data["equipped"] is bool or not data["identified"] is bool:
		return null
	var loaded_charges := _integer(data["charges"])
	if loaded_charges < -1 or loaded_charges > 32_767:
		return null
	return ItemInstance.new(data["id"], data["definitionId"], loaded_charges, data["equipped"], data["identified"])

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

func set_total_minutes(minutes: int) -> bool:
	if minutes < 0:
		return false
	_total_minutes = minutes
	return true

static func _json_safe(value: Variant, depth: int) -> bool:
	if depth > 32:
		return false
	if value == null or value is bool or value is int or value is float or value is String:
		return true
	if value is Array:
		if value.size() > 4096:
			return false
		for child: Variant in value:
			if not _json_safe(child, depth + 1):
				return false
		return true
	if value is Dictionary:
		if value.size() > 4096:
			return false
		for key: Variant in value.keys():
			if not key is String or not _json_safe(value[key], depth + 1):
				return false
		return true
	return false

func next_instance_id(prefix: String) -> String:
