func run() -> void:
	var map_presenter := ClassicMapPresenter.new()
	assert_equal(map_presenter.cell_size, 32.0, "Classic land atlases render at their native 32-pixel cell size")
	map_presenter._party_rect = Rect2(64, 64, 32, 32)
