class_name RealmzClock
extends RefCounted

const MINUTES_PER_DAY: int = 1_440

var _total_minutes: int = 0


func _init(initial_total_minutes: int = 0) -> void:
	_total_minutes = maxi(initial_total_minutes, 0)


func advance_minutes(minutes: int) -> bool:
	if minutes < 0:
		return false
	_total_minutes += minutes
	return true


func set_total_minutes(minutes: int) -> bool:
	if minutes < 0:
		return false
	_total_minutes = minutes
	return true


func total_minutes() -> int:
	return _total_minutes


func day() -> int:
	return 1 + floori(float(_total_minutes) / float(MINUTES_PER_DAY))


func hour() -> int:
	return floori(float(_total_minutes % MINUTES_PER_DAY) / 60.0)


func minute() -> int:
	return _total_minutes % 60


func to_data() -> Dictionary:
	return {"totalMinutes": _total_minutes}


static func from_data(data: Variant) -> RealmzClock:
	if not data is Dictionary or not data.has("totalMinutes"):
		return null
	var minutes: int = data["totalMinutes"] if data["totalMinutes"] is int else int(data["totalMinutes"]) if data["totalMinutes"] is float and is_equal_approx(data["totalMinutes"], round(data["totalMinutes"])) else -1
	if minutes < 0:
		return null
	return RealmzClock.new(minutes)

class_name ClockRules
extends RefCounted

var _conditions: ConditionRules


func _init(condition_rules: ConditionRules) -> void:
	_conditions = condition_rules


func change_fatigue(party: PartyState, amount: int) -> int:
	party.fatigue = clampi(party.fatigue + amount, 4, 135)
	return party.fatigue


func advance_minutes(state: GameState, minutes: int, condition_ticks: int = 0) -> Array[DomainEvent]:
	state.clock.advance_minutes(maxi(0, minutes))
	var events: Array[DomainEvent] = [DomainEvent.new(&"time_advanced", {"minutes": maxi(0, minutes), "day": state.clock.day(), "hour": state.clock.hour()})]
	for tick: int in condition_ticks:
		events.append_array(_conditions.tick_party(state.party))
	return events


func camp(state: GameState, hours: int = 8) -> Array[DomainEvent]:
	var events := advance_minutes(state, maxi(1, hours) * 60, maxi(1, hours))
	state.party.fatigue = 4
	for character: CharacterState in state.party.characters():
		if character.current_health > 0:
			character.current_health = mini(character.maximum_health, character.current_health + maxi(1, hours))
			character.spell_points = character.maximum_spell_points
	events.append(DomainEvent.new(&"party_camped", {"hours": maxi(1, hours)}))
	return events

