	var equipment_character_ids: Array = _equipment_storage.keys()
	equipment_character_ids.sort()
	for character_id: Variant in equipment_character_ids:
		var item_data: Array[Dictionary] = []
		for item: ItemInstance in _equipment_storage[character_id]:
			item_data.append(item.to_data())
		equipment_data[character_id] = item_data
	return {"mapId": map_id, "x": coordinate.x, "y": coordinate.y, "characters": character_data, "pooledWealth": pooled_wealth.to_data(), "bankedWealth": banked_wealth.to_data(), "fatigue": fatigue, "conditions": conditions.to_data(), "allies": ally_data, "storage": storage_data, "equipmentStorageActive": equipment_storage_active, "equipmentStorage": equipment_data, "equipmentWealth": _equipment_wealth.to_data()}


static func from_data(data: Variant) -> PartyState:
	if not data is Dictionary:
		return null
	for field: String in ["mapId", "x", "y", "characters"]:
		if not data.has(field):
			return null
	if not data["mapId"] is String or data["mapId"].is_empty():
		return null
	var x := _integer(data["x"])
	var y := _integer(data["y"])
	if x < 0 or y < 0 or not data["characters"] is Array:
		return null
	var loaded_characters: Array[CharacterState] = []
	for character_data: Variant in data["characters"]:
		var character := CharacterState.from_data(character_data)
		if character == null:
			return null
		loaded_characters.append(character)
	if loaded_characters.is_empty():
		return null
	var result := PartyState.new(data["mapId"], Vector2i(x, y), loaded_characters)
	if not data.has("pooledWealth"):
		return result
	for field: String in ["pooledWealth", "fatigue", "conditions", "allies", "storage"]:
		if not data.has(field):
			return null
	var wealth := WealthState.from_data(data["pooledWealth"])
	var banked := WealthState.from_data(data.get("bankedWealth", {"gold": 0, "gems": 0, "jewelry": 0}))
	var party_conditions := ConditionSet.from_data(data["conditions"], ConditionSet.PARTY_COUNT)
	var loaded_fatigue := _integer(data["fatigue"])
	if wealth == null or banked == null or party_conditions == null or loaded_fatigue < 4 or loaded_fatigue > 135 or not data["allies"] is Array or not data["storage"] is Array:
		return null
	var loaded_allies: Array[MonsterState] = []
	for ally_data: Variant in data["allies"]:
		var ally := MonsterState.from_data(ally_data)
		if ally == null:
			return null
		loaded_allies.append(ally)
	var stored_items: Array[ItemInstance] = []
	for item_data: Variant in data["storage"]:
		var item := ItemInstance.from_data(item_data)
		if item == null:
			return null
		stored_items.append(item)
	result.pooled_wealth = wealth
	result.banked_wealth = banked
	result.fatigue = loaded_fatigue
	result.conditions = party_conditions
	result._allies = loaded_allies
	result._storage = stored_items
	if data.has("equipmentStorageActive"):
		if not data["equipmentStorageActive"] is bool or not data.get("equipmentStorage") is Dictionary:
			return null
		var equipment_wealth := WealthState.from_data(data.get("equipmentWealth"))
		if equipment_wealth == null:
			return null
		var equipment_storage: Dictionary = {}
		for character_id: Variant in data["equipmentStorage"]:
			if not character_id is String or result.character_by_id(character_id) == null or not data["equipmentStorage"][character_id] is Array:
				return null
			var equipment_items: Array[ItemInstance] = []
			for item_data: Variant in data["equipmentStorage"][character_id]:
				var item := ItemInstance.from_data(item_data)
				if item == null:
					return null
				equipment_items.append(item)
			equipment_storage[character_id] = equipment_items
		result.equipment_storage_active = data["equipmentStorageActive"]
		result._equipment_storage = equipment_storage
		result._equipment_wealth = equipment_wealth
	return result


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

class_name RandomRegionState
extends RefCounted

var id: String
var chance_ten_thousand: int
var battle_minimum: int
var battle_maximum: int
var _random_door_percents: Array[int]


func _init(region_id: String, chance: int, battle_min: int, battle_max: int, door_percents: Array[int] = []) -> void:
	id = region_id
	chance_ten_thousand = chance
	battle_minimum = battle_min
	battle_maximum = battle_max
	_random_door_percents = door_percents.duplicate()


func random_door_percents() -> Array[int]:
	return _random_door_percents.duplicate()


func consume_random_door(index: int) -> void:
	if index >= 0 and index < _random_door_percents.size() and _random_door_percents[index] > 0:
		_random_door_percents[index] = 0


func to_data() -> Dictionary:
	return {"id": id, "chanceTenThousand": chance_ten_thousand, "battleMinimum": battle_minimum, "battleMaximum": battle_maximum, "randomDoorPercent": _random_door_percents.duplicate()}


static func from_data(data: Variant) -> RandomRegionState:
	if not data is Dictionary:
		return null
	for field: String in ["id", "chanceTenThousand", "battleMinimum", "battleMaximum", "randomDoorPercent"]:
		if not data.has(field):
			return null
	if not data["id"] is String or data["id"].is_empty():
		return null
	var chance := _signed_integer(data["chanceTenThousand"])
	var battle_min := _signed_integer(data["battleMinimum"])
	var battle_max := _signed_integer(data["battleMaximum"])
	if chance == -100_000 or battle_min == -100_000 or battle_max == -100_000 or not data["randomDoorPercent"] is Array or data["randomDoorPercent"].size() != 3:
		return null
	var door_percents: Array[int] = []
	for value: Variant in data["randomDoorPercent"]:
		var percent := _signed_integer(value)
		if percent == -100_000:
			return null
		door_percents.append(percent)
	return RandomRegionState.new(data["id"], chance, battle_min, battle_max, door_percents)


static func _signed_integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

class_name WealthState
extends RefCounted

enum Kind {
	GOLD,
	GEMS,
	JEWELRY,
}

var gold: int = 0
var gems: int = 0
var jewelry: int = 0


func _init(gold_amount: int = 0, gem_amount: int = 0, jewelry_amount: int = 0) -> void:
	gold = maxi(0, gold_amount)
	gems = maxi(0, gem_amount)
	jewelry = maxi(0, jewelry_amount)


func amount(kind: Kind) -> int:
	match kind:
		Kind.GOLD:
			return gold
		Kind.GEMS:
			return gems
		Kind.JEWELRY:
			return jewelry
	return 0


func set_amount(kind: Kind, value: int) -> void:
	match kind:
		Kind.GOLD:
			gold = maxi(0, value)
		Kind.GEMS:
			gems = maxi(0, value)
		Kind.JEWELRY:
			jewelry = maxi(0, value)


func add(kind: Kind, value: int) -> void:
	set_amount(kind, amount(kind) + value)


func to_data() -> Dictionary:
	return {"gold": gold, "gems": gems, "jewelry": jewelry}


static func from_data(data: Variant) -> WealthState:
	if not data is Dictionary:
		return null
	var amounts: Array[int] = []
	for field: String in ["gold", "gems", "jewelry"]:
		if not data.has(field):
			return null
		var value := _integer(data[field])
		if value < 0:
			return null
		amounts.append(value)
	return WealthState.new(amounts[0], amounts[1], amounts[2])


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

class_name WorldState
extends RefCounted

var _terrain_overrides: Dictionary = {}
var _door_states: Dictionary = {}
var _discovered_secrets: Dictionary = {}
var _disabled_triggers: Dictionary = {}
var _visited_cells: Dictionary = {}
var _trigger_chances: Dictionary = {}
var _acquired_maps: Dictionary = {}
var _random_regions: Dictionary = {}
var _map_darkness: Dictionary = {}


func terrain_for(map_id: String, cell: MapCell) -> String:
	return String(_terrain_overrides.get(_cell_key(map_id, cell.coordinate), cell.terrain_id))


func replace_terrain(map_id: String, coordinate: Vector2i, terrain_id: String) -> void:
	_terrain_overrides[_cell_key(map_id, coordinate)] = terrain_id


func open_door(door_id: String) -> void:
	if not door_id.is_empty():
		_door_states[door_id] = "open"


func door_is_open(door_id: String, initially_open: bool = false) -> bool:
	if door_id.is_empty():
		return true
	return _door_states.get(door_id, "open" if initially_open else "closed") == "open"


func discover_secret(secret_id: String) -> void:
	if not secret_id.is_empty():
		_discovered_secrets[secret_id] = true


func secret_is_discovered(secret_id: String, initially_discovered: bool = false) -> bool:
	return secret_id.is_empty() or initially_discovered or _discovered_secrets.has(secret_id)


func disable_trigger(trigger_id: String) -> void:
	_disabled_triggers[trigger_id] = true


func trigger_is_disabled(trigger_id: String) -> bool:
	return _disabled_triggers.has(trigger_id)


func set_trigger_chance(trigger_id: String, percent: int) -> void:
	if trigger_id.is_empty():
		return
	_trigger_chances[trigger_id] = clampi(percent, -1, 100)
	if percent < 0:
		disable_trigger(trigger_id)


func trigger_chance(trigger_id: String, authored_percent: int) -> int:
	return int(_trigger_chances.get(trigger_id, authored_percent))


func acquire_map(map_id: String) -> void:
	if not map_id.is_empty():
		_acquired_maps[map_id] = true


func has_map(map_id: String) -> bool:
	return _acquired_maps.has(map_id)


func acquired_map_ids() -> Array[String]:
	var result: Array[String] = []
	for map_id: Variant in _acquired_maps.keys():
		if map_id is String:
			result.append(map_id)
	result.sort()
	return result


func set_random_region(region: RandomRegionState) -> void:
	if region != null and not region.id.is_empty():
		_random_regions[region.id] = region


func random_region(region: RandomEncounterRegion) -> RandomRegionState:
	if _random_regions.has(region.id):
		return _random_regions[region.id] as RandomRegionState
	return RandomRegionState.new(region.id, region.chance_ten_thousand, region.battle_minimum, region.battle_maximum, region.random_door_percents())


func set_map_darkness(map_id: String, dark: bool) -> void:
	if not map_id.is_empty():
		_map_darkness[map_id] = dark


func map_is_dark(map: MapDefinition) -> bool:
	return false if map == null else bool(_map_darkness.get(map.id, map.dark))


func mark_visited(map_id: String, coordinate: Vector2i) -> void:
	_visited_cells[_cell_key(map_id, coordinate)] = true


func was_visited(map_id: String, coordinate: Vector2i) -> bool:
	return _visited_cells.has(_cell_key(map_id, coordinate))


func visited_coordinates(map_id: String) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	var prefix := "%s:" % map_id
	for key_value: Variant in _visited_cells.keys():
		var key := String(key_value)
		if not key.begins_with(prefix):
			continue
		var components := key.trim_prefix(prefix).split(",", false, 1)
		if components.size() != 2 or not components[0].is_valid_int() or not components[1].is_valid_int():
			continue
		result.append(Vector2i(int(components[0]), int(components[1])))
	result.sort_custom(func(left: Vector2i, right: Vector2i) -> bool: return left.y < right.y or left.y == right.y and left.x < right.x)
	return result


func to_data() -> Dictionary:
	var random_regions: Array[Dictionary] = []
	var random_region_ids: Array = _random_regions.keys()
	random_region_ids.sort()
	for region_id: Variant in random_region_ids:
		random_regions.append((_random_regions[region_id] as RandomRegionState).to_data())
	return {
		"terrainOverrides": _sorted_dictionary(_terrain_overrides),
		"doorStates": _sorted_dictionary(_door_states),
		"discoveredSecrets": _sorted_keys(_discovered_secrets),
		"disabledTriggers": _sorted_keys(_disabled_triggers),
		"visitedCells": _sorted_keys(_visited_cells),
		"triggerChances": _sorted_dictionary(_trigger_chances),
		"acquiredMaps": _sorted_keys(_acquired_maps),
		"randomRegions": random_regions,
		"mapDarkness": _sorted_dictionary(_map_darkness),
	}


static func from_data(data: Variant) -> WorldState:
	if not data is Dictionary:
		return null
	for field: String in ["terrainOverrides", "doorStates", "discoveredSecrets", "disabledTriggers", "visitedCells"]:
		if not data.has(field):
			return null
	if not data["terrainOverrides"] is Dictionary or not data["doorStates"] is Dictionary:
		return null
	var state := WorldState.new()
	for key: Variant in data["terrainOverrides"]:
		if not key is String or not data["terrainOverrides"][key] is String:
			return null
		state._terrain_overrides[key] = data["terrainOverrides"][key]
	for key: Variant in data["doorStates"]:
		if not key is String or data["doorStates"][key] not in ["open", "closed"]:
			return null
		state._door_states[key] = data["doorStates"][key]
	if not _load_key_array(data["discoveredSecrets"], state._discovered_secrets) or not _load_key_array(data["disabledTriggers"], state._disabled_triggers) or not _load_key_array(data["visitedCells"], state._visited_cells):
		return null
	if data.has("triggerChances"):
		if not data["triggerChances"] is Dictionary:
			return null
		for key: Variant in data["triggerChances"]:
			var percent := _integer(data["triggerChances"][key])
			if not key is String or key.is_empty() or percent < -1 or percent > 100:
				return null
			state._trigger_chances[key] = percent
	if data.has("acquiredMaps") and not _load_key_array(data["acquiredMaps"], state._acquired_maps):
		return null
	if data.has("randomRegions"):
		if not data["randomRegions"] is Array:
			return null
		for entry: Variant in data["randomRegions"]:
			var region := RandomRegionState.from_data(entry)
			if region == null or state._random_regions.has(region.id):
				return null
			state._random_regions[region.id] = region
	if data.has("mapDarkness"):
		if not data["mapDarkness"] is Dictionary:
			return null
		for key: Variant in data["mapDarkness"]:
			if not key is String or key.is_empty() or not data["mapDarkness"][key] is bool:
				return null
			state._map_darkness[key] = data["mapDarkness"][key]
	return state


static func _load_key_array(value: Variant, target: Dictionary) -> bool:
	if not value is Array:
		return false
	for key: Variant in value:
		if not key is String or key.is_empty() or target.has(key):
			return false
		target[key] = true
	return true


static func _sorted_dictionary(source: Dictionary) -> Dictionary:
	var result: Dictionary = {}
	var keys: Array = source.keys()
	keys.sort()
	for key: Variant in keys:
		result[key] = source[key]
	return result


static func _sorted_keys(source: Dictionary) -> Array[String]:
	var keys: Array[String] = []
	for key: Variant in source.keys():
		keys.append(String(key))
	keys.sort()
	return keys


static func _cell_key(map_id: String, coordinate: Vector2i) -> String:
	return "%s:%d,%d" % [map_id, coordinate.x, coordinate.y]


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

class_name InteractionComponent
extends VBoxContainer

signal payload_submitted(payload: Dictionary)


func build(_request: InteractionRequest) -> void:
	pass


func add_response(label: String, payload: Dictionary, enabled: bool = true, reason: String = "") -> Button:
	var button := Button.new()
	button.text = label
	button.custom_minimum_size.y = 36.0
	button.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	button.disabled = not enabled
	button.tooltip_text = reason
	button.pressed.connect(func() -> void: payload_submitted.emit(payload))
	add_child(button)
	return button


func add_hint(text: String) -> Label:
	var label := Label.new()
	label.text = text
	label.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	label.add_theme_color_override("font_color", Color("d5b45d"))
	add_child(label)
	return label


func character_option(value: Variant) -> OptionButton:
	var picker := OptionButton.new()
	picker.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	if value is Array:
		for character: Variant in value:
			if character is Dictionary:
				picker.add_item(String(character.get("name", "Character")))
				picker.set_item_metadata(picker.item_count - 1, String(character.get("id", "")))
	return picker

class_name ShopInteraction
extends InteractionComponent


func build(request: InteractionRequest) -> void:
	add_hint("Inflation %d%%" % int(request.payload.get("inflationPercent", 100)))
	var picker := character_option(request.payload.get("characters", []))
	add_child(picker)
	add_hint("Buy")
	var stock: Variant = request.payload.get("stock", [])
	if stock is Array:
		for entry: Variant in stock:
			if not entry is Dictionary:
				continue
			var available := int(entry.get("quantity", 0)) > 0 and picker.item_count > 0
			var payload := {"action": "buy", "stockIndex": int(entry.get("index", -1))}
			var button := Button.new()
			button.text = "%s • %d gold • %d left" % [entry.get("name", "Item"), int(entry.get("buyPrice", 0)), int(entry.get("quantity", 0))]
			button.disabled = not available
			button.tooltip_text = "No stock or eligible buyer." if not available else ""
			button.pressed.connect(func() -> void:
				if picker.item_count > 0:
					payload["characterId"] = String(picker.get_selected_metadata())
					payload_submitted.emit(payload)
			)
			add_child(button)
	add_hint("Sell")
	var characters: Variant = request.payload.get("characters", [])
	if characters is Array:
		for character: Variant in characters:
			if not character is Dictionary or not character.get("inventory", []) is Array:
				continue
			for item: Variant in character.get("inventory", []):
				if item is Dictionary:
					add_response("Sell %s (%s) • %d gold" % [item.get("name", "Item"), character.get("name", "Character"), int(item.get("sellPrice", 0))], {"action": "sell", "characterId": String(character.get("id", "")), "instanceId": String(item.get("instanceId", ""))})
	add_response("Leave shop", {"action": "leave"})

class_name TempleInteraction
extends InteractionComponent


