class_name TextChoiceInteraction
extends InteractionComponent


func build(request: InteractionRequest) -> void:
	match request.kind:
		&"encounter_choice", &"scenario_choice":
			var options: Variant = request.payload.get("options", [])
			if options is Array:
				for index: int in options.size():
					var option: Variant = options[index]
					if option is Dictionary:
						add_response(String(option.get("label", "Option %d" % (index + 1))), {"index": index})
			if request.kind == &"encounter_choice" and bool(request.payload.get("canBackOut", false)):
				add_response("Back out", {"cancelled": true})
		&"yes_no":
			add_response(String(request.payload.get("yesLabel", "Yes")), {"accepted": true})
			add_response(String(request.payload.get("noLabel", "No")), {"accepted": false})
		&"acknowledge":
			add_response("Continue", {})

class_name InteractionPresenter
extends PanelContainer

signal response_submitted(response: InteractionResponse)

@onready var _prompt: Label = %InteractionPrompt
@onready var _heading: Label = %InteractionHeading
@onready var _options: VBoxContainer = %InteractionOptions

var _request: InteractionRequest
var _component: InteractionComponent
var _stage_rect := Rect2(32.0, 32.0, 640.0, 480.0)
var _textbox_rect := Rect2(8.0, 424.0, 696.0, 168.0)
var _passive_text: bool = false


func present(request: InteractionRequest, classic_text_context: String = "") -> void:
	_request = request
	_passive_text = false
	_clear_options()
	visible = request != null
	if request == null:
		_set_heading("")
		_prompt.text = ""
		return
	_set_heading(_heading_for_kind(request.kind))
	_prompt.text = _prompt_for(request, classic_text_context)
	_component = _component_for(request.kind)
	if _component == null:
		_set_heading("Unsupported Interaction")
		_prompt.text = "Unsupported Realmz interaction: %s" % String(request.kind)
		_add_hint("This package cannot continue because its interaction contract is unavailable.")
		return
	_component.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_component.add_theme_constant_override("separation", 8)
	_component.payload_submitted.connect(_submit_payload)
	_options.add_child(_component)
	_component.build(request)
	_apply_classic_region()
	call_deferred("_focus_first_control")


func set_classic_regions(stage_rect: Rect2, textbox_rect: Rect2) -> void:
	_stage_rect = stage_rect
	_textbox_rect = textbox_rect
	_apply_classic_region()


func dismiss_passive_text() -> bool:
	if _request != null or not visible:
		return false
	visible = false
	_passive_text = false
	_prompt.text = ""
	return true


func present_passive_classic_text(text: String) -> void:
	if _request != null:
		return
	_clear_options()
	_set_heading("")
	_prompt.text = text
	_passive_text = not text.is_empty()
	visible = not text.is_empty()
	_apply_classic_region()


func has_blocking_request() -> bool:
	return _request != null


func set_text_scale(value: float) -> void:
	_heading.add_theme_font_size_override("font_size", int(round(18.0 * value)))
	_prompt.add_theme_font_size_override("font_size", int(round(20.0 * value)))


func _component_for(kind: StringName) -> InteractionComponent:
	match kind:
		&"acknowledge", &"yes_no", &"encounter_choice", &"scenario_choice":
			return TextChoiceInteraction.new()
		&"character_selection", &"ally_selection":
			return SelectionInteraction.new()
		&"complex_encounter":
			return EncounterInteraction.new()
		&"shop_action":
			return ShopInteraction.new()
		&"temple_action":
			return TempleInteraction.new()
		&"bank_action":
			return BankInteraction.new()
		&"combat_action":
			return BattleInteraction.new()
	return null


func _submit_payload(payload: Dictionary) -> void:
	if _request == null:
		return
	var response := InteractionPresenter.response_for(_request, payload)
	_request = null
	visible = false
	response_submitted.emit(response)


static func response_for(request: InteractionRequest, payload: Dictionary) -> InteractionResponse:
	assert(request != null, "An interaction response requires its originating request")
	return InteractionResponse.new(request.request_id, request.kind, payload)


func _clear_options() -> void:
	_component = null
	for child: Node in _options.get_children():
		_options.remove_child(child)
		child.queue_free()


func _apply_classic_region() -> void:
	if not is_inside_tree():
		return
	set_anchors_preset(Control.PRESET_TOP_LEFT)
	if _passive_text or _request != null and _request.kind in [&"acknowledge", &"yes_no", &"encounter_choice", &"scenario_choice"]:
		position = _textbox_rect.position
		size = _textbox_rect.size
	else:
		var desired := Vector2(minf(700.0, _stage_rect.size.x - 20.0), minf(520.0, _stage_rect.size.y - 20.0))
		desired.x = maxf(300.0, desired.x)
		desired.y = maxf(260.0, desired.y)
		position = _stage_rect.position + (_stage_rect.size - desired) * 0.5
		size = desired


func _add_hint(text: String) -> void:
	var label := Label.new()
	label.text = text
	label.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	label.add_theme_color_override("font_color", Color("d5b45d"))
	_options.add_child(label)


func _focus_first_control() -> void:
	var first := _first_focusable(_options)
	if first != null:
		first.grab_focus()


static func _title_for_kind(kind: StringName) -> String:
	return String(kind).replace("_", " ").capitalize()


static func _prompt_for(request: InteractionRequest, classic_text_context: String) -> String:
	var explicit_prompt := String(request.payload.get("prompt", "")).strip_edges()
	if not explicit_prompt.is_empty():
		return explicit_prompt
	if request.kind == InteractionRequest.YES_NO:
		var authored_context := classic_text_context.strip_edges()
		if not authored_context.is_empty():
			return authored_context
		return "Choose Yes or No to continue."
	return _title_for_kind(request.kind)


static func _heading_for_kind(kind: StringName) -> String:
	match kind:
		&"acknowledge":
			return ""
		&"yes_no":
			return "Question"
		&"encounter_choice", &"scenario_choice", &"complex_encounter":
			return "Encounter"
		&"character_selection", &"ally_selection":
			return "Character Selection"
		&"shop_action":
			return "Shop"
		&"temple_action":
			return "Temple"
		&"bank_action":
			return "Bank"
		&"combat_action":
			return "Battle"
	return _title_for_kind(kind)


func _set_heading(value: String) -> void:
	_heading.text = value
	_heading.visible = not value.is_empty()


static func _first_focusable(parent: Node) -> Control:
	for child: Node in parent.get_children():
		if child is Control and (child as Control).visible and (child as Control).focus_mode != Control.FOCUS_NONE and not (child is BaseButton and (child as BaseButton).disabled):
			return child as Control
		var nested := _first_focusable(child)
		if nested != null:
			return nested
	return null

class_name ClassicPartyRoster
extends PanelContainer

signal character_selected(character_id: String)

const MUTED := Color("9da8aa")

@onready var _party_list: VBoxContainer = %PartyList
@onready var _heading: Label = %Heading

var _media: PackageMediaCatalog
var _selected_character_id: String = ""


func set_media_catalog(media: PackageMediaCatalog) -> void:
	_media = media


func present(view: GameView, selected_character_id: String = "") -> void:
	_selected_character_id = selected_character_id
	_clear()
	if view == null or not view.session_started:
		_heading.text = "Party"
		_add_empty("No active party")
		return
	_heading.text = "Party • %d / 6" % view.party_members.size()
	for character: CharacterView in view.party_members:
		_add_character(character)
	for index: int in maxi(0, 6 - view.party_members.size()):
		_add_empty("Empty position %d" % (view.party_members.size() + index + 1))


func _add_character(character: CharacterView) -> void:
	var row := Button.new()
	row.custom_minimum_size.y = 58.0
	row.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	row.alignment = HORIZONTAL_ALIGNMENT_LEFT
	row.text_overrun_behavior = TextServer.OVERRUN_TRIM_ELLIPSIS
	row.toggle_mode = true
	row.button_pressed = character.id == _selected_character_id
	var condition_text := _condition_summary(character.condition_values)
	var action_fact := "SP %d/%d" % [character.spell_points, character.maximum_spell_points] if character.maximum_spell_points > 0 else "Attacks %d" % character.normal_attacks
	row.text = "%s\n%s / %s  •  Stamina %d/%d\n%s  •  AR %d%s" % [
		character.name,
		character.race_name,
		character.caste_name,
		character.current_health,
		character.maximum_health,
		action_fact,
		character.armor,
		"  •  %s" % condition_text if not condition_text.is_empty() else "",
	]
	row.tooltip_text = "Level %d • Movement %d/%d" % [character.level, character.movement, character.maximum_movement]
	var portrait := _portrait_texture(character.portrait_id)
	if portrait != null:
		row.icon = portrait
		row.icon_max_width = 42
	row.pressed.connect(func() -> void:
		_selected_character_id = character.id
		character_selected.emit(character.id)
	)
	_party_list.add_child(row)


func _add_empty(text: String) -> void:
	var label := Label.new()
	label.custom_minimum_size.y = 42.0
	label.text = text
	label.vertical_alignment = VERTICAL_ALIGNMENT_CENTER
	label.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
	label.add_theme_color_override("font_color", MUTED)
	_party_list.add_child(label)


func _portrait_texture(asset_id: String) -> Texture2D:
	if _media == null or asset_id.is_empty():
		return null
	var asset := _media.asset_by_id(asset_id)
	if asset == null or not asset.is_picture():
		return null
	var bytes := _media.read_bytes(asset)
	var image := Image.new()
	var error := ERR_UNAVAILABLE
	match asset.path.get_extension().to_lower():
		"png": error = image.load_png_from_buffer(bytes)
		"jpg", "jpeg": error = image.load_jpg_from_buffer(bytes)
		"webp": error = image.load_webp_from_buffer(bytes)
	return ImageTexture.create_from_image(image) if error == OK else null


func _condition_summary(values: Array[int]) -> String:
	var active: Array[String] = []
	for index: int in values.size():
		if values[index] != 0:
			active.append("Condition %d" % (index + 1))
		if active.size() == 2:
			break
	return ", ".join(active)


func _clear() -> void:
	for child: Node in _party_list.get_children():
		_party_list.remove_child(child)
		child.queue_free()

class_name SelectionInteraction
extends InteractionComponent

var _checks: Array[CheckButton] = []


func build(request: InteractionRequest) -> void:
	if request.kind == &"character_selection":
		_build_character_selection(request)
	else:
		_build_ally_selection(request)


func _build_character_selection(request: InteractionRequest) -> void:
	var required := int(request.payload.get("count", 1))
	add_hint("Choose %d character%s." % [required, "" if required == 1 else "s"])
	var eligible: Variant = request.payload.get("eligible", [])
	if eligible is Array:
		for entry: Variant in eligible:
			if entry is Dictionary:
				_add_character_check(entry, false, false)
	var submit := Button.new()
	submit.text = "Choose"
	submit.pressed.connect(_submit_characters.bind(required))
	add_child(submit)


func _build_ally_selection(request: InteractionRequest) -> void:
	var maximum := int(request.payload.get("maximum", 0))
	var selected: Variant = request.payload.get("selectedIds", [])
	add_hint("Choose up to %d surviving allies. Required allies stay selected." % maximum)
	var candidates: Variant = request.payload.get("candidates", [])
	if candidates is Array:
		for entry: Variant in candidates:
			if not entry is Dictionary:
				continue
			var ally_id := String(entry.get("id", ""))
			var required := bool(entry.get("required", false))
			_add_character_check(entry, required or selected is Array and selected.has(ally_id), required)
	var submit := Button.new()
	submit.text = "Continue"
	submit.pressed.connect(_submit_allies.bind(maximum))
	add_child(submit)


func _add_character_check(entry: Dictionary, selected: bool, required: bool) -> void:
	var check := CheckButton.new()
	check.text = "%s • HP %d/%d%s" % [entry.get("name", "Character"), int(entry.get("currentHealth", 0)), int(entry.get("maximumHealth", entry.get("currentHealth", 0))), " • Required" if required else ""]
	check.set_meta("character_id", String(entry.get("id", "")))
	check.button_pressed = selected
	check.disabled = required
	_checks.append(check)
	add_child(check)


func _submit_characters(required: int) -> void:
	var ids := _selected_ids()
	if ids.size() != required:
		add_hint("Choose exactly %d character%s." % [required, "" if required == 1 else "s"])
		return
	payload_submitted.emit({"characterIds": ids})


func _submit_allies(maximum: int) -> void:
	var ids := _selected_ids()
	if ids.size() > maximum:
		add_hint("Choose no more than %d allies." % maximum)
		return
	payload_submitted.emit({"selectedIds": ids})


func _selected_ids() -> Array[String]:
	var ids: Array[String] = []
	for check: CheckButton in _checks:
		if check.button_pressed:
			ids.append(String(check.get_meta("character_id")))
	return ids

