func is_active() -> bool:
	return _enabled and _projection != null


func projection() -> DungeonGeometryProjection:
	return _projection


func _update_visibility() -> void:
	visible = is_active()


func _rebuild_geometry() -> void:
	if _geometry_root == null:
		return
	for child: Node in _geometry_root.get_children():
		_geometry_root.remove_child(child)
		child.queue_free()
	if _projection == null:
		return
	for cell: DungeonGeometryProjection.CellProjection in _projection.cells():
		if cell.passable:
			_add_box("Floor_%d_%d" % [cell.coordinate.x, cell.coordinate.y], Vector3(cell_span * 0.94, 0.10, cell_span * 0.94), _cell_center(cell.coordinate) + Vector3(0.0, -0.08, 0.0), _floor_material)
		if cell.features.has(&"column"):
			_add_column(cell.coordinate)
		if cell.features.has(&"stairs"):
			_add_stairs(cell.coordinate)
	var built_edges: Dictionary = {}
	for edge: DungeonGeometryProjection.EdgeProjection in _projection.edges():
		if edge.kind == &"open" or built_edges.has(edge.canonical_key):
			continue
		built_edges[edge.canonical_key] = true
		if edge.kind in [&"door", &"archway"]:
			_add_door_frame(edge)
		else:
			_add_wall(edge, _secret_material if edge.kind == &"secret" else _wall_material)
	_add_party_marker()
	var target := _cell_center(_projection.party_coordinate) + Vector3(0.0, 0.65, 0.0)
	_camera.position = target + Vector3(5.6, 7.5, 7.8)
	_camera.look_at(target, Vector3.UP)


func _add_wall(edge: DungeonGeometryProjection.EdgeProjection, surface_material: Material) -> void:
	var horizontal := edge.direction in [&"north", &"south"]
	var box_dimensions := Vector3(cell_span, wall_height, wall_thickness) if horizontal else Vector3(wall_thickness, wall_height, cell_span)
	_add_box("Edge_%s" % edge.canonical_key, box_dimensions, _edge_center(edge.coordinate, edge.direction) + Vector3(0.0, wall_height * 0.5, 0.0), surface_material)


func _add_door_frame(edge: DungeonGeometryProjection.EdgeProjection) -> void:
	var horizontal := edge.direction in [&"north", &"south"]
	var center := _edge_center(edge.coordinate, edge.direction)
	var post_offset := cell_span * 0.37
	var post_size := Vector3(wall_thickness * 1.35, wall_height * 0.82, wall_thickness * 1.35)
	var left_offset := Vector3(post_offset, 0.0, 0.0) if horizontal else Vector3(0.0, 0.0, post_offset)
	_add_box("DoorPostA_%s" % edge.canonical_key, post_size, center - left_offset + Vector3(0.0, post_size.y * 0.5, 0.0), _door_material)
	_add_box("DoorPostB_%s" % edge.canonical_key, post_size, center + left_offset + Vector3(0.0, post_size.y * 0.5, 0.0), _door_material)
	var lintel_size := Vector3(cell_span, wall_thickness * 1.5, wall_thickness * 1.5) if horizontal else Vector3(wall_thickness * 1.5, wall_thickness * 1.5, cell_span)
	_add_box("DoorLintel_%s" % edge.canonical_key, lintel_size, center + Vector3(0.0, wall_height * 0.84, 0.0), _door_material)
	if edge.kind == &"door" and not edge.passable:
		var panel_size := Vector3(cell_span * 0.62, wall_height * 0.70, wall_thickness * 0.65) if horizontal else Vector3(wall_thickness * 0.65, wall_height * 0.70, cell_span * 0.62)
		_add_box("DoorPanel_%s" % edge.canonical_key, panel_size, center + Vector3(0.0, panel_size.y * 0.5, 0.0), _door_material)


func _add_column(coordinate: Vector2i) -> void:
	var mesh := CylinderMesh.new()
	mesh.top_radius = 0.26
	mesh.bottom_radius = 0.31
	mesh.height = wall_height * 0.88
	var instance := MeshInstance3D.new()
	instance.name = "Column_%d_%d" % [coordinate.x, coordinate.y]
	instance.mesh = mesh
	instance.material_override = _feature_material
	instance.position = _cell_center(coordinate) + Vector3(0.0, mesh.height * 0.5, 0.0)
	_geometry_root.add_child(instance)


func _add_stairs(coordinate: Vector2i) -> void:
	for index: int in range(3):
		var height := 0.12 * float(index + 1)
		_add_box("Stair_%d_%d_%d" % [coordinate.x, coordinate.y, index], Vector3(cell_span * 0.62, height, cell_span * 0.20), _cell_center(coordinate) + Vector3(0.0, height * 0.5, (float(index) - 1.0) * cell_span * 0.20), _feature_material)


func _add_party_marker() -> void:
	var mesh := CylinderMesh.new()
	mesh.top_radius = 0.24
	mesh.bottom_radius = 0.34
	mesh.height = 0.95
	var marker := MeshInstance3D.new()
	marker.name = "PartyMarker"
	marker.mesh = mesh
	marker.material_override = _party_material
	marker.position = _cell_center(_projection.party_coordinate) + Vector3(0.0, mesh.height * 0.5, 0.0)
	_geometry_root.add_child(marker)


func _add_box(node_name: String, box_size: Vector3, box_position: Vector3, surface_material: Material) -> void:
	var mesh := BoxMesh.new()
	mesh.size = box_size
	var instance := MeshInstance3D.new()
	instance.name = node_name.validate_node_name()
	instance.mesh = mesh
	instance.material_override = surface_material
	instance.position = box_position
	_geometry_root.add_child(instance)


func _cell_center(coordinate: Vector2i) -> Vector3:
	return Vector3(float(coordinate.x) * cell_span, 0.0, float(coordinate.y) * cell_span)


func _edge_center(coordinate: Vector2i, direction: StringName) -> Vector3:
	var center := _cell_center(coordinate)
	match direction:
		&"north":
			center.z -= cell_span * 0.5
		&"east":
			center.x += cell_span * 0.5
		&"south":
			center.z += cell_span * 0.5
		&"west":
			center.x -= cell_span * 0.5
	return center


static func _material(color: Color) -> StandardMaterial3D:...

class_name RealmzArithmetic
extends RefCounted


func signed_16(value: int) -> int:
	var wrapped := value & 0xffff
	return wrapped - 0x10000 if wrapped >= 0x8000 else wrapped


func unsigned_16(value: int) -> int:
	return value & 0xffff


func signed_32(value: int) -> int:
	var wrapped := value & 0xffffffff
	return wrapped - 0x1_0000_0000 if wrapped >= 0x8000_0000 else wrapped


func percentage_succeeds(roll: int, chance: int, inclusive: bool = true) -> bool:
	return roll <= chance if inclusive else roll < chance


func pin(value: int, minimum: int, maximum: int) -> int:
	return clampi(value, minimum, maximum)

class_name MonsterRules
extends RefCounted


func build_monster(definition: MonsterDefinition, instance_id: String, traitor_override: int, difficulty: int, realmz_day: int, rng: RealmzRng) -> MonsterState:
	if definition == null or rng == null:
		return null
	var stamina := definition.stamina_bonus
	for die: int in definition.hit_dice:
		stamina += rng.draw(8, StringName("monster.%s.stamina.%d" % [instance_id, die]))
	var armor := definition.armor + rng.draw(3, StringName("monster.%s.armor" % instance_id)) - 2
	var agility := maxi(1, definition.agility + rng.draw(3, StringName("monster.%s.agility" % instance_id)) - 2)
	var spell_points := definition.spell_points
	var variation := int(float(spell_points) / 10.0)
	if variation > 0:
		spell_points += rng.draw_between(-variation, variation, StringName("monster.%s.spell-points" % instance_id))
	var magic_resistance := definition.magic_resistance
	if magic_resistance < 99 and magic_resistance > 9:
		magic_resistance += 3 * difficulty
	if magic_resistance < 99:
		magic_resistance += 3 * difficulty
	magic_resistance = maxi(0, magic_resistance)
	armor -= 2 * difficulty
	agility += difficulty
	var multiplier := 1.0 + float(difficulty) * 0.33
	spell_points = int(float(spell_points) * multiplier)
	stamina = maxi(1, int(float(stamina) * multiplier))
	var denominator := 180 - 30 * difficulty
	if denominator > 0:
		stamina += int(float(realmz_day) / float(denominator))
	var traitor := definition.traitor if traitor_override < 0 else traitor_override != 0
	var result := MonsterState.new(instance_id, definition.id, definition.name, stamina, stamina, definition.hit_dice, agility, armor, magic_resistance, spell_points, traitor)
	result.surrender_percent = definition.surrender_percent
	result.weapon_id = _random_weapon(definition.random_weapon_table, instance_id, rng) if definition.random_weapon_table > 0 else definition.weapon_id
	return result


func _random_weapon(table_id: int, instance_id: String, rng: RealmzRng) -> String:
	var table_index := 8 if table_id == 10 else table_id - 1
	var tables: Array[Array] = [
		[[0, 50, 10], [51, 60, 20], [61, 70, 71], [71, 95, 75], [96, 100, 24]],
		[[0, 35, 65], [36, 70, 37], [71, 85, 125], [85, 94, 137], [95, 100, 138]],
		[[0, 40, 120], [41, 60, 37], [61, 90, 125], [91, 95, 65], [96, 100, 138]],
		[[0, 40, 81], [41, 80, 92], [81, 85, 81], [86, 93, 92], [94, 100, 136]],
		[[0, 35, 81], [36, 70, 75], [71, 90, 81], [91, 95, 75], [96, 100, 136]],
		[[0, 20, 37], [21, 40, 65], [41, 60, 75], [61, 80, 120], [81, 100, 120]],
		[[0, 15, 140], [16, 30, 142], [31, 45, 120], [46, 75, 140], [76, 100, 120]],
		[[0, 25, 92], [26, 50, 81], [51, 75, 120], [76, 90, 120], [91, 100, 120]],
		[[0, 20, 1], [21, 40, 31], [41, 65, 75], [66, 90, 44], [91, 100, 31]],
	]
	if table_index < 0 or table_index >= tables.size():
		return ""
	var roll := rng.draw(100, StringName("monster.%s.random-weapon" % instance_id))
	for range_row: Array in tables[table_index]:
		if roll >= int(range_row[0]) and roll <= int(range_row[1]):
			return "classic.item.%d" % int(range_row[2])
	return ""


func choose_action(monster: MonsterState, definition: MonsterDefinition, rng: RealmzRng) -> StringName:
	if monster.conditions.is_active(ConditionRules.RUNS_AWAY):
		return &"retreat"
	if rng.draw(100, &"monster.ai.missile") <= definition.missile_percent:
		return &"missile"
	if not monster.conditions.is_active(ConditionRules.STUPID) and not monster.conditions.is_active(ConditionRules.CONFUSED) and not monster.conditions.is_active(ConditionRules.SILENCED) and not monster.conditions.is_active(ConditionRules.HELPLESS) and rng.draw(100, &"monster.ai.cast") <= definition.cast_percent:
		return &"cast"
	return &"advance"


func morale_action(monster: MonsterState, definition: MonsterDefinition) -> StringName:
	if monster.current_health <= 0:
		return &"defeated"
	# Castle getup.c computes current/current before the thresholds; preserve the observable 100 percent result.
	var percent := 100
	var surrender_percent := monster.surrender_percent if monster.surrender_percent != 0 else definition.surrender_percent
	if percent < surrender_percent:
		return &"panic" if surrender_percent == 101 else &"surrender"
	if percent < definition.run_percent:
		return &"retreat"
	return &"fight"

