class_name RealmzRngState
extends RefCounted

var generator_state: int
var draw_count: int


func _init(state_value: int, completed_draws: int) -> void:
	generator_state = state_value
	draw_count = completed_draws


func to_data() -> Dictionary:
	return {"generatorState": generator_state, "drawCount": draw_count}


static func from_data(data: Variant) -> RealmzRngState:
	if not data is Dictionary or not data.has("generatorState") or not data.has("drawCount"):
		return null
	var generator := _integer(data["generatorState"])
	var draws := _integer(data["drawCount"])
	if generator < 0 or draws < 0:
		return null
	if generator <= 0 or generator >= RealmzRng.MODULUS:
		return null
	return RealmzRngState.new(generator, draws)


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

class_name GameSessionController
extends Node

signal step_committed(step: SessionStep)

var _session: GameSession = GameSession.new()
var _current_view: GameView = _session.view()


func session() -> GameSession:
	return _session


func view() -> GameView:
	return _current_view


func replace_session(replacement: GameSession) -> void:
	assert(replacement != null, "A session replacement is required")
	_session = replacement
	_current_view = _session.view()


func start(content: RealmzContent, initial_seed: int) -> SessionStep:
	var replacement := GameSession.new()
	var step := replacement.start(content, initial_seed)
	if step.state != SessionStep.State.FAILED:
		replace_session(replacement)
	step_committed.emit(step)
	return step


func restore(content: RealmzContent, envelope: SaveEnvelope) -> SessionStep:
	var replacement := GameSession.new()
	var step := replacement.restore(content, envelope)
	if step.state != SessionStep.State.FAILED:
		replace_session(replacement)
	step_committed.emit(step)
	return step


func submit_intent(intent: PlayerIntent) -> SessionStep:
	var step: SessionStep = _session.submit_intent(intent)
	_current_view = _session.view()
	step_committed.emit(step)
	return step


func respond(response: InteractionResponse) -> SessionStep:
	var step: SessionStep = _session.respond(response)
	_current_view = _session.view()
	step_committed.emit(step)
	return step

class_name UiInputActions
extends RefCounted

const DEFINITIONS: Array[Dictionary] = [
	{"id": &"realmz_move_up", "keys": [KEY_UP, KEY_W, KEY_KP_8]},
	{"id": &"realmz_move_up_right", "keys": [KEY_KP_9]},
	{"id": &"realmz_move_right", "keys": [KEY_RIGHT, KEY_D, KEY_KP_6]},
	{"id": &"realmz_move_down_right", "keys": [KEY_KP_3]},
	{"id": &"realmz_move_down", "keys": [KEY_DOWN, KEY_S, KEY_KP_2]},
	{"id": &"realmz_move_down_left", "keys": [KEY_KP_1]},
	{"id": &"realmz_move_left", "keys": [KEY_LEFT, KEY_A, KEY_KP_4]},
	{"id": &"realmz_move_up_left", "keys": [KEY_KP_7]},
	{"id": &"realmz_search", "keys": [KEY_F]},
	{"id": &"realmz_camp", "keys": [KEY_C]},
	{"id": &"realmz_back", "keys": [KEY_ESCAPE]},
	{"id": &"ui_screen_explore", "keys": [KEY_1]},
	{"id": &"ui_screen_characters", "keys": [KEY_2]},
	{"id": &"ui_screen_inventory", "keys": [KEY_3]},
	{"id": &"ui_screen_spells", "keys": [KEY_4]},
	{"id": &"ui_screen_journal", "keys": [KEY_5]},
	{"id": &"ui_screen_system", "keys": [KEY_6]},
	{"id": &"ui_screen_vault", "keys": [KEY_7]},
	{"id": &"ui_screen_services", "keys": [KEY_8]},
	{"id": &"ui_screen_battle", "keys": [KEY_9]},
]


static func ensure_defaults() -> void:
	for definition: Dictionary in DEFINITIONS:
		var action_id: StringName = definition["id"]
		if not InputMap.has_action(action_id):
			InputMap.add_action(action_id)
		if not InputMap.action_get_events(action_id).is_empty():
			continue
		for keycode: Key in definition["keys"]:
			var event := InputEventKey.new()
			event.physical_keycode = keycode
			InputMap.action_add_event(action_id, event)


static func movement_direction(event: InputEvent) -> Vector2i:
	if event.is_action_pressed(&"realmz_move_up"):
		return Vector2i.UP
	if event.is_action_pressed(&"realmz_move_up_right"):
		return Vector2i(1, -1)
	if event.is_action_pressed(&"realmz_move_right"):
		return Vector2i.RIGHT
