			_shell_presenter.set_status("Choose a response before leaving this interaction.")
			get_viewport().set_input_as_handled()
			return
		if _interaction_presenter.dismiss_passive_text() or _shell_presenter.handle_back():
			get_viewport().set_input_as_handled()
