	var first: Array[String] = []
	var last: Array[String] = []
	for id: String in order:
		if monster_ids.has(id):
			first.append(id)
		else:
			last.append(id)
	first.append_array(last)
	return first

class_name EconomyRules
extends RefCounted


func pool_party_wealth(party: PartyState) -> void:
	for character: CharacterState in party.characters():
		party.pooled_wealth.gold += character.money.gold
		party.pooled_wealth.gems += character.money.gems
		party.pooled_wealth.jewelry += character.money.jewelry
		character.carried_load = maxi(0, character.carried_load - character.money.gold - character.money.gems - character.money.jewelry * 15)
		character.money = WealthState.new()


func take(party: PartyState, amount: int, kind: WealthState.Kind) -> bool:
	if amount < 0:
		return false
	var available := party.pooled_wealth.amount(kind)
	for character: CharacterState in party.characters():
		available += character.money.amount(kind)
	if amount > available:
		return false
	var from_pool := mini(amount, party.pooled_wealth.amount(kind))
	party.pooled_wealth.add(kind, -from_pool)
	var remaining := amount - from_pool
	var characters := party.characters()
	var index := 0
	while remaining > 0:
		var character := characters[index]
		if character.money.amount(kind) > 0:
			character.money.add(kind, -1)
			character.carried_load = maxi(0, character.carried_load - (15 if kind == WealthState.Kind.JEWELRY else 1))
			remaining -= 1
		index = (index + 1) % characters.size()
	return true


func item_price(item: ItemDefinition, shop: ShopDefinition, selling: bool = false) -> int:
	var multiplier := shop.inflation_percent
	if selling and multiplier > 100:
		multiplier = 100
	return mini(32_000, int(float(absi(item.cost) * multiplier) / 100.0))


func roll_treasure(treasure: TreasureDefinition, rng: RealmzRng) -> TreasureRoll:
	return TreasureRoll.new(_roll_signed(treasure.experience, rng, &"treasure.experience"), WealthState.new(_roll_signed(treasure.gold, rng, &"treasure.gold"), _roll_signed(treasure.gems, rng, &"treasure.gems"), _roll_signed(treasure.jewelry, rng, &"treasure.jewelry")), treasure.item_ids())


func _roll_signed(value: int, rng: RealmzRng, tag: StringName) -> int:
	return rng.draw(absi(value), tag) if value < 0 else maxi(0, value)

class_name InventoryRules
extends RefCounted

const MAX_ITEMS: int = 30


func can_equip(character: CharacterState, item: ItemDefinition) -> bool:
	if character == null or item == null:
		return false
	if not item.specific_race_id.is_empty() and item.specific_race_id != character.race_id:
		return false
	if not item.specific_caste_id.is_empty() and item.specific_caste_id != character.caste_id:
		return false
	return true


func add_item(character: CharacterState, item: ItemDefinition, instance_id: String, identified: bool = false) -> ItemInstance:
	if character == null or item == null or character.inventory().size() >= MAX_ITEMS:
		return null
	var instance := ItemInstance.new(instance_id, item.id, item.initial_charges, false, identified)
	var items := character.inventory()
	if character.carried_load + item.instance_weight(instance.charges) > character.maximum_load:
		return null
	items.append(instance)
	character.set_inventory(items)
	character.carried_load += item.instance_weight(instance.charges)
	return instance


func equip(character: CharacterState, instance_id: String, definition: ItemDefinition) -> bool:
	if not can_equip(character, definition):
		return false
	for instance: ItemInstance in character.inventory():
		if instance.id == instance_id and instance.definition_id == definition.id:
			instance.equipped = true
			return true
	return false


func use_charge(character: CharacterState, instance_id: String, definition: ItemDefinition) -> bool:
	var items := character.inventory()
	for index: int in items.size():
		var instance := items[index]
		if instance.id != instance_id or instance.definition_id != definition.id or instance.charges == 0:
			continue
		if instance.charges > 0:
			instance.charges -= 1
			character.carried_load = maxi(0, character.carried_load - definition.weight_per_charge)
		if instance.charges == 0 and definition.drop_on_empty:
			items.remove_at(index)
			character.carried_load = maxi(0, character.carried_load - definition.weight)
			character.set_inventory(items)
		return true
	return false


func remove_item(character: CharacterState, instance_id: String, definition: ItemDefinition) -> ItemInstance:
	if character == null or definition == null:
		return null
	var items := character.inventory()
	for index: int in items.size():
		var instance := items[index]
		if instance.id != instance_id or instance.definition_id != definition.id:
			continue
		items.remove_at(index)
		character.set_inventory(items)
		character.carried_load = maxi(0, character.carried_load - definition.instance_weight(instance.charges))
		return instance
	return null


func equipped_damage_bonus(character: CharacterState, definitions: Array[ItemDefinition]) -> int:
