	return String(_terrain_overrides.get(_cell_key(map_id, cell.coordinate), cell.terrain_id))


func replace_terrain(map_id: String, coordinate: Vector2i, terrain_id: String) -> void:
	_terrain_overrides[_cell_key(map_id, coordinate)] = terrain_id


func open_door(door_id: String) -> void:
	if not door_id.is_empty():
		_door_states[door_id] = "open"


func door_is_open(door_id: String, initially_open: bool = false) -> bool:
	if door_id.is_empty():
		return true
	return _door_states.get(door_id, "open" if initially_open else "closed") == "open"


func discover_secret(secret_id: String) -> void:
	if not secret_id.is_empty():
		_discovered_secrets[secret_id] = true


func secret_is_discovered(secret_id: String, initially_discovered: bool = false) -> bool:
	return secret_id.is_empty() or initially_discovered or _discovered_secrets.has(secret_id)


func disable_trigger(trigger_id: String) -> void:
	_disabled_triggers[trigger_id] = true


func trigger_is_disabled(trigger_id: String) -> bool:
	return _disabled_triggers.has(trigger_id)


func set_trigger_chance(trigger_id: String, percent: int) -> void:
	if trigger_id.is_empty():
		return
	_trigger_chances[trigger_id] = clampi(percent, -1, 100)
	if percent < 0:
		disable_trigger(trigger_id)


func trigger_chance(trigger_id: String, authored_percent: int) -> int:
	return int(_trigger_chances.get(trigger_id, authored_percent))


func acquire_map(map_id: String) -> void:
	if not map_id.is_empty():
		_acquired_maps[map_id] = true


func has_map(map_id: String) -> bool:
	return _acquired_maps.has(map_id)


func acquired_map_ids() -> Array[String]:
	var result: Array[String] = []
	for map_id: Variant in _acquired_maps.keys():
		if map_id is String:
			result.append(map_id)
	result.sort()
	return result


func set_random_region(region: RandomRegionState) -> void:
	if region != null and not region.id.is_empty():
		_random_regions[region.id] = region


func random_region(region: RandomEncounterRegion) -> RandomRegionState:
	if _random_regions.has(region.id):
		return _random_regions[region.id] as RandomRegionState
	return RandomRegionState.new(region.id, region.chance_ten_thousand, region.battle_minimum, region.battle_maximum, region.random_door_percents())


func set_map_darkness(map_id: String, dark: bool) -> void:
	if not map_id.is_empty():
		_map_darkness[map_id] = dark


func map_is_dark(map: MapDefinition) -> bool:
	return false if map == null else bool(_map_darkness.get(map.id, map.dark))


func mark_visited(map_id: String, coordinate: Vector2i) -> void:
	_visited_cells[_cell_key(map_id, coordinate)] = true


func was_visited(map_id: String, coordinate: Vector2i) -> bool:
	return _visited_cells.has(_cell_key(map_id, coordinate))


func visited_coordinates(map_id: String) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	var prefix := "%s:" % map_id
	for key_value: Variant in _visited_cells.keys():
		var key := String(key_value)
		if not key.begins_with(prefix):
			continue
		var components := key.trim_prefix(prefix).split(",", false, 1)
		if components.size() != 2 or not components[0].is_valid_int() or not components[1].is_valid_int():
			continue
		result.append(Vector2i(int(components[0]), int(components[1])))
	result.sort_custom(func(left: Vector2i, right: Vector2i) -> bool: return left.y < right.y or left.y == right.y and left.x < right.x)
	return result


func to_data() -> Dictionary:
	var random_regions: Array[Dictionary] = []
	var random_region_ids: Array = _random_regions.keys()
	random_region_ids.sort()
	for region_id: Variant in random_region_ids:
		random_regions.append((_random_regions[region_id] as RandomRegionState).to_data())
	return {
		"terrainOverrides": _sorted_dictionary(_terrain_overrides),
		"doorStates": _sorted_dictionary(_door_states),
		"discoveredSecrets": _sorted_keys(_discovered_secrets),
		"disabledTriggers": _sorted_keys(_disabled_triggers),
		"visitedCells": _sorted_keys(_visited_cells),
		"triggerChances": _sorted_dictionary(_trigger_chances),
		"acquiredMaps": _sorted_keys(_acquired_maps),
		"randomRegions": random_regions,
		"mapDarkness": _sorted_dictionary(_map_darkness),
	}


static func from_data(data: Variant) -> WorldState:
	if not data is Dictionary:
		return null
	for field: String in ["terrainOverrides", "doorStates", "discoveredSecrets", "disabledTriggers", "visitedCells"]:
		if not data.has(field):
			return null
	if not data["terrainOverrides"] is Dictionary or not data["doorStates"] is Dictionary:
		return null
	var state := WorldState.new()
	for key: Variant in data["terrainOverrides"]:
		if not key is String or not data["terrainOverrides"][key] is String:
			return null
		state._terrain_overrides[key] = data["terrainOverrides"][key]
	for key: Variant in data["doorStates"]:
		if not key is String or data["doorStates"][key] not in ["open", "closed"]:
			return null
		state._door_states[key] = data["doorStates"][key]
	if not _load_key_array(data["discoveredSecrets"], state._discovered_secrets) or not _load_key_array(data["disabledTriggers"], state._disabled_triggers) or not _load_key_array(data["visitedCells"], state._visited_cells):

func can_equip(character: CharacterState, item: ItemDefinition) -> bool:
	if character == null or item == null:
		return false
	if not item.specific_race_id.is_empty() and item.specific_race_id != character.race_id:
		return false
	if not item.specific_caste_id.is_empty() and item.specific_caste_id != character.caste_id:
		return false
	return true

func add_item(character: CharacterState, item: ItemDefinition, instance_id: String, identified: bool = false) -> ItemInstance:
	if character == null or item == null or character.inventory().size() >= MAX_ITEMS:
		return null
	var instance := ItemInstance.new(instance_id, item.id, item.initial_charges, false, identified)
	var items := character.inventory()
	if character.carried_load + item.instance_weight(instance.charges) > character.maximum_load:
		return null
	items.append(instance)
	character.set_inventory(items)
	character.carried_load += item.instance_weight(instance.charges)
	return instance

func equip(character: CharacterState, instance_id: String, definition: ItemDefinition) -> bool:
	if not can_equip(character, definition):
		return false
	for instance: ItemInstance in character.inventory():
		if instance.id == instance_id and instance.definition_id == definition.id:
			instance.equipped = true
			return true
	return false

func use_charge(character: CharacterState, instance_id: String, definition: ItemDefinition) -> bool:
	var items := character.inventory()
	for index: int in items.size():
		var instance := items[index]
		if instance.id != instance_id or instance.definition_id != definition.id or instance.charges == 0:
			continue
		if instance.charges > 0:
			instance.charges -= 1
			character.carried_load = maxi(0, character.carried_load - definition.weight_per_charge)
		if instance.charges == 0 and definition.drop_on_empty:
			items.remove_at(index)
			character.carried_load = maxi(0, character.carried_load - definition.weight)
			character.set_inventory(items)
		return true
	return false

func remove_item(character: CharacterState, instance_id: String, definition: ItemDefinition) -> ItemInstance:
	if character == null or definition == null:
		return null
	var items := character.inventory()
	for index: int in items.size():
		var instance := items[index]
		if instance.id != instance_id or instance.definition_id != definition.id:
			continue
		items.remove_at(index)
		character.set_inventory(items)
		character.carried_load = maxi(0, character.carried_load - definition.instance_weight(instance.charges))
		return instance
	return null

func equipped_damage_bonus(character: CharacterState, definitions: Array[ItemDefinition]) -> int:
	var by_id: Dictionary = {}
	for definition: ItemDefinition in definitions:
		by_id[definition.id] = definition
	var total := 0
	for instance: ItemInstance in character.inventory():
		if instance.equipped and by_id.has(instance.definition_id):
			total += (by_id[instance.definition_id] as ItemDefinition).damage_bonus
	return total

func take(party: PartyState, amount: int, kind: WealthState.Kind) -> bool:
	if amount < 0:
		return false
	var available := party.pooled_wealth.amount(kind)
	for character: CharacterState in party.characters():
		available += character.money.amount(kind)
	if amount > available:
		return false
	var from_pool := mini(amount, party.pooled_wealth.amount(kind))
	party.pooled_wealth.add(kind, -from_pool)
	var remaining := amount - from_pool
	var characters := party.characters()
	var index := 0
	while remaining > 0:
		var character := characters[index]
		if character.money.amount(kind) > 0:
			character.money.add(kind, -1)
			character.carried_load = maxi(0, character.carried_load - (15 if kind == WealthState.Kind.JEWELRY else 1))
			remaining -= 1
		index = (index + 1) % characters.size()
	return true

func signed_16(value: int) -> int:
	var wrapped := value & 0xffff
	return wrapped - 0x10000 if wrapped >= 0x8000 else wrapped

func signed_32(value: int) -> int:
	var wrapped := value & 0xffffffff
	return wrapped - 0x1_0000_0000 if wrapped >= 0x8000_0000 else wrapped

func tick_character(character: CharacterState) -> Array[DomainEvent]:
	var events: Array[DomainEvent] = []
	if character.conditions.is_active(REGENERATING) and character.current_health > -10 and character.current_health < character.maximum_health and not character.conditions.is_active(ANIMATED):
		var healed := mini(absi(character.conditions.value(REGENERATING)), character.maximum_health - character.current_health)
		character.current_health += healed
		events.append(DomainEvent.new(&"condition_healed", {"characterId": character.id, "condition": REGENERATING, "amount": healed}))
	for index: int in [DISEASED, POISONED]:
		if character.conditions.is_active(index) and character.current_health > 0 and character.conditions.value(ANIMATED) > -1:
			var damage := absi(character.conditions.value(index))
			character.current_health -= damage
			events.append(DomainEvent.new(&"condition_damaged", {"characterId": character.id, "condition": index, "amount": damage}))
	if character.conditions.is_active(ENERGY_DRAIN) and character.current_health > 0:
		character.spell_points = maxi(0, character.spell_points - absi(character.conditions.value(ENERGY_DRAIN)))
	if character.conditions.is_active(ABSORBING_ENERGY) and character.maximum_spell_points > 0 and character.current_health > 0:
		character.spell_points = mini(character.maximum_spell_points, character.spell_points + absi(character.conditions.value(ABSORBING_ENERGY)))
	for index: int in character.conditions.decay_positive():
		events.append(DomainEvent.new(&"condition_expired", {"characterId": character.id, "condition": index}))
	return events

func tick_party(party: PartyState) -> Array[DomainEvent]:
	var events: Array[DomainEvent] = []
	for index: int in party.conditions.decay_positive():
		events.append(DomainEvent.new(&"party_condition_expired", {"condition": index}))
	for character: CharacterState in party.characters():
		events.append_array(tick_character(character))
	return events

func item_price(item: ItemDefinition, shop: ShopDefinition, selling: bool = false) -> int:
	var multiplier := shop.inflation_percent
	if selling and multiplier > 100:
		multiplier = 100
	return mini(32_000, int(float(absi(item.cost) * multiplier) / 100.0))

func _init(hit_bonus: int = 0, damage: int = 0) -> void:
	to_hit_bonus = hit_bonus
	damage_bonus = damage

func change_fatigue(party: PartyState, amount: int) -> int:
	party.fatigue = clampi(party.fatigue + amount, 4, 135)
	return party.fatigue

func advance_minutes(state: GameState, minutes: int, condition_ticks: int = 0) -> Array[DomainEvent]:
	state.clock.advance_minutes(maxi(0, minutes))
	var events: Array[DomainEvent] = [DomainEvent.new(&"time_advanced", {"minutes": maxi(0, minutes), "day": state.clock.day(), "hour": state.clock.hour()})]
	for tick: int in condition_ticks:
		events.append_array(_conditions.tick_party(state.party))
	return events

func camp(state: GameState, hours: int = 8) -> Array[DomainEvent]:
	var events := advance_minutes(state, maxi(1, hours) * 60, maxi(1, hours))
	state.party.fatigue = 4
	for character: CharacterState in state.party.characters():
		if character.current_health > 0:
			character.current_health = mini(character.maximum_health, character.current_health + maxi(1, hours))
			character.spell_points = character.maximum_spell_points
	events.append(DomainEvent.new(&"party_camped", {"hours": maxi(1, hours)}))
	return events

