class_name ScenarioActionState
extends RefCounted

const MAX_ENTRIES: int = 4096

var _values: Dictionary = {}


func read(state_scope: String, owner_id: String, name: String, default_value: Variant = null) -> Variant:
	return _values.get(_key(state_scope, owner_id, name), default_value)


func write(state_scope: String, owner_id: String, name: String, value: Variant) -> bool:
	var key := _key(state_scope, owner_id, name)
	if not _values.has(key) and _values.size() >= MAX_ENTRIES:
		return false
	if not _json_safe(value, 0):
		return false
	_values[key] = value
	return true


func to_data() -> Dictionary:
	var result: Dictionary = {}
	var keys: Array = _values.keys()
	keys.sort()
	for key: Variant in keys:
		result[key] = _encode(_values[key])
	return result


static func from_data(data: Variant) -> ScenarioActionState:
	if not data is Dictionary or data.size() > MAX_ENTRIES:
		return null
	var state := ScenarioActionState.new()
	for key: Variant in data.keys():
		if not key is String or key.is_empty():
			return null
		var decoded := _decode(data[key], 0)
		if not decoded["ok"]:
			return null
		state._values[key] = decoded["value"]
	return state


static func _key(state_scope: String, owner_id: String, name: String) -> String:
	return "%s:%s:%s" % [state_scope, owner_id, name]


static func _json_safe(value: Variant, depth: int) -> bool:
	if depth > 32:
		return false
	if value == null or value is bool or value is int or value is String:
		return true
	if value is float:
		return not is_nan(value) and not is_inf(value)
	if value is Array:
		if value.size() > 256:
			return false
		for child: Variant in value:
			if not _json_safe(child, depth + 1):
				return false
		return true
	if value is Dictionary:
		if value.size() > 256:
			return false
		for key: Variant in value.keys():
			if not key is String or not _json_safe(value[key], depth + 1):
				return false
		return true
	return false


static func _encode(value: Variant) -> Dictionary:
	if value == null:
		return {"type": "null"}
	if value is bool:
		return {"type": "bool", "value": value}
	if value is int:
		return {"type": "int", "value": value}
	if value is float:
		return {"type": "float", "value": value}
	if value is String:
		return {"type": "string", "value": value}
	if value is Array:
		var entries: Array[Dictionary] = []
		for child: Variant in value:
			entries.append(_encode(child))
		return {"type": "array", "value": entries}
	var fields: Dictionary = {}
	var keys: Array = value.keys()
	keys.sort()
	for key: Variant in keys:
		fields[key] = _encode(value[key])
	return {"type": "record", "value": fields}


static func _decode(value: Variant, depth: int) -> Dictionary:
	if depth > 32 or not value is Dictionary or not value.get("type") is String:
		return {"ok": false}
	match value["type"]:
		"null":
			return {"ok": value.size() == 1, "value": null}
		"bool":
			return {"ok": value.size() == 2 and value.get("value") is bool, "value": value.get("value")}
		"int":
			var integer: Variant = _integer(value.get("value"))
			return {"ok": value.size() == 2 and integer != null, "value": integer}
		"float":
			var number: Variant = value.get("value")
			return {"ok": value.size() == 2 and (number is int or number is float) and not is_nan(float(number)) and not is_inf(float(number)), "value": float(number) if number is int or number is float else 0.0}
		"string":
			return {"ok": value.size() == 2 and value.get("value") is String, "value": value.get("value")}
		"array":
			if value.size() != 2 or not value.get("value") is Array or value["value"].size() > 256:
				return {"ok": false}
			var entries: Array = []
			for child: Variant in value["value"]:
				var decoded := _decode(child, depth + 1)
				if not decoded["ok"]:
					return {"ok": false}
				entries.append(decoded["value"])
			return {"ok": true, "value": entries}
		"record":
			if value.size() != 2 or not value.get("value") is Dictionary or value["value"].size() > 256:
				return {"ok": false}
			var fields: Dictionary = {}
			for key: Variant in value["value"].keys():
				if not key is String:
					return {"ok": false}
				var decoded := _decode(value["value"][key], depth + 1)
				if not decoded["ok"]:
					return {"ok": false}
				fields[key] = decoded["value"]
			return {"ok": true, "value": fields}
	return {"ok": false}


static func _integer(value: Variant) -> Variant:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return null

class_name ScenarioFrame
extends RefCounted

const PROGRAM: StringName = &"program"
const ACTION: StringName = &"action"

var kind: StringName
var definition_id: String
var cursor: int = 0
var return_target: String = ""
var counts_as_classic_call: bool = false
var _parameters: Dictionary = {}
var _locals: Dictionary = {}
var _context: Dictionary = {}
var _iterators: Array[Dictionary] = []


func _init(frame_kind: StringName, id: String, start_cursor: int = 0) -> void:
	kind = frame_kind
	definition_id = id
	cursor = start_cursor


func set_parameters(values: Dictionary) -> void:
	_parameters = values.duplicate(true)


func parameter(name: String) -> Variant:
	return _parameters.get(name)


func has_local(name: String) -> bool:
	return _locals.has(name)


func local(name: String) -> Variant:
	return _locals.get(name)


func set_local(name: String, value: Variant) -> void:
	_locals[name] = value


func erase_local(name: String) -> void:
	_locals.erase(name)


func set_context(values: Dictionary) -> void:
	_context = values.duplicate(true)


func context_value(name: String) -> Variant:
	return _context.get(name)


func context_data() -> Dictionary:
	return _context.duplicate(true)


func push_iterator(iterator: Dictionary) -> void:
	_iterators.append(iterator.duplicate(true))


func has_iterator() -> bool:
	return not _iterators.is_empty()


func current_iterator() -> Dictionary:
	return {} if _iterators.is_empty() else _iterators.back().duplicate(true)


func update_current_iterator(iterator: Dictionary) -> void:
	assert(not _iterators.is_empty(), "An active iterator is required")
	_iterators[_iterators.size() - 1] = iterator.duplicate(true)


func pop_iterator() -> Dictionary:
	return {} if _iterators.is_empty() else _iterators.pop_back()


func to_data() -> Dictionary:
	return {
		"kind": String(kind),
		"definitionId": definition_id,
		"cursor": cursor,
		"returnTarget": return_target,
		"countsAsClassicCall": counts_as_classic_call,
		"parameters": _parameters.duplicate(true),
		"locals": _locals.duplicate(true),
		"context": _context.duplicate(true),
		"iterators": _iterators.duplicate(true),
	}


static func from_data(data: Variant) -> ScenarioFrame:
	if not data is Dictionary:
		return null
	for field: String in ["kind", "definitionId", "cursor", "returnTarget", "countsAsClassicCall", "parameters", "locals", "context", "iterators"]:
		if not data.has(field):
			return null
	var saved_cursor := _integer(data["cursor"])
	if data["kind"] not in ["program", "action"] or not data["definitionId"] is String or data["definitionId"].is_empty() or saved_cursor < 0 or not data["returnTarget"] is String or not data["countsAsClassicCall"] is bool:
		return null
	if not data["parameters"] is Dictionary or not data["locals"] is Dictionary or not data["context"] is Dictionary or not data["iterators"] is Array:
		return null
	var frame := ScenarioFrame.new(StringName(data["kind"]), data["definitionId"], saved_cursor)
	frame.return_target = data["returnTarget"]
	frame.counts_as_classic_call = data["countsAsClassicCall"]
	frame._parameters = data["parameters"].duplicate(true)
	frame._locals = data["locals"].duplicate(true)
	frame._context = data["context"].duplicate(true)
	for iterator: Variant in data["iterators"]:
		if not iterator is Dictionary:
			return null
		frame._iterators.append(iterator.duplicate(true))
	return frame


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

class_name ScenarioVmSnapshot
extends RefCounted

const SCHEMA_VERSION: int = 1

var frames: Array[ScenarioFrame] = []
var pending_request: InteractionRequest
var pending_continuation: Dictionary = {}
var trace: Array[Dictionary] = []
var request_counter: int = 0
var step_count: int = 0
var halted: bool = true
var last_outcome: Variant


func to_data() -> Dictionary:
	var frame_data: Array[Dictionary] = []
	for frame: ScenarioFrame in frames:
		frame_data.append(frame.to_data())
	var pending_data: Variant = null
	if pending_request != null:
		pending_data = pending_request.to_data()
	return {
		"schemaVersion": SCHEMA_VERSION,
		"frames": frame_data,
		"pendingRequest": pending_data,
		"pendingContinuation": pending_continuation.duplicate(true),
		"trace": trace.duplicate(true),
		"requestCounter": request_counter,
		"stepCount": step_count,
		"halted": halted,
		"lastOutcome": last_outcome,
	}


static func from_data(data: Variant) -> ScenarioVmSnapshot:
	if not data is Dictionary or data.get("schemaVersion") != SCHEMA_VERSION:
		return null
	for field: String in ["frames", "pendingRequest", "pendingContinuation", "trace", "requestCounter", "stepCount", "halted", "lastOutcome"]:
		if not data.has(field):
			return null
	var saved_request_counter := _integer(data["requestCounter"])
	var saved_step_count := _integer(data["stepCount"])
	if not data["frames"] is Array or not data["pendingContinuation"] is Dictionary or not data["trace"] is Array or saved_request_counter < 0 or saved_step_count < 0 or not data["halted"] is bool:
		return null
	var snapshot := ScenarioVmSnapshot.new()
	for frame_data: Variant in data["frames"]:
		var frame := ScenarioFrame.from_data(frame_data)
		if frame == null:
			return null
		snapshot.frames.append(frame)
	if data["pendingRequest"] != null:
		snapshot.pending_request = InteractionRequest.from_data(data["pendingRequest"])
		if snapshot.pending_request == null:
			return null
	snapshot.pending_continuation = data["pendingContinuation"].duplicate(true)
	if (snapshot.pending_request == null and not snapshot.pending_continuation.is_empty()) or (snapshot.pending_request != null and snapshot.pending_continuation.is_empty()):
		return null
	for entry: Variant in data["trace"]:
		if not entry is Dictionary:
			return null
		snapshot.trace.append(entry.duplicate(true))
	snapshot.request_counter = saved_request_counter
	snapshot.step_count = saved_step_count
	snapshot.halted = data["halted"]
	snapshot.last_outcome = data["lastOutcome"]
	return snapshot


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

class_name ScenarioVm
extends RefCounted

const CLASSIC_CALL_LIMIT: int = 20
const ACTION_CALL_LIMIT: int = 32
const EXECUTION_STEP_LIMIT: int = 65536
const TRACE_LIMIT: int = 4096

var _definition: ScenarioDefinition
var _frames: Array[ScenarioFrame] = []
var _pending_request: InteractionRequest
var _pending_continuation: Dictionary = {}
var _trace: Array[Dictionary] = []
var _request_counter: int = 0
var _step_count: int = 0
var _execution_step_limit: int = EXECUTION_STEP_LIMIT
var _halted: bool = true
var _last_outcome: Variant


func configure(definition: ScenarioDefinition, execution_step_limit: int = EXECUTION_STEP_LIMIT) -> void:
	assert(execution_step_limit > 0 and execution_step_limit <= EXECUTION_STEP_LIMIT, "Scenario step limit must remain within the engine budget")
	_definition = definition
	_execution_step_limit = execution_step_limit
	reset()


func reset() -> void:
	_frames.clear()
	_pending_request = null
	_pending_continuation.clear()
	_trace.clear()
	_request_counter = 0
	_step_count = 0
	_halted = true
	_last_outcome = null


func start_program(program_id: String, context: Dictionary = {}) -> ScenarioVmResult:
	if _definition == null:
		return ScenarioVmResult.failed(&"scenario_not_configured", "Scenario VM has no validated definition.")
	if _pending_request != null or not _frames.is_empty():
		return ScenarioVmResult.failed(&"scenario_already_running", "A scenario program is already active.")
	if _definition.program_by_id(program_id) == null:
		return ScenarioVmResult.failed(&"unknown_scenario_program", "Scenario program '%s' is unavailable." % program_id)
	var frame := ScenarioFrame.new(ScenarioFrame.PROGRAM, program_id)
	frame.set_context(context)
	_frames.append(frame)
	_halted = false
	_step_count = 0
	_last_outcome = null
	_append_trace({"event": "start", "programId": program_id})
	return ScenarioVmResult.completed()


func run(runtime_api: RealmzRuntimeApi) -> ScenarioVmResult:
	if _halted:
		return ScenarioVmResult.completed([], _last_outcome)
	if _pending_request != null:
		return ScenarioVmResult.failed(&"interaction_pending", "The Scenario VM is waiting for interaction '%s'." % _pending_request.request_id)
	var events: Array[DomainEvent] = []
	while not _frames.is_empty():
		_step_count += 1
		if _step_count > _execution_step_limit:
			return _fail(&"scenario_step_limit", "Scenario execution exceeded %s steps." % _execution_step_limit, events)
		var frame: ScenarioFrame = _frames.back()
		var result: ScenarioVmResult = _execute_program_frame(frame, runtime_api) if frame.kind == ScenarioFrame.PROGRAM else _execute_action_frame(frame, runtime_api)
		events.append_array(result.events)
		if result.state == ScenarioVmResult.State.WAITING:
			return ScenarioVmResult.waiting(result.interaction, events)
		if result.state == ScenarioVmResult.State.FAILED:
			return _fail(result.error_code, result.error_message, events)
	_halted = true
	return ScenarioVmResult.completed(events, _last_outcome)


func resume(response: InteractionResponse, runtime_api: RealmzRuntimeApi) -> ScenarioVmResult:
	if _pending_request == null:
		return ScenarioVmResult.failed(&"no_interaction_pending", "The Scenario VM has no interaction to resume.")
	if response == null or response.request_id != _pending_request.request_id:
		return ScenarioVmResult.failed(&"interaction_mismatch", "The interaction response does not match the issuing VM request.")
	var events: Array[DomainEvent] = []
	var continuation := _pending_continuation.duplicate(true)
	var request_id := _pending_request.request_id
	_pending_request = null
	_pending_continuation.clear()
	_append_trace({"event": "resume", "requestId": request_id, "kind": continuation.get("kind", "")})
	match continuation.get("kind"):
		"safe-operation":
			var operation := runtime_api.resume_safe(continuation.get("runtime", {}), response, _next_request_id())
			if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
				return _fail(operation.error_code, operation.error_message, events)
			events.append_array(operation.events)
			if operation.state == ScenarioRuntimeOperationResult.State.WAITING:
				_pending_request = operation.interaction
				_pending_continuation = {"kind": "safe-operation", "frameIndex": continuation.get("frameIndex", -1), "resultTarget": continuation.get("resultTarget", ""), "runtime": operation.continuation.duplicate(true)}
				_append_trace({"event": "yield", "requestId": operation.interaction.request_id, "kind": String(operation.interaction.kind)})
				return ScenarioVmResult.waiting(operation.interaction, events)
			var frame_index: int = int(continuation.get("frameIndex", -1))
			if frame_index < 0 or frame_index >= _frames.size() or _frames[frame_index].kind != ScenarioFrame.ACTION:
				return _fail(&"invalid_vm_continuation", "Scenario Action continuation frame is unavailable.", events)
			var result_target: String = str(continuation.get("resultTarget", ""))
			if not result_target.is_empty():
				_frames[frame_index].set_local(result_target, operation.value)
		"classic-operation":
			var operation := runtime_api.resume_classic(continuation.get("runtime", {}), response, _next_request_id())
			if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
				return _fail(operation.error_code, operation.error_message, events)
			events.append_array(operation.events)
			if operation.state == ScenarioRuntimeOperationResult.State.WAITING:
				_pending_request = operation.interaction
				_pending_continuation = {"kind": "classic-operation", "runtime": operation.continuation.duplicate(true)}
				_append_trace({"event": "yield", "requestId": operation.interaction.request_id, "kind": String(operation.interaction.kind)})
				return ScenarioVmResult.waiting(operation.interaction, events)
			var directive_result := _apply_classic_directive(operation.directive)
			if directive_result.state == ScenarioVmResult.State.FAILED:
				return _fail(directive_result.error_code, directive_result.error_message, events)
		_:
			return _fail(&"unknown_interaction_continuation", "Scenario VM continuation kind is unavailable.", events)
	var resumed := run(runtime_api)
	events.append_array(resumed.events)
	if resumed.state == ScenarioVmResult.State.WAITING:
		return ScenarioVmResult.waiting(resumed.interaction, events)
	if resumed.state == ScenarioVmResult.State.FAILED:
		return ScenarioVmResult.failed(resumed.error_code, resumed.error_message, events)
	return ScenarioVmResult.completed(events, resumed.outcome)


func snapshot() -> ScenarioVmSnapshot:
	var result := ScenarioVmSnapshot.new()
	for frame: ScenarioFrame in _frames:
		result.frames.append(ScenarioFrame.from_data(frame.to_data()))
	result.pending_request = InteractionRequest.from_data(_pending_request.to_data()) if _pending_request != null else null
	result.pending_continuation = _pending_continuation.duplicate(true)
	result.trace = _trace.duplicate(true)
	result.request_counter = _request_counter
	result.step_count = _step_count
	result.halted = _halted
	result.last_outcome = _last_outcome
	return result


func restore(value: Variant) -> bool:
	var saved := value as ScenarioVmSnapshot
	if saved == null or _definition == null or saved.frames.size() > CLASSIC_CALL_LIMIT + ACTION_CALL_LIMIT + 1:
		return false
	var action_depth := 0
	var classic_depth := 0
	for frame: ScenarioFrame in saved.frames:
		if frame.kind == ScenarioFrame.PROGRAM:
			var program := _definition.program_by_id(frame.definition_id)
			if program == null or frame.cursor > program.instruction_count():
				return false
			if frame.counts_as_classic_call:
				classic_depth += 1
		else:
			var action := _definition.action_by_id(frame.definition_id)
			if action == null or frame.cursor > action.program.instruction_count():
				return false
			action_depth += 1

	if action_depth > ACTION_CALL_LIMIT or classic_depth > CLASSIC_CALL_LIMIT:
		return false
	_frames.clear()
	for frame: ScenarioFrame in saved.frames:
		_frames.append(ScenarioFrame.from_data(frame.to_data()))
	_pending_request = InteractionRequest.from_data(saved.pending_request.to_data()) if saved.pending_request != null else null
	_pending_continuation = saved.pending_continuation.duplicate(true)
	_trace = saved.trace.duplicate(true)
	_request_counter = saved.request_counter
	_step_count = saved.step_count
	_halted = saved.halted
	_last_outcome = saved.last_outcome
	return true


func trace() -> Array[Dictionary]:
	return _trace.duplicate(true)


func is_active() -> bool:
	return not _halted and not _frames.is_empty()


func pending_request() -> InteractionRequest:
	return _pending_request


func _execute_program_frame(frame: ScenarioFrame, runtime_api: RealmzRuntimeApi) -> ScenarioVmResult:
	if frame.cursor == 0 and frame.context_value("_programResolved") != true:
		var original_program_id := frame.definition_id
		var resolved_program_id := runtime_api.resolve_program_id(original_program_id)
		if _definition.program_by_id(resolved_program_id) == null:
			return ScenarioVmResult.failed(&"unknown_scenario_program", "Scenario program override for '%s' references unavailable program '%s'." % [original_program_id, resolved_program_id])
		var resolved_context := frame.context_data()
		resolved_context["_programResolved"] = true
		resolved_context["originalProgramId"] = original_program_id
		frame.set_context(resolved_context)
		frame.definition_id = resolved_program_id
		if resolved_program_id != original_program_id:
			_append_trace({"event": "program-override", "sourceProgramId": original_program_id, "targetProgramId": resolved_program_id})
	var program := _definition.program_by_id(frame.definition_id)
	if program == null:
		return ScenarioVmResult.failed(&"unknown_scenario_program", "Scenario program '%s' disappeared during execution." % frame.definition_id)
	if frame.cursor >= program.instruction_count():
		_return_from_frame(null)
		return ScenarioVmResult.completed()
	var instruction: Variant = program.instruction_at(frame.cursor)
	if instruction is CallScenarioActionInstruction:
		var action_call: CallScenarioActionInstruction = instruction
		var arguments_result := _evaluate_call_arguments(action_call, frame, runtime_api)
		if not arguments_result["ok"]:
			return ScenarioVmResult.failed(&"safe_expression_failed", arguments_result["error"])
		frame.cursor += 1
		return _push_action(action_call.action_id, arguments_result["value"], action_call.result_target, _calling_context(frame, program), frame.context_data(), true)
	if not instruction is ClassicActionDefinition:
		return ScenarioVmResult.failed(&"unknown_scenario_instruction", "Scenario program '%s' contains an unknown instruction." % program.id)
	var action: ClassicActionDefinition = instruction
	_append_trace({"event": "execute-classic", "programId": program.id, "cursor": frame.cursor, "slot": action.slot, "rawOpcode": action.raw_opcode, "opcode": action.opcode, "id": action.operand_id})
	match action.opcode:
		39:
			var target_id := "xap:%d" % action.operand_id
			if _definition.program_by_id(target_id) == null:
				return ScenarioVmResult.failed(&"unknown_scenario_program", "Classic opcode 39 references unavailable XAP %d." % action.operand_id)
			var replacement := ScenarioFrame.new(ScenarioFrame.PROGRAM, target_id)
			replacement.counts_as_classic_call = frame.counts_as_classic_call
			var transfer_context := frame.context_data()
			transfer_context["originProgramId"] = program.id
			replacement.set_context(transfer_context)
			_frames[_frames.size() - 1] = replacement
			_append_trace({"event": "classic-transfer", "programId": target_id})
			return ScenarioVmResult.completed()
		111:
			_append_trace({"event": "classic-return", "programId": program.id})
			_return_from_frame(null)
			return ScenarioVmResult.completed()
		112:
			frame.cursor += 1
			_pop_classic_caller_below_top()
			return ScenarioVmResult.completed()
	var request_id := _next_request_id()
	var operation := runtime_api.execute_classic(action, request_id, frame.context_data())
	frame.cursor += 1
	if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
		return ScenarioVmResult.failed(operation.error_code, operation.error_message)
	if operation.state == ScenarioRuntimeOperationResult.State.WAITING:
		_pending_request = operation.interaction
		_pending_continuation = {"kind": "classic-operation", "runtime": operation.continuation.duplicate(true)}
		_append_trace({"event": "yield", "requestId": request_id, "kind": String(operation.interaction.kind)})
		return ScenarioVmResult.waiting(operation.interaction, operation.events)
	var directive_result := _apply_classic_directive(operation.directive, frame.context_data())
	if directive_result.state == ScenarioVmResult.State.FAILED:
		return directive_result
	return ScenarioVmResult.completed(operation.events)


func _apply_classic_directive(directive: Dictionary, inherited_context: Dictionary = {}) -> ScenarioVmResult:
	if directive.is_empty():
		return ScenarioVmResult.completed()
	match directive.get("kind"):
		"finish":
			_return_from_frame(null)
			return ScenarioVmResult.completed()
		"branch-xap":
			var program_id := "xap:%d" % int(directive.get("targetId", -1))
			if _definition.program_by_id(program_id) == null:
				return ScenarioVmResult.failed(&"unknown_scenario_program", "Classic branch references unavailable XAP %d." % int(directive.get("targetId", -1)))
			var target_frame := ScenarioFrame.new(ScenarioFrame.PROGRAM, program_id)
			target_frame.set_context(inherited_context)
			if bool(directive.get("gosub", false)):
				if _classic_call_depth() >= CLASSIC_CALL_LIMIT:
					return ScenarioVmResult.failed(&"classic_gosub_limit", "Classic GOSUB stack exceeded 20 frames.")
				target_frame.counts_as_classic_call = true
				_frames.append(target_frame)
			else:
				_frames[_frames.size() - 1] = target_frame
			_append_trace({"event": "classic-branch", "programId": program_id, "gosub": bool(directive.get("gosub", false))})
			return ScenarioVmResult.completed()
		"branch-program":
			var program_id: String = str(directive.get("programId", ""))
			if _definition.program_by_id(program_id) == null:
				return ScenarioVmResult.failed(&"unknown_scenario_program", "Classic branch references unavailable program '%s'." % program_id)
			var target_frame := ScenarioFrame.new(ScenarioFrame.PROGRAM, program_id)
			target_frame.counts_as_classic_call = bool(directive.get("gosub", false))
			var context: Variant = directive.get("context", {})
			if not context is Dictionary:
				return ScenarioVmResult.failed(&"invalid_vm_directive", "Classic branch context is malformed.")
			var merged_context := inherited_context.duplicate(true)
			for key: Variant in context:
				merged_context[key] = context[key]
			target_frame.set_context(merged_context)
			if target_frame.counts_as_classic_call:
				if _classic_call_depth() >= CLASSIC_CALL_LIMIT:
					return ScenarioVmResult.failed(&"classic_gosub_limit", "Classic GOSUB stack exceeded 20 frames.")
				_frames.append(target_frame)
			else:
				_frames[_frames.size() - 1] = target_frame
			_append_trace({"event": "classic-branch", "programId": program_id, "gosub": target_frame.counts_as_classic_call})
			return ScenarioVmResult.completed()
		_:
			return ScenarioVmResult.failed(&"unknown_vm_directive", "Realmz Runtime API returned an unknown VM directive.")


func _execute_action_frame(frame: ScenarioFrame, runtime_api: RealmzRuntimeApi) -> ScenarioVmResult:
	var action := _definition.action_by_id(frame.definition_id)
	if action == null:
		return ScenarioVmResult.failed(&"unknown_scenario_action", "Scenario Action '%s' disappeared during execution." % frame.definition_id)
	if frame.cursor >= action.program.instruction_count():
		if action.return_type != &"void":
			return ScenarioVmResult.failed(&"scenario_action_missing_return", "Scenario Action '%s' completed without its declared return value." % action.id)
		_return_from_frame(null)
		return ScenarioVmResult.completed()
	var instruction := action.program.instruction_at(frame.cursor)
	_append_trace({"event": "execute-action", "actionId": action.id, "cursor": frame.cursor, "instructionKind": instruction.kind})
	match instruction.kind:
		SafeInstructionDefinition.Kind.OPERATION:
			var arguments_result := _evaluate_safe_arguments(instruction, frame, runtime_api)
			if not arguments_result["ok"]:
				return ScenarioVmResult.failed(&"safe_expression_failed", arguments_result["error"])
			var request_id := _next_request_id()
			var operation := runtime_api.execute_safe(instruction.capability, arguments_result["value"], request_id)

			frame.cursor += 1
			if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
				return ScenarioVmResult.failed(operation.error_code, operation.error_message)
			if operation.state == ScenarioRuntimeOperationResult.State.WAITING:
				_pending_request = operation.interaction
				_pending_continuation = {"kind": "safe-operation", "frameIndex": _frames.size() - 1, "resultTarget": instruction.result_target, "runtime": operation.continuation.duplicate(true)}
				_append_trace({"event": "yield", "requestId": request_id, "kind": String(operation.interaction.kind), "actionId": action.id})
				return ScenarioVmResult.waiting(operation.interaction, operation.events)
			if not instruction.result_target.is_empty():
				frame.set_local(instruction.result_target, operation.value)
			return ScenarioVmResult.completed(operation.events)
		SafeInstructionDefinition.Kind.CALL_ACTION:
			var arguments_result := _evaluate_safe_arguments(instruction, frame, runtime_api)
			if not arguments_result["ok"]:
				return ScenarioVmResult.failed(&"safe_expression_failed", arguments_result["error"])
			frame.cursor += 1
			return _push_action(instruction.action_id, arguments_result["value"], instruction.result_target, StringName(frame.context_value("callingContext")), frame.context_data(), false)
		SafeInstructionDefinition.Kind.SET_VALUE:
			var evaluated := _evaluate(instruction.value, frame, runtime_api)
			if not evaluated["ok"]:
				return ScenarioVmResult.failed(&"safe_expression_failed", evaluated["error"])
			if instruction.scope == &"local":
				frame.set_local(instruction.name, evaluated["value"])
			else:
				var state_scope := instruction.state_scope if not instruction.state_scope.is_empty() else "campaign"
				var owner_id := instruction.owner_id if not instruction.owner_id.is_empty() else frame.definition_id
				if not runtime_api.write_action_state(state_scope, owner_id, instruction.name, evaluated["value"]):
					return ScenarioVmResult.failed(&"scenario_state_limit", "Scenario Action state rejected an unsafe or oversized value.")
			frame.cursor += 1
			return ScenarioVmResult.completed()
		SafeInstructionDefinition.Kind.JUMP_IF_FALSE:
			var evaluated := _evaluate(instruction.condition, frame, runtime_api)
			if not evaluated["ok"] or not evaluated["value"] is bool:
				return ScenarioVmResult.failed(&"safe_expression_failed", evaluated.get("error", "Safe condition did not evaluate to bool."))
			frame.cursor = frame.cursor + 1 if evaluated["value"] else instruction.target
			return ScenarioVmResult.completed()
		SafeInstructionDefinition.Kind.JUMP:
			frame.cursor = instruction.target
			return ScenarioVmResult.completed()
		SafeInstructionDefinition.Kind.BEGIN_FOR_EACH:
			return _begin_for_each(frame, instruction, runtime_api)
		SafeInstructionDefinition.Kind.NEXT_FOR_EACH:
			return _next_for_each(frame, instruction)
		SafeInstructionDefinition.Kind.RETURN:
			var return_value: Variant = null
			if instruction.value != null:
				var evaluated := _evaluate(instruction.value, frame, runtime_api)
				if not evaluated["ok"]:
					return ScenarioVmResult.failed(&"safe_expression_failed", evaluated["error"])
				return_value = evaluated["value"]
			if not _value_matches_type(return_value, action.return_type):
				return ScenarioVmResult.failed(&"scenario_action_return_type", "Scenario Action '%s' returned a value outside its declared type." % action.id)
			_return_from_frame(return_value)
			return ScenarioVmResult.completed()
		SafeInstructionDefinition.Kind.HALT:
			_frames.clear()
			_halted = true
			_last_outcome = instruction.outcome
			return ScenarioVmResult.completed([], instruction.outcome)
	return ScenarioVmResult.failed(&"unknown_scenario_instruction", "Scenario Action contains an unavailable instruction kind.")


func _push_action(action_id: String, arguments: Dictionary, return_target: String, calling_context: StringName, inherited_context: Dictionary, require_public: bool) -> ScenarioVmResult:
	var action := _definition.action_by_id(action_id)
	if action == null:
		return ScenarioVmResult.failed(&"unknown_scenario_action", "Scenario Action '%s' is unavailable." % action_id)
	if require_public and action.visibility != &"public":
		return ScenarioVmResult.failed(&"private_scenario_action", "Private Scenario Action '%s' cannot be called from an authored timeline." % action_id)
	if calling_context == &"" or not action.allowed_contexts().has(calling_context):
		return ScenarioVmResult.failed(&"scenario_action_context", "Scenario Action '%s' is not allowed in context '%s'." % [action_id, calling_context])
	var parameters := action.parameters()
	if arguments.size() != parameters.size():
		return ScenarioVmResult.failed(&"scenario_action_arguments", "Scenario Action '%s' received the wrong argument set." % action_id)
	for parameter: ScenarioActionParameter in parameters:
		if not arguments.has(parameter.name) or not _value_matches_type(arguments[parameter.name], parameter.value_type, parameter.max_length):
			return ScenarioVmResult.failed(&"scenario_action_arguments", "Scenario Action '%s' received an invalid '%s' argument." % [action_id, parameter.name])
	if _action_call_depth() >= ACTION_CALL_LIMIT:
		return ScenarioVmResult.failed(&"scenario_action_call_limit", "Scenario Action call stack exceeded 32 frames.")
	var frame := ScenarioFrame.new(ScenarioFrame.ACTION, action_id)
	frame.return_target = return_target
	frame.set_parameters(arguments)
	var context := inherited_context.duplicate(true)
	context["callingContext"] = String(calling_context)
	frame.set_context(context)
	_frames.append(frame)
	_append_trace({"event": "call-action", "actionId": action_id, "depth": _action_call_depth()})
	return ScenarioVmResult.completed()


func _return_from_frame(value: Variant) -> void:
	if _frames.is_empty():
		return
	var finished: ScenarioFrame = _frames.pop_back()
	_append_trace({"event": "return", "definitionId": finished.definition_id, "kind": String(finished.kind)})
	if _frames.is_empty():
		_halted = true
		_last_outcome = value
		return
	if finished.kind == ScenarioFrame.ACTION and not finished.return_target.is_empty():
		_frames.back().set_local(finished.return_target, value)


func _begin_for_each(frame: ScenarioFrame, instruction: SafeInstructionDefinition, runtime_api: RealmzRuntimeApi) -> ScenarioVmResult:
	var evaluated := _evaluate(instruction.collection, frame, runtime_api)
	if not evaluated["ok"] or not evaluated["value"] is Array:
		return ScenarioVmResult.failed(&"safe_expression_failed", evaluated.get("error", "For-each input is not an array."))
	var values: Array = evaluated["value"]
	if values.size() > 256:
		return ScenarioVmResult.failed(&"safe_array_limit", "For-each input exceeds 256 entries.")
	if values.is_empty():
		frame.cursor = instruction.target
		return ScenarioVmResult.completed()
	frame.push_iterator({"beginTarget": frame.cursor, "index": 0, "values": values.duplicate(true), "itemName": instruction.item_name, "hadPrevious": frame.has_local(instruction.item_name), "previous": frame.local(instruction.item_name)})
	frame.set_local(instruction.item_name, values[0])
	frame.cursor += 1
	return ScenarioVmResult.completed()


func _next_for_each(frame: ScenarioFrame, instruction: SafeInstructionDefinition) -> ScenarioVmResult:
	if not frame.has_iterator():
		return ScenarioVmResult.failed(&"invalid_safe_program", "For-each continuation has no active iterator.")
	var iterator: Dictionary = frame.current_iterator()
	if iterator.get("beginTarget") != instruction.target:
		return ScenarioVmResult.failed(&"invalid_safe_program", "For-each continuation target does not match its iterator.")
	iterator["index"] += 1
	if iterator["index"] < iterator["values"].size():
		frame.set_local(iterator["itemName"], iterator["values"][iterator["index"]])
		frame.update_current_iterator(iterator)
		frame.cursor = instruction.target + 1
		return ScenarioVmResult.completed()
	frame.pop_iterator()
	if iterator["hadPrevious"]:
		frame.set_local(iterator["itemName"], iterator["previous"])
	else:
		frame.erase_local(iterator["itemName"])
	frame.cursor += 1
	return ScenarioVmResult.completed()


func _evaluate_call_arguments(action_call: CallScenarioActionInstruction, frame: ScenarioFrame, runtime_api: RealmzRuntimeApi) -> Dictionary:
	var result: Dictionary = {}
	for name: String in action_call.argument_names():
		var evaluated := _evaluate(action_call.argument(name), frame, runtime_api)
		if not evaluated["ok"]:
			return evaluated
		result[name] = evaluated["value"]
	return {"ok": true, "value": result}


func _evaluate_safe_arguments(instruction: SafeInstructionDefinition, frame: ScenarioFrame, runtime_api: RealmzRuntimeApi) -> Dictionary:
	var result: Dictionary = {}
	for name: String in instruction.argument_names():
		var evaluated := _evaluate(instruction.argument(name), frame, runtime_api)
		if not evaluated["ok"]:
			return evaluated
		result[name] = evaluated["value"]
	return {"ok": true, "value": result}


func _evaluate(expression: SafeExpressionDefinition, frame: ScenarioFrame, runtime_api: RealmzRuntimeApi) -> Dictionary:

	if expression == null:
		return {"ok": false, "error": "Safe expression is missing."}
	match expression.kind:
		SafeExpressionDefinition.Kind.LITERAL:
			return {"ok": true, "value": expression.value}
		SafeExpressionDefinition.Kind.VARIABLE:
			match expression.scope:
				&"parameter":
					return {"ok": true, "value": frame.parameter(expression.name)}
				&"local":
					if not frame.has_local(expression.name):
						return {"ok": false, "error": "Safe local '%s' is undefined." % expression.name}
					return {"ok": true, "value": frame.local(expression.name)}
				&"context":
					return {"ok": true, "value": frame.context_value(expression.name)}
				&"persistent":
					var state_scope := expression.state_scope if not expression.state_scope.is_empty() else "campaign"
					var owner_id := expression.owner_id if not expression.owner_id.is_empty() else frame.definition_id
					return {"ok": true, "value": runtime_api.read_action_state(state_scope, owner_id, expression.name)}
		SafeExpressionDefinition.Kind.ARRAY:
			var values: Array = []
			for child: SafeExpressionDefinition in expression.values():
				var evaluated := _evaluate(child, frame, runtime_api)
				if not evaluated["ok"]:
					return evaluated
				values.append(evaluated["value"])
			return {"ok": true, "value": values}
		SafeExpressionDefinition.Kind.RECORD:
			var fields: Dictionary = {}
			for field_name: String in expression.field_names():
				var evaluated := _evaluate(expression.field(field_name), frame, runtime_api)
				if not evaluated["ok"]:
					return evaluated
				fields[field_name] = evaluated["value"]
			return {"ok": true, "value": fields}
		SafeExpressionDefinition.Kind.UNARY:
			var operand := _evaluate(expression.operand, frame, runtime_api)
			if not operand["ok"]:
				return operand
			if expression.operator == &"not" and operand["value"] is bool:
				return {"ok": true, "value": not operand["value"]}
			if expression.operator == &"-" and _is_number(operand["value"]):
				return {"ok": true, "value": -operand["value"]}
			return {"ok": false, "error": "Safe unary operator '%s' received an invalid operand." % expression.operator}
		SafeExpressionDefinition.Kind.BINARY:
			var left_result := _evaluate(expression.left, frame, runtime_api)
			var right_result := _evaluate(expression.right, frame, runtime_api)
			if not left_result["ok"]:
				return left_result
			if not right_result["ok"]:
				return right_result
			return _evaluate_binary(expression.operator, left_result["value"], right_result["value"])
		SafeExpressionDefinition.Kind.MEMBER:
			var object_result := _evaluate(expression.object, frame, runtime_api)
			if not object_result["ok"]:
				return object_result
			if not object_result["value"] is Dictionary or not object_result["value"].has(expression.member):
				return {"ok": false, "error": "Safe member '%s' is unavailable." % expression.member}
			return {"ok": true, "value": object_result["value"][expression.member]}
		SafeExpressionDefinition.Kind.COLLECTION:
			return _evaluate_collection(expression, frame, runtime_api)
	return {"ok": false, "error": "Safe expression kind is unavailable."}


func _evaluate_binary(operator: StringName, left: Variant, right: Variant) -> Dictionary:
	match operator:
		&"==": return {"ok": true, "value": left == right}
		&"!=": return {"ok": true, "value": left != right}
		&"and", &"or":
			if left is bool and right is bool:
				return {"ok": true, "value": left and right if operator == &"and" else left or right}
		&"+":
			if _is_number(left) and _is_number(right) or left is String and right is String:
				return {"ok": true, "value": left + right}
		&"-", &"*", &"/":
			if _is_number(left) and _is_number(right) and not (operator == &"/" and right == 0):
				match operator:
					&"-": return {"ok": true, "value": left - right}
					&"*": return {"ok": true, "value": left * right}
					&"/": return {"ok": true, "value": left / right}
		&"<", &"<=", &">", &">=":
			if _is_number(left) and _is_number(right):
				match operator:
					&"<": return {"ok": true, "value": left < right}
					&"<=": return {"ok": true, "value": left <= right}
					&">": return {"ok": true, "value": left > right}
					&">=": return {"ok": true, "value": left >= right}
	return {"ok": false, "error": "Safe binary operator '%s' received incompatible values." % operator}


func _evaluate_collection(expression: SafeExpressionDefinition, frame: ScenarioFrame, runtime_api: RealmzRuntimeApi) -> Dictionary:
	var collection_result := _evaluate(expression.collection, frame, runtime_api)
	if not collection_result["ok"] or not collection_result["value"] is Array:
		return {"ok": false, "error": "Safe collection expression input is not an array."}
	var values: Array = collection_result["value"]
	if values.size() > 256:
		return {"ok": false, "error": "Safe collection exceeds 256 entries."}
	if expression.operator == &"count":
		return {"ok": true, "value": values.size()}
	if expression.operator == &"first" and expression.predicate == null:
		return {"ok": true, "value": values[0] if not values.is_empty() else null}
	var had_previous := frame.has_local(expression.item_name)
	var previous: Variant = frame.local(expression.item_name)
	var matches: Array = []
	for value: Variant in values:
		frame.set_local(expression.item_name, value)
		var predicate := _evaluate(expression.predicate, frame, runtime_api)
		if not predicate["ok"] or not predicate["value"] is bool:
			_restore_local(frame, expression.item_name, had_previous, previous)
			return {"ok": false, "error": "Safe collection predicate did not evaluate to bool."}
		matches.append(predicate["value"])
	_restore_local(frame, expression.item_name, had_previous, previous)
	match expression.operator:
		&"any": return {"ok": true, "value": matches.has(true)}
		&"all": return {"ok": true, "value": not matches.has(false)}
		&"first":
			for index: int in range(matches.size()):
				if matches[index]:
					return {"ok": true, "value": values[index]}
			return {"ok": true, "value": null}
	return {"ok": false, "error": "Safe collection operation '%s' is unavailable." % expression.operator}


func _restore_local(frame: ScenarioFrame, name: String, had_previous: bool, previous: Variant) -> void:
	if had_previous:
		frame.set_local(name, previous)
	else:
		frame.erase_local(name)


func _pop_classic_caller_below_top() -> void:
	for index: int in range(_frames.size() - 2, -1, -1):
		if _frames[index].kind == ScenarioFrame.PROGRAM and _frames[index + 1].counts_as_classic_call:
			_frames.remove_at(index)
			_frames[index].counts_as_classic_call = false
			return


func _action_call_depth() -> int:
	var count := 0
	for frame: ScenarioFrame in _frames:
		if frame.kind == ScenarioFrame.ACTION:
			count += 1
	return count


func _classic_call_depth() -> int:
	var count := 0
	for frame: ScenarioFrame in _frames:
		if frame.counts_as_classic_call:
			count += 1
	return count


func _calling_context(frame: ScenarioFrame, program: ScenarioProgramDefinition) -> StringName:
	var explicit: Variant = frame.context_value("callingContext")
	if explicit is String and not explicit.is_empty():
		return StringName(explicit)
	match program.owner_kind:
		&"simple-encounter-result", &"complex-encounter-result":

	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 120 requires a five-value Extra Code row.")
	var target_kind := action.extra_code[0]
	var definition := _content.monster_by_classic_id(absi(action.extra_code[1]))
	var remaining := maxi(0, action.extra_code[2])
	if target_kind < 1 or target_kind > 2 or definition == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_combat_monster_target", "Classic opcode 120 references an unavailable monster kind or identity.")
	var candidates := _game_state.party.allies() if target_kind == 1 else _game_state.combat.monsters()
	var altered: Array[String] = []
	for monster: MonsterState in candidates:
		if remaining <= 0:
			break
		if monster.definition_id != definition.id:
			continue
		if action.extra_code[3] != -1:
			monster.icon_id = action.extra_code[3]
			altered.append(monster.id)
			remaining -= 1
		elif action.extra_code[4] != -1 and monster.traitor != (action.extra_code[4] != 0):
			monster.traitor = action.extra_code[4] != 0
			altered.append(monster.id)
			remaining -= 1
	return ScenarioRuntimeOperationResult.completed(altered.size(), [DomainEvent.new(&"combat_monsters_altered", {"count": altered.size(), "monsterIds": altered, "classicMonsterId": definition.classic_id, "targetKind": target_kind, "source": "classic"})])


func _cause_monsters_to_route(action: ClassicActionDefinition, context: Dictionary) -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.completed(0, [DomainEvent.new(&"combat_route_applied", {"count": 0, "reason": "no-active-battle", "source": "classic"})])
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 123 requires a five-value Extra Code row.")
	var source_traitor := true
	var source_id := str(context.get("combatantId", ""))
	var source_monster := _game_state.combat.monster_by_id(source_id)
	if source_monster != null:
		source_traitor = source_monster.traitor
	var definition_ids: Dictionary = {}
	for classic_id: int in action.extra_code:
		if classic_id == 0:
			continue
		var definition := _content.monster_by_classic_id(absi(classic_id))
		if definition == null:
			return ScenarioRuntimeOperationResult.failed(&"unknown_monster", "Classic opcode 123 references unavailable monster %d." % classic_id)
		definition_ids[definition.id] = true
	var routed: Array[String] = []
	for monster: MonsterState in _game_state.combat.monsters():
		if monster.current_health > 0 and monster.traitor == source_traitor and definition_ids.has(monster.definition_id):
			monster.conditions.set_value(ConditionRules.RUNS_AWAY, -1)
			monster.surrender_percent = 50
			routed.append(monster.id)
	return ScenarioRuntimeOperationResult.completed(routed.size(), [DomainEvent.new(&"combat_route_applied", {"count": routed.size(), "monsterIds": routed, "traitorSide": source_traitor, "source": "classic"})])


func _revive_after_combat_macro(context: Dictionary) -> ScenarioRuntimeOperationResult:
	var living_party := 0
	for character: CharacterState in _game_state.party.characters():
		if character.current_health > 0:
			living_party += 1
	if living_party == 0:
		var revived_party: Array[String] = []
		for character: CharacterState in _game_state.party.characters():
			character.current_health = 1
			character.conditions.set_value(ConditionRules.ANIMATED, 0)
			revived_party.append(character.id)
		return ScenarioRuntimeOperationResult.completed(revived_party, [DomainEvent.new(&"party_revived", {"characterIds": revived_party, "source": "classic-death-macro"})], {"kind": "finish"})
	if _game_state.combat == null:
		return ScenarioRuntimeOperationResult.failed(&"revival_outside_combat", "Classic opcode 119 has no combatant to revive.")
	var combatant_id := str(context.get("combatantId", ""))
	var monster := _game_state.combat.monster_by_id(combatant_id)
	if monster == null:
		return ScenarioRuntimeOperationResult.failed(&"missing_combatant_context", "Classic opcode 119 requires its death-macro combatant identity.")
	monster.current_health = 1
	monster.traitor = false
	return ScenarioRuntimeOperationResult.completed(monster.id, [DomainEvent.new(&"monster_revived", {"monsterId": monster.id, "source": "classic-death-macro"})])


func resolve_program_id(program_id: String) -> String:
	return _control_flow_operations.resolve_program_id(program_id)


func execute_safe(capability: String, arguments: Dictionary, request_id: String) -> ScenarioRuntimeOperationResult:
	match capability:
		"core.party.camp":
			if not arguments.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "Camp does not accept arguments.")
			if not _game_state.camping_allowed or _game_state.combat != null and not _game_state.combat.completed:
				return ScenarioRuntimeOperationResult.failed(&"camping_unavailable", "The party cannot camp in the current state.")
			return ScenarioRuntimeOperationResult.completed(true, _rules.clock.camp(_game_state))
		"core.time.advance":
			if not _whole_number(arguments.get("minutes")) or int(arguments["minutes"]) < 0:
				return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "Advance Time requires non-negative integer minutes.")
			return ScenarioRuntimeOperationResult.completed(true, _rules.clock.advance_minutes(_game_state, int(arguments["minutes"])))
		"core.inventory.grant-item":
			if not arguments.get("characterId") is String or not arguments.get("itemId") is String or arguments.get("identified", false) is not bool:
				return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "Grant Item requires characterId, itemId, and optional identified bool.")
			return _grant_item(arguments["characterId"], arguments["itemId"], arguments.get("identified", false))
		"core.economy.grant-treasure":
			if not arguments.get("treasureId") is String:
				return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "Grant Treasure requires a stable treasureId.")
			var treasure := _content.treasure_by_id(arguments["treasureId"])
			if treasure == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_treasure", "Treasure '%s' is unavailable." % arguments["treasureId"])
			return _grant_treasure_definition(treasure)
		"core.economy.take-gold":
			if not _whole_number(arguments.get("amount")) or int(arguments["amount"]) < 0:
				return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "Take Gold requires a non-negative integer amount.")
			var amount := int(arguments["amount"])
			var paid := _rules.economy.take(_game_state.party, amount, WealthState.Kind.GOLD)
			return ScenarioRuntimeOperationResult.completed(paid, [DomainEvent.new(&"wealth_taken", {"amount": amount, "kind": WealthState.Kind.GOLD, "paid": paid, "source": "scenario-action"})])
		"core.combat.start":
			if not arguments.get("battleId") is String:
				return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "Start Battle requires a stable battleId.")
			var battle := _content.battle_by_id(arguments["battleId"])
			if battle == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_battle", "Battle '%s' is unavailable." % arguments["battleId"])
			return _start_battle_definition(battle, request_id, "scenario-action")
		"core.presentation.text":
			if not arguments.get("text") is String:
				return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "Show Text requires a string 'text' argument.")
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new("message_shown", {"text": arguments["text"], "source": "scenario-action"})])
		"core.presentation.choice":
			if not arguments.get("prompt") is String or not arguments.get("options") is Array or arguments["options"].is_empty() or arguments["options"].size() > 256:
				return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "Choice requires a prompt and one to 256 options.")
			var options: Array[Dictionary] = []
			for index: int in range(arguments["options"].size()):
				var label: Variant = arguments["options"][index]
				if not label is String:
					return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "Choice option %d is not a string." % index)
				options.append({"id": "choice:%d" % index, "label": label})
			var request := InteractionRequest.new(request_id, &"scenario_choice", {"prompt": arguments["prompt"], "options": options})
			return ScenarioRuntimeOperationResult.waiting(request, {"kind": "safe-choice", "optionCount": options.size()})
		"core.state.read":
			var state_identity := _state_identity(arguments)
			if state_identity.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "State Read requires a valid scope and name or numeric ID.")
			return ScenarioRuntimeOperationResult.completed(_action_state.read(state_identity[0], state_identity[1], state_identity[2], arguments.get("default")))
		"core.state.write":
			var state_identity := _state_identity(arguments)
			if state_identity.is_empty() or not arguments.has("value"):
				return ScenarioRuntimeOperationResult.failed(&"invalid_action_arguments", "State Write requires a valid scope, name or numeric ID, and value.")
			if not _action_state.write(state_identity[0], state_identity[1], state_identity[2], arguments["value"]):
				return ScenarioRuntimeOperationResult.failed(&"scenario_state_limit", "Scenario Action state rejected an unsafe or oversized value.")
			return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new("scenario_state_changed", {"scope": state_identity[0], "ownerId": state_identity[1], "name": state_identity[2]})])
		_:
			return ScenarioRuntimeOperationResult.failed(&"unknown_action_capability", "Scenario Action capability '%s' is not available." % capability)


func resume_safe(continuation: Dictionary, response: InteractionResponse, request_id: String = "") -> ScenarioRuntimeOperationResult:
	match continuation.get("kind"):
		"safe-choice":
			var option_count: int = int(continuation.get("optionCount", 0))
			if response.kind != &"scenario_choice" or not response.payload.get("index") is int or response.payload["index"] < 0 or response.payload["index"] >= option_count:
				return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Scenario choice response must identify an available option.")
			return ScenarioRuntimeOperationResult.completed(response.payload["index"])
		"safe-combat":
			return _resume_battle(continuation, response, request_id if not request_id.is_empty() else String(response.request_id))
		"safe-combat-macro":
			return _resume_battle_macro(continuation, response, request_id if not request_id.is_empty() else String(response.request_id))
		"safe-combat-death-macro":
			return _resume_combat_death_macro(continuation, response, request_id if not request_id.is_empty() else String(response.request_id))
		"safe-combat-ally-selection":

	var selector := action.extra_code[0]
	if selector < 0 or selector > 4:
		return ScenarioRuntimeOperationResult.failed(&"invalid_character_identity_selector", "Classic opcode 50 has an invalid identity selector.")
	var selected: Array[String] = []
	for character: CharacterState in _game_state.party.characters():
		if action.extra_code[4] != 0 and character.current_health <= 0:
			continue
		var race := _content.race_by_id(character.race_id)
		var caste := _content.caste_by_id(character.caste_id)
		var matches := false
		match selector:
			0:
				matches = race != null and race.classic_id == action.extra_code[2]
			1:
				matches = character.gender == action.extra_code[1]
			2:
				matches = caste != null and caste.classic_id == action.extra_code[2]
			3:
				if action.extra_code[2] < 1 or action.extra_code[2] > 32:
					return ScenarioRuntimeOperationResult.failed(&"invalid_race_descriptor", "Classic opcode 50 race descriptor is outside 1 through 32.")
				matches = race != null and (race.descriptor_flags & (1 << (action.extra_code[2] - 1))) != 0
			4:
				matches = caste != null and caste.caste_class == action.extra_code[2]
		if matches:
			selected.append(character.id)
	_game_state.set_selected_character_ids(selected)
	return ScenarioRuntimeOperationResult.completed(selected, [DomainEvent.new(&"characters_selected_by_identity", {"selector": selector, "characterIds": selected, "livingOnly": action.extra_code[4] != 0, "source": "classic"})])


func _grant_random_items(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 3:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 65 requires a five-value Extra Code row.")
	var count := action.extra_code[0]
	if count < 0:
		count = _rng.draw(absi(count), &"classic.random-item-count")
	if count < 0 or count > 20 or action.extra_code[1] > action.extra_code[2]:
		return ScenarioRuntimeOperationResult.failed(&"invalid_random_item_range", "Classic opcode 65 has an invalid count or item range.")
	var granted: Array[String] = []
	var unclaimed: Array[String] = []
	for index: int in count:
		var classic_item_id := _rng.draw_between(action.extra_code[1], action.extra_code[2], StringName("classic.random-item.%d" % index))
		var definition := _content.item_by_classic_id(classic_item_id)
		if definition == null:
			return ScenarioRuntimeOperationResult.failed(&"unknown_item", "Classic opcode 65 generated unavailable item %d." % classic_item_id)
		var assigned := false
		for character: CharacterState in _game_state.party.characters():
			var instance := _rules.inventory.add_item(character, definition, _game_state.next_instance_id("classic.random-item"), false)
			if instance != null:
				granted.append(instance.id)
				assigned = true
				break
		if not assigned:
			unclaimed.append(definition.id)
	return ScenarioRuntimeOperationResult.completed(granted, [DomainEvent.new(&"random_items_granted", {"count": count, "itemInstanceIds": granted, "unclaimedItemIds": unclaimed, "source": "classic"})])


func _level_selected_characters() -> ScenarioRuntimeOperationResult:
	var leveled: Array[String] = []
	for character: CharacterState in _game_state.selected_characters():
		var race := _content.race_by_id(character.race_id)
		var caste := _content.caste_by_id(character.caste_id)
		if race == null or caste == null:
			return ScenarioRuntimeOperationResult.failed(&"unknown_character_profile", "Classic opcode 102 requires source-defined race and caste profiles.")
		character.experience = 1
		if _rules.characters.level_up(character, race, caste, _rng) == null:
			return ScenarioRuntimeOperationResult.failed(&"character_level_failed", "Classic opcode 102 could not level character '%s'." % character.id)
		leveled.append(character.id)
	return ScenarioRuntimeOperationResult.completed(leveled, [DomainEvent.new(&"characters_leveled", {"characterIds": leveled, "source": "classic"})])


func _branch_battle_round_macro(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.failed(&"battle_macro_outside_combat", "Classic opcode 126 requires an active battle macro.")
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 126 requires a five-value Extra Code row.")
	var combat := _game_state.combat
	if combat.macro_id > 0:
		return ScenarioRuntimeOperationResult.completed(false, [], {"kind": "finish"})
	var mode := action.extra_code[0]
	var matched := false
	match mode:
		0:
			matched = combat.round_number - 1 == action.extra_code[1]
		1:
			matched = _rng.draw(100, &"classic.battle-round-macro-percent") <= action.extra_code[1]
		_:
			return ScenarioRuntimeOperationResult.failed(&"invalid_battle_macro_test", "Classic opcode 126 has an invalid round test mode.")
	if not matched:
		return ScenarioRuntimeOperationResult.completed(false, [DomainEvent.new(&"battle_macro_tested", {"matched": false, "mode": mode, "round": combat.round_number, "source": "classic"})], {"kind": "finish"})
	if action.extra_code[2] != 1:
		combat.macro_id = 0
	var target_id := action.extra_code[3]
	if action.extra_code[2] == 2:
		target_id = _rng.draw_between(action.extra_code[3], action.extra_code[4], &"classic.battle-round-macro-target")
	if target_id <= 0:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_macro_target", "Classic opcode 126 references an invalid Extra Action Point target.")
	return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"battle_macro_tested", {"matched": true, "mode": mode, "round": combat.round_number, "targetId": target_id, "repeating": action.extra_code[2] == 1, "source": "classic"})], {"kind": "branch-xap", "targetId": target_id, "gosub": false})


func _continue_if_monster_present(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.failed(&"monster_test_outside_combat", "Classic opcode 127 requires an active battle macro.")
	var definition := _content.monster_by_classic_id(absi(action.operand_id))
	if definition == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_monster", "Classic opcode 127 references unavailable monster %d." % action.operand_id)
	var present := false
	for monster: MonsterState in _game_state.combat.monsters():
		if monster.definition_id == definition.id and monster.current_health > 0:
			present = true
			break
	var directive: Dictionary = {} if present else {"kind": "finish"}
	return ScenarioRuntimeOperationResult.completed(present, [DomainEvent.new(&"battle_monster_presence_checked", {"classicMonsterId": definition.classic_id, "present": present, "source": "classic"})], directive)


func _alter_selected_characters(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 2:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 108 requires a five-value Extra Code row.")
	var alteration := action.extra_code[0]
	var amount := action.extra_code[1]
	if alteration < 1 or alteration > 12:
		return ScenarioRuntimeOperationResult.failed(&"invalid_character_alteration", "Classic opcode 108 references alteration %d outside 1 through 12." % alteration)
	var targets := _game_state.selected_characters()
	for character: CharacterState in targets:
		match alteration:
			1:
				character.attack_bonus = maxi(0, character.attack_bonus + amount)
			2:
				if character.maximum_spell_attacks != 0:
					character.maximum_spell_attacks = maxi(1, character.maximum_spell_attacks + amount)
			3:
				character.maximum_movement = maxi(3, character.maximum_movement + amount)
				character.movement = mini(character.movement, character.maximum_movement)
			4:
				character.damage_bonus = maxi(0, character.damage_bonus + amount)
			5:
				if character.maximum_spell_points != 0:
					character.maximum_spell_points = maxi(0, character.maximum_spell_points + amount)
					character.spell_points = mini(character.spell_points, character.maximum_spell_points)
			6:
				if character.hand_to_hand != 0:
					character.hand_to_hand = maxi(1, character.hand_to_hand + amount)
			7:
				character.maximum_health = maxi(2, character.maximum_health + amount)
				character.current_health = mini(character.current_health, character.maximum_health)
			8:
				character.armor = maxi(0, character.armor + amount)
			9:
				character.to_hit = maxi(2, character.to_hit + amount)
			10:
				character.missile = maxi(2, character.missile + amount)
			11:
				character.magic_resistance = maxi(0, character.magic_resistance + amount)
			12:
				character.prestige_penalty -= amount
	return ScenarioRuntimeOperationResult.completed(targets.size(), [DomainEvent.new(&"selected_characters_altered", {"alteration": alteration, "amount": amount, "characterIds": targets.map(func(character: CharacterState) -> String: return character.id), "source": "classic"})])


func _alter_combat_monsters(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.completed(0, [DomainEvent.new(&"combat_monsters_altered", {"count": 0, "reason": "no-active-battle", "source": "classic"})])

class_name RealmzRuntimeApi
extends RefCounted

const SUPPORTED_SAFE_CAPABILITIES: Array[String] = [
	"core.combat.start",
	"core.economy.grant-treasure",
	"core.economy.take-gold",
	"core.inventory.grant-item",
	"core.party.camp",
	"core.presentation.choice",
	"core.presentation.text",
	"core.state.read",
	"core.state.write",
	"core.time.advance",
]

var _content: RealmzContent
var _game_state: GameState
var _rng: RealmzRng
var _action_state: ScenarioActionState
var _rules: RealmzRules
var _character_operations: ClassicCharacterOperations
var _combat_operations: ClassicCombatOperations
var _control_flow_operations: ClassicControlFlowOperations
var _inventory_operations: ClassicInventoryOperations


func _init(content: RealmzContent, game_state: GameState, rng: RealmzRng, action_state: ScenarioActionState, rules: RealmzRules = null) -> void:
	_content = content
	_game_state = game_state
	_rng = rng
	_action_state = action_state
	_rules = rules if rules != null else RealmzRules.new()
	_character_operations = ClassicCharacterOperations.new(_content, _game_state, _rng, _rules)
	_combat_operations = ClassicCombatOperations.new(_content, _game_state, _rules)
	_control_flow_operations = ClassicControlFlowOperations.new(_content, _game_state)
	_inventory_operations = ClassicInventoryOperations.new(_content, _game_state, _rules)


func execute_classic(action: ClassicActionDefinition, request_id: String, context: Dictionary = {}) -> ScenarioRuntimeOperationResult:
	match action.opcode:
		-23, 23:
			return _mutate_random_region(action, action.opcode == -23)
		-14, 14:
			return _request_character_selection(action, request_id, action.opcode == -14)
		1:
			var message_id := absi(action.operand_id)
			var message := _content.message_by_id(message_id)
			if message == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Classic opcode 1 references unavailable message %d." % action.operand_id)
			var event := DomainEvent.new(&"message_shown", {"messageId": message_id, "text": message.text, "source": "classic", "classicClick": action.operand_id > 0})
			if action.operand_id > 0:
				var request := InteractionRequest.new(request_id, &"acknowledge", {"prompt": message.text, "messageId": message_id, "presentation": "classic-textbox"})
				return ScenarioRuntimeOperationResult.waiting(request, {"kind": "classic-textbox", "messageId": message_id}, [event])
			return ScenarioRuntimeOperationResult.completed(null, [event])
		4:
			var encounter := _content.simple_encounter_by_id(action.operand_id)
			if encounter == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_encounter", "Classic opcode 4 references unavailable Simple Encounter %d." % action.operand_id)
			var prompt := _content.message_by_id(absi(encounter.prompt_message_id))
			if prompt == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Simple Encounter %d references unavailable prompt message %d." % [encounter.id, encounter.prompt_message_id])
			var options: Array[Dictionary] = []
			var option_indexes: Array[int] = []
			var responses := encounter.responses()
			for option_index: int in responses.size():
				if _game_state.simple_option_is_eliminated(encounter.id, option_index):
					continue
				var response: SimpleEncounterResponse = responses[option_index]
				options.append({"id": response.id, "label": response.label})
				option_indexes.append(option_index)
			if options.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"encounter_has_no_options", "Simple Encounter %d has no remaining responses." % encounter.id)
			var request := InteractionRequest.new(request_id, &"encounter_choice", {"encounterKind": "simple", "encounterId": encounter.id, "prompt": prompt.text, "options": options, "canBackOut": encounter.can_back_out})
			return ScenarioRuntimeOperationResult.waiting(request, {"kind": "classic-simple-encounter", "encounterId": encounter.id, "gosub": action.gosub, "optionIndexes": option_indexes})
		5:
			return _request_complex_encounter(action, request_id)
		3:
			return _request_classic_choice(action, request_id)
		6:
			return _request_shop(action.operand_id, request_id)
		7:
			return _control_flow_operations.replace_scenario_program(action, context)
		8:
			return _control_flow_operations.branch_to_trigger_program(action, context)
		2, 48, 56, 107:
			return _start_classic_battle(action, request_id)
		9:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"sound_requested", {"soundId": absi(action.operand_id), "waitForCompletion": action.operand_id < 0, "source": "classic"})])
		10:
			return _grant_treasure(action.operand_id)
		11:
			var experience := maxi(0, action.operand_id)
			for character: CharacterState in _game_state.party.characters():
				if character.current_health > 0:
					character.experience += experience
			return ScenarioRuntimeOperationResult.completed(experience, [DomainEvent.new(&"experience_granted", {"amount": experience, "target": "living-party", "source": "classic"})])
		12:
			return _mutate_tile(action)
		13:
			return _mutate_triggers(action)
		15, 16:
			return _apply_health(action, action.opcode == 16)
		17, 18:
			return _character_operations.apply_scenario_spell(action, action.opcode == 18)
		19:
			return _show_random_message(action)
		20:
			return _move_between_maps(action, false, true)
		21:
			return _branch_on_item(action)
		22:
			return _mutate_items(action)
		24:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"action_point_kept", {"triggerId": String(context.get("triggerId", "")), "source": "classic"})], {"kind": "finish"})
		25:
			var trigger_id := String(context.get("triggerId", ""))
			if trigger_id.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"missing_trigger_context", "Classic opcode 25 requires an Action Point origin.")
			_game_state.world.disable_trigger(trigger_id)
			return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"trigger_disabled", {"triggerId": trigger_id, "source": "classic"})])
		26:
			return ScenarioRuntimeOperationResult.waiting(InteractionRequest.new(request_id, &"acknowledge", {"prompt": "Continue", "soundId": 30005}), {"kind": "classic-acknowledge"})
		27:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"picture_requested", {"pictureId": absi(action.operand_id), "source": "classic"})])
		28:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"map_redraw_requested", {"source": "classic"})])
		29:
			var map := _content.world.map_by_type_and_index(&"land", absi(action.operand_id))
			if map == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_map", "Classic opcode 29 references unavailable land map %d." % action.operand_id)
			_game_state.world.acquire_map(map.id)
			return ScenarioRuntimeOperationResult.completed(map.id, [DomainEvent.new(&"map_acquired", {"mapId": map.id, "display": action.operand_id < 0})])
		30:
			return _filter_character_selection(action)
		31:
			return _request_character_ability(action, request_id)
		32:
			return _request_temple(action, request_id)
		33:
			var values := action.extra_code
			var amount := absi(action.operand_id) if values.is_empty() else absi(values[0])
			var kind := WealthState.Kind.GOLD if values.size() < 2 else clampi(values[1], WealthState.Kind.GOLD, WealthState.Kind.JEWELRY) as WealthState.Kind
			var paid := _rules.economy.take(_game_state.party, amount, kind)
			return ScenarioRuntimeOperationResult.completed(paid, [DomainEvent.new(&"wealth_taken", {"amount": amount, "kind": kind, "paid": paid, "source": "classic"})])
		34:
			return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"encounter_loop_finished", {"source": "classic"})], {"kind": "finish"})
		35:
			var encounter_id := int(context.get("encounterId", -1))
			if context.get("encounterKind") != "simple" or not _game_state.eliminate_simple_option(encounter_id, action.operand_id - 1):
				return ScenarioRuntimeOperationResult.failed(&"invalid_encounter_context", "Classic opcode 35 requires a Simple Encounter response context.")
			return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"encounter_option_eliminated", {"encounterId": encounter_id, "optionIndex": action.operand_id - 1})])
		36:
			return _inventory_operations.toggle_equipment_storage(action.operand_id != 0)
		37:
			return _move_between_maps(action, true)
		38:
			return _branch_on_item_result(action)
		40:
			return _branch_on_party_condition(action)

class_name ScenarioDefinition
extends RefCounted

var _programs: Dictionary = {}
var _actions: Dictionary = {}


func _init(programs: Array[ScenarioProgramDefinition], actions: Array[ScenarioActionDefinition]) -> void:
	for program: ScenarioProgramDefinition in programs:
		_programs[program.id] = program
	for action: ScenarioActionDefinition in actions:
		_actions[action.id] = action


func program_by_id(program_id: String) -> ScenarioProgramDefinition:
	return _programs.get(program_id) as ScenarioProgramDefinition


func action_by_id(action_id: String) -> ScenarioActionDefinition:
	return _actions.get(action_id) as ScenarioActionDefinition


func program_ids() -> Array[String]:
	var ids: Array[String] = []
	for program_id: Variant in _programs.keys():
		ids.append(String(program_id))
	ids.sort()
	return ids


func action_ids() -> Array[String]:
	var ids: Array[String] = []
	for action_id: Variant in _actions.keys():
		ids.append(String(action_id))
	ids.sort()
	return ids

class_name ClassicCharacterOperations
extends RefCounted

var _content: RealmzContent
var _game_state: GameState
var _rng: RealmzRng
var _rules: RealmzRules


func _init(content: RealmzContent, game_state: GameState, rng: RealmzRng, rules: RealmzRules) -> void:
	_content = content
	_game_state = game_state
	_rng = rng
	_rules = rules


func apply_scenario_spell(action: ClassicActionDefinition, entire_party: bool) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 4:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode %d requires a four-value Extra Code row." % action.opcode)
	var spell := _content.spell_by_classic_id(int(action.extra_code[0]))
	if spell == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_spell", "Classic opcode %d references unavailable packed spell %d." % [action.opcode, int(action.extra_code[0])])
	var targets := _game_state.party.characters() if entire_party else _game_state.selected_characters()
	if targets.is_empty():
		return ScenarioRuntimeOperationResult.failed(&"no_selected_characters", "Classic opcode %d has no selected character targets." % action.opcode)
	var events: Array[DomainEvent] = []
	for character: CharacterState in targets:
		var before_health := character.current_health
		var before_conditions := character.conditions.values()
		var caste := _content.caste_by_id(character.caste_id)
		var resolution := _rules.magic.resolve_scenario_spell(character, spell, int(action.extra_code[1]), int(action.extra_code[2]), int(action.extra_code[3]) != 0, _rng, caste)
		if resolution == null:
			return ScenarioRuntimeOperationResult.failed(&"invalid_spell_effect", "Classic scenario spell inputs are invalid.")
		events.append(DomainEvent.new(&"scenario_spell_applied", {
			"spellId": spell.id,
			"classicSpellId": spell.classic_id,
			"characterId": character.id,
			"powerLevel": int(action.extra_code[1]),
			"saved": resolution.saved,
			"damage": resolution.damage,
			"duration": resolution.duration,
			"healthBefore": before_health,
			"healthAfter": character.current_health,
			"conditionsChanged": before_conditions != character.conditions.values(),
			"source": "classic",
		}))
	return ScenarioRuntimeOperationResult.completed(targets.size(), events)

class_name ClassicCombatOperations
extends RefCounted

var _content: RealmzContent
var _game_state: GameState
var _rules: RealmzRules


func _init(content: RealmzContent, game_state: GameState, rules: RealmzRules) -> void:
	_content = content
	_game_state = game_state
	_rules = rules


func cause_fumble(action: ClassicActionDefinition, context: Dictionary) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 2:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 122 requires message and sound fields.")
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.completed(false, [DomainEvent.new(&"combat_fumble_skipped", {"reason": "no-active-battle", "source": "classic"})])
	var actor_id := str(context.get("combatantId", _game_state.combat.active_actor_id()))
	var character := _game_state.party.character_by_id(actor_id)
	var fumbled_definition_id := ""
	if character != null:
		for instance: ItemInstance in character.inventory():
			if not instance.equipped:
				continue
			var definition := _content.item_by_id(instance.definition_id)
			var removed := _rules.inventory.remove_item(character, instance.id, definition)
			if removed != null:
				removed.equipped = false
				_game_state.party.add_storage_item(removed)
				fumbled_definition_id = removed.definition_id
			break
	else:
		var monster := _game_state.combat.monster_by_id(actor_id)
		if monster != null and not monster.weapon_id.is_empty():
			fumbled_definition_id = monster.weapon_id
			monster.weapon_id = ""
	var changed := not fumbled_definition_id.is_empty()
	var events: Array[DomainEvent] = []
	if int(action.extra_code[1]) != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": int(action.extra_code[1]), "source": "classic"}))
	if int(action.extra_code[0]) != 0:
		var message := _content.message_by_id(absi(int(action.extra_code[0])))
		if message != null:
			events.append(DomainEvent.new(&"message_shown", {"messageId": message.id, "text": message.text, "source": "classic"}))
	events.append(DomainEvent.new(&"combatant_fumbled", {"combatantId": actor_id, "itemId": fumbled_definition_id, "changed": changed, "source": "classic"}))
	return ScenarioRuntimeOperationResult.completed(changed, events)

class_name ClassicControlFlowOperations
extends RefCounted

var _content: RealmzContent
var _game_state: GameState


func _init(content: RealmzContent, game_state: GameState) -> void:
	_content = content
	_game_state = game_state


func resolve_program_id(program_id: String) -> String:
	return _game_state.scenario_program_id(program_id)


func replace_scenario_program(action: ClassicActionDefinition, context: Dictionary) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 7 requires a five-value Extra Code row.")
	var values := action.extra_code
	var source_program_id := "xap:%d" % int(values[2])
	var target_program_id := ""
	match int(values[0]):
		-1:
			target_program_id = "simple:%d:result:%d" % [int(values[1]), int(values[4])]
		-2:
			target_program_id = "complex:%d:result:%d" % [int(values[1]), int(values[4])]
		_:
			var current_trigger := _content.trigger_by_id(str(context.get("triggerId", "")))
			var current_map: MapDefinition = null
			if current_trigger != null and not current_trigger.map_id.is_empty():
				current_map = _content.world.map_by_id(current_trigger.map_id)
			if current_map == null:
				current_map = _content.world.map_by_id(_game_state.party.map_id)
			if current_map == null:
				return ScenarioRuntimeOperationResult.failed(&"missing_trigger_context", "Classic opcode 7 cannot resolve the current map.")
			var level_type := current_map.level_type
			if int(values[3]) != 0:
				if int(values[3]) not in [1, 2]:
					return ScenarioRuntimeOperationResult.failed(&"invalid_map_type", "Classic opcode 7 map type must be 1 for land or 2 for dungeon.")
				level_type = &"land" if int(values[3]) == 1 else &"dungeon"
			var target_map := _content.world.map_by_type_and_index(level_type, int(values[0]))
			if target_map == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_map", "Classic opcode 7 references unavailable %s map %d." % [String(level_type), int(values[0])])
			var target_trigger := _content.trigger_by_map_record(target_map.id, int(values[1]))
			if target_trigger == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_trigger", "Classic opcode 7 references unavailable Action Point record %d on map '%s'." % [int(values[1]), target_map.id])
			target_program_id = target_trigger.program_id
	if _content.scenario.program_by_id(source_program_id) == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_scenario_program", "Classic opcode 7 references unavailable source XAP %d." % int(values[2]))
	if _content.scenario.program_by_id(target_program_id) == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_scenario_program", "Classic opcode 7 references unavailable target program '%s'." % target_program_id)
	_game_state.set_scenario_program_override(target_program_id, source_program_id)
	return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"scenario_program_replaced", {"sourceProgramId": target_program_id, "targetProgramId": source_program_id, "source": "classic"})])


func branch_to_trigger_program(action: ClassicActionDefinition, context: Dictionary) -> ScenarioRuntimeOperationResult:
	var current_trigger := _content.trigger_by_id(str(context.get("triggerId", "")))
	if current_trigger == null:
		return ScenarioRuntimeOperationResult.failed(&"missing_trigger_context", "Classic opcode 8 requires an Action Point origin.")
	var target_trigger := _content.trigger_by_map_record(current_trigger.map_id, action.operand_id)
	if target_trigger == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_trigger", "Classic opcode 8 references unavailable Action Point record %d on map '%s'." % [action.operand_id, current_trigger.map_id])
	return ScenarioRuntimeOperationResult.completed(target_trigger.program_id, [DomainEvent.new(&"scenario_program_redirected", {"triggerId": current_trigger.id, "targetTriggerId": target_trigger.id, "source": "classic"})], {"kind": "branch-program", "programId": target_trigger.program_id, "gosub": false, "context": context.duplicate(true)})

