const FIXTURE_PATH: String = "res://tests/fixtures/packages/realmz2-synthetic-fixture.realmz2"


func run() -> void:
	var loaded := PackageRepository.new().load_package(FIXTURE_PATH)
	assert_true(loaded.is_ok(), "topology fixture loads: %s" % loaded.error_message)
	if not loaded.is_ok():
		return
	var world_state := WorldState.new()
	var land := loaded.content.world.map_by_id("land:0")
	var hidden_cell := land.topology.cell_at(Vector2i(0, 1))
	var hidden_feature := hidden_cell.feature_by_kind(&"secret")
	assert_not_null(hidden_feature, "land secret is an explicit feature")
	assert_equal(land.topology.probe_entry(hidden_cell.coordinate, Vector2i.LEFT, world_state).reason, &"secret_hidden", "hidden land secret blocks movement through topology")
	world_state.discover_secret(hidden_feature.id)
	assert_true(land.topology.probe_entry(hidden_cell.coordinate, Vector2i.LEFT, world_state).allowed, "discovery overlay changes the same topology query")
	assert_true(land.topology.probe_land_entry(Vector2i.ZERO, world_state).allowed, "land entry checks the destination tile without inventing a diagonal edge")
	assert_equal(land.topology.probe_entry(Vector2i.ZERO, Vector2i(-1, -1), world_state).reason, &"invalid_direction", "edge-based topology entry remains cardinal for dungeons and pathfinding")
	assert_equal(land.topology.visible_cells(Vector2i(1, 1), 8, world_state, false).size(), 9, "non-LOS land view derives every visible cell from topology")

	var dungeon := loaded.content.world.map_by_id("dungeon:0")
	assert_equal(dungeon.topology.probe_entry(Vector2i.ZERO, Vector2i.LEFT, world_state).reason, &"terrain_blocked", "dungeon wall blocks movement")
	var door_probe := dungeon.topology.probe_entry(Vector2i(1, 0), Vector2i.LEFT, world_state)
	assert_true(door_probe.allowed, "dungeon door permits the Classic movement attempt")
	assert_equal(door_probe.door_id, "dungeon:0:cell:1,0:door", "movement and rendering share the explicit door identity")
	assert_equal(dungeon.topology.find_path(Vector2i(2, 0), Vector2i(1, 0), world_state), [Vector2i(1, 0)], "pathfinding traverses the same explicit door edge")
	assert_true(dungeon.topology.find_path(Vector2i(2, 0), Vector2i.ZERO, world_state).is_empty(), "pathfinding cannot route into blocked wall terrain")
	var secret_probe := dungeon.topology.probe_entry(Vector2i(0, 1), Vector2i.RIGHT, world_state)
	assert_true(secret_probe.allowed, "matching directional secret passage permits entry")
	assert_equal(secret_probe.secret_id, "dungeon:0:cell:0,1:secret:east", "secret passage returns its stable overlay identity")
	assert_false(dungeon.topology.probe_entry(Vector2i(0, 1), Vector2i.UP, world_state).allowed, "nonmatching secret direction remains blocked")

	world_state.open_door(door_probe.door_id)
	world_state.mark_visited("dungeon:0", Vector2i(1, 0))
	var restored := WorldState.from_data(world_state.to_data())
	assert_not_null(restored, "world overlays serialize as typed state")
	assert_true(restored.door_is_open(door_probe.door_id), "door overlay survives serialization")
	assert_true(restored.secret_is_discovered(hidden_feature.id), "secret discovery survives serialization")
	assert_true(restored.was_visited("dungeon:0", Vector2i(1, 0)), "minimap visitation survives serialization")

param(
    [Parameter(Mandatory = $true)]
    [string]$ManifestPath,
    [string]$GodotPath = ""
)

$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot
if (-not (Test-Path -LiteralPath $ManifestPath)) {
    throw "Corpus manifest does not exist: $ManifestPath"
}
if ([string]::IsNullOrWhiteSpace($GodotPath)) {
    $godotCommand = Get-Command Godot_v4.7.1-stable_win64_console.exe -ErrorAction SilentlyContinue
    if ($null -eq $godotCommand) {
        $godotCommand = Get-Command godot -ErrorAction Stop
    }
    $GodotPath = $godotCommand.Source
}

$manifest = Get-Content -Raw -LiteralPath $ManifestPath | ConvertFrom-Json
if ($manifest.schemaVersion -ne 1 -or $null -eq $manifest.campaigns -or $manifest.campaigns.Count -eq 0) {
    throw "Corpus manifest must use schemaVersion 1 and declare at least one campaign."
}

$failures = @()
foreach ($campaign in $manifest.campaigns) {
    foreach ($field in @("id", "package", "route", "report")) {
        if ([string]::IsNullOrWhiteSpace($campaign.$field)) {
            throw "Corpus entry is missing $field."
        }
    }
    foreach ($inputPath in @($campaign.package, $campaign.route)) {
        if (-not (Test-Path -LiteralPath $inputPath)) {
            throw "Corpus input does not exist: $inputPath"
        }
    }
    $reportDirectory = Split-Path -Parent $campaign.report
    if (-not [string]::IsNullOrWhiteSpace($reportDirectory)) {
        New-Item -ItemType Directory -Force -Path $reportDirectory | Out-Null
    }
    Write-Host "CERTIFY $($campaign.id)"
    & $GodotPath --headless --path $repoRoot --script res://tools/route_acceptance.gd -- $campaign.package $campaign.route $campaign.report
    if ($LASTEXITCODE -ne 0) {
        $failures += $campaign.id
    }
}

if ($failures.Count -gt 0) {
    throw "Campaign route certification failed: $($failures -join ', ')"
}
Write-Host "Corpus route certification passed for $($manifest.campaigns.Count) campaign(s)."

param(
    [Parameter(Mandatory = $true)]
    [string]$SourcePackage,
    [Parameter(Mandatory = $true)]
    [string]$DestinationPackage
)

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.IO.Compression

$sourcePath = (Resolve-Path -LiteralPath $SourcePackage).Path
$destinationPath = [System.IO.Path]::GetFullPath($DestinationPackage)
$destinationDirectory = [System.IO.Path]::GetDirectoryName($destinationPath)
[System.IO.Directory]::CreateDirectory($destinationDirectory) | Out-Null
if ([System.IO.File]::Exists($destinationPath)) {
    [System.IO.File]::Delete($destinationPath)
}

$sourceStream = [System.IO.File]::OpenRead($sourcePath)
$destinationStream = [System.IO.File]::Open($destinationPath, [System.IO.FileMode]::CreateNew)
try {
    $sourceArchive = [System.IO.Compression.ZipArchive]::new($sourceStream, [System.IO.Compression.ZipArchiveMode]::Read, $false)
    $destinationArchive = [System.IO.Compression.ZipArchive]::new($destinationStream, [System.IO.Compression.ZipArchiveMode]::Create, $true)
    try {
        foreach ($sourceEntry in ($sourceArchive.Entries | Sort-Object FullName)) {
            $input = $sourceEntry.Open()
            $buffer = [System.IO.MemoryStream]::new()
            try {
                $input.CopyTo($buffer)
                [byte[]]$bytes = $buffer.ToArray()
            }
            finally {
                $buffer.Dispose()
                $input.Dispose()
            }
            if ($sourceEntry.FullName -eq "content.json") {
                $utf8 = [System.Text.UTF8Encoding]::new($false)
                $text = $utf8.GetString($bytes)
                if (-not $text.Contains("Fixture Wand")) {
                    throw "The positive fixture does not contain the expected synthetic mutation target."
                }
                $bytes = $utf8.GetBytes($text.Replace("Fixture Wand", "Fixture Band"))
            }
            $destinationEntry = $destinationArchive.CreateEntry($sourceEntry.FullName, [System.IO.Compression.CompressionLevel]::Optimal)
            $destinationEntry.LastWriteTime = $sourceEntry.LastWriteTime
            $output = $destinationEntry.Open()
            try {
                $output.Write($bytes, 0, $bytes.Length)
            }
            finally {
                $output.Dispose()
            }
        }
    }
    finally {
        $destinationArchive.Dispose()
        $sourceArchive.Dispose()
    }
}
finally {
    $destinationStream.Dispose()
    $sourceStream.Dispose()
}

Write-Host "Created valid-ZIP stale-hash fixture at $destinationPath"

extends SceneTree


func _initialize() -> void:
	var arguments := OS.get_cmdline_user_args()
	if arguments.size() != 1:
		printerr("Usage: godot --headless --path <project> --script res://tools/package_probe.gd -- <package.realmz2>")
		call_deferred("_quit_cleanly", 2)
		return
	var package_path: String = arguments[0]
	var repository := PackageRepository.new()
	var archive := ZIPReader.new()
	var started_at := Time.get_ticks_msec()
	var open_error := archive.open(package_path)
	if open_error != OK:
		printerr("PACKAGE_REJECTED package_open_failed: ZIP error %d" % open_error)
		call_deferred("_quit_cleanly", 1)
		return
	var archive_entries: Array[String] = repository._zip_entries(archive)
	var manifest: Variant = repository._read_document(archive, "manifest.json")
	if manifest == null or not repository._validate_manifest(manifest, archive, archive_entries):
		printerr("PACKAGE_REJECTED manifest: %s" % repository._last_error)
		call_deferred("_quit_cleanly", 1)
		return
	print("PROBE manifest_ms=%d" % (Time.get_ticks_msec() - started_at))
	var documents_started := Time.get_ticks_msec()
	var content_document: Variant = repository._read_document(archive, "content.json")
	var world_document: Variant = repository._read_document(archive, "world.json")
	var scenario_document: Variant = repository._read_document(archive, "scenario.json")
	var asset_document: Variant = repository._read_document(archive, "assets/index.json")
	print("PROBE documents_ms=%d" % (Time.get_ticks_msec() - documents_started))
	if content_document == null or world_document == null or scenario_document == null or asset_document == null:
		printerr("PACKAGE_REJECTED documents: %s" % repository._last_error)
		call_deferred("_quit_cleanly", 1)
		return
	var construction_started := Time.get_ticks_msec()
	var content := repository._construct_content(manifest, content_document, world_document, scenario_document)
	print("PROBE construction_ms=%d" % (Time.get_ticks_msec() - construction_started))
	if content == null:
		printerr("PACKAGE_REJECTED construction: %s" % repository._last_error)
		call_deferred("_quit_cleanly", 1)
		return
	var media := PackageMediaCatalog.new(package_path, manifest["packageHash"], repository._construct_assets(asset_document))
	archive.close()
	var session := GameSession.new()
	var session_started_at := Time.get_ticks_msec()
	var step := session.start(content, 1)
	var session_start_ms := Time.get_ticks_msec() - session_started_at
	if step.state == SessionStep.State.FAILED:
		printerr("SESSION_REJECTED %s: %s" % [step.error_code, step.error_message])
		call_deferred("_quit_cleanly", 1)
		return
	var view_started_at := Time.get_ticks_msec()
	var view := session.view()
	var first_view_ms := Time.get_ticks_msec() - view_started_at
	var repeat_views_started_at := Time.get_ticks_msec()
	for index: int in 10:
		session.view()
	var ten_repeat_views_ms := Time.get_ticks_msec() - repeat_views_started_at
	var blocked_move_started_at := Time.get_ticks_msec()
	var blocked_move := session.submit_intent(PlayerIntent.move(Vector2i.LEFT))
	var blocked_move_ms := Time.get_ticks_msec() - blocked_move_started_at
	var post_move_view_started_at := Time.get_ticks_msec()
	session.view()
	var post_move_view_ms := Time.get_ticks_msec() - post_move_view_started_at
	print(CanonicalJson.encode({
		"blockedMoveError": String(blocked_move.error_code),
		"blockedMoveMs": blocked_move_ms,
		"campaignId": content.campaign_id,
		"firstViewMs": first_view_ms,
		"packageHash": content.package_hash,
		"rulesVersion": content.rules_version,
		"startMapId": view.party_map_id,
		"startX": view.party_coordinate.x,
		"startY": view.party_coordinate.y,
		"partySetupAvailable": view.party_setup_available,
		"pendingInteraction": step.interaction != null,
		"mediaAssets": media.assets().size(),
		"postMoveViewMs": post_move_view_ms,
		"sessionStartMs": session_start_ms,
		"tenRepeatViewsMs": ten_repeat_views_ms,
		"totalMs": Time.get_ticks_msec() - started_at,
	}))
	call_deferred("_quit_cleanly", 0)


func _quit_cleanly(exit_code: int) -> void:
	quit(exit_code)

