    if($file.content.Length -gt 0){$lines=$file.content -split "\r\n|\n|\r";$part=0;for($start=0;$start -lt $lines.Count;$start+=160){$end=[Math]::Min($lines.Count-1,$start+159);$chunks.Add([ordered]@{id="chunk:$($file.id):$part";entity_id=$file.id;kind="file";title="$($file.path) part $part";path=$file.path;start_line=$start+1;end_line=$end+1;module_id=$file.module_id;dox_scope_id=$file.dox_scope_id;text=(($lines[$start..$end])-join [Environment]::NewLine);source_sha256=$file.sha256;commit=$commit});$part++}}
}

$intelligenceFlows=[System.Collections.Generic.List[object]]::new()
foreach($flow in $catalog.flows){
    $triggerSpan=Get-SourceSpanForCatalogTrigger $flow.trigger $fileByPath $commit;$steps=[System.Collections.Generic.List[object]]::new()
    foreach($step in $flow.steps){$id="module:$step";$stepEvidence=@();if($entityById.ContainsKey($id)){$stepEvidence=@($entityById[$id].evidence)};$steps.Add([ordered]@{entity_id=$id;label=$step;evidence=$stepEvidence})}
    $intelligenceFlows.Add([ordered]@{id=$flow.id;label=$flow.label;primary=[bool]$flow.primary;trigger=[ordered]@{label=$flow.trigger.label;path=$flow.trigger.path;symbol=$flow.trigger.symbol;evidence=@($triggerSpan)};steps=@($steps);outcome=$flow.outcome;tests=@($flow.tests)})
}

$overviewPair=[ordered]@{};$overviewTypeMap=@{imports="imports";constructs="calls";calls="calls";reads="reads";writes="writes";publishes="publishes";subscribes="subscribes";tests="calls"}
foreach($relation in ($relations|Where-Object{$overviewTypeMap.ContainsKey($_.type) -and $_.status -eq "resolved"})){
    $fromEntity=$entityById[$relation.from];$toEntity=$entityById[$relation.to];if(-not $fromEntity -or -not $toEntity){continue};$from=$fromEntity.module_id;$to=$toEntity.module_id;if(-not $from -or -not $to -or $from -eq $to){continue}
    $fromOverview=$from.Substring("module:".Length);$toOverview=$to.Substring("module:".Length);$fromKnown=@($catalog.overview_nodes|Where-Object{$_.id -eq $fromOverview}).Count -gt 0;$toKnown=@($catalog.overview_nodes|Where-Object{$_.id -eq $toOverview}).Count -gt 0;if(-not $fromKnown -or -not $toKnown){continue}
    $type=$overviewTypeMap[$relation.type];$key="$fromOverview|$toOverview|$type";if(-not $overviewPair.Contains($key)){$overviewPair[$key]=[ordered]@{from=$fromOverview;to=$toOverview;type=$type;evidence=[System.Collections.Generic.List[object]]::new()}};if($overviewPair[$key].evidence.Count -lt 4){$overviewPair[$key].evidence.Add($relation.evidence[0])}
}
$overviewEdges=[System.Collections.Generic.List[object]]::new();foreach($pair in $overviewPair.Values|Sort-Object from,to,type){$overviewEdges.Add([ordered]@{from=$pair.from;to=$pair.to;type=$pair.type;evidence=@($pair.evidence|ForEach-Object{[ordered]@{path=$_.path;symbol=$_.symbol}})})}

$moduleTestMap=@{}
foreach($relation in $relations|Where-Object{$_.type -eq "tests" -and $_.status -eq "resolved"}){
    $testEntity=$entityById[$relation.from];$target=$entityById[$relation.to];if(-not $testEntity -or -not $target){continue};if(-not $moduleTestMap.ContainsKey($target.module_id)){$moduleTestMap[$target.module_id]=[System.Collections.Generic.List[string]]::new()};if($testEntity.path -and -not $moduleTestMap[$target.module_id].Contains($testEntity.path)){$moduleTestMap[$target.module_id].Add($testEntity.path)}
}
$overviewNodes=[System.Collections.Generic.List[object]]::new()
foreach($node in $catalog.overview_nodes){
    $moduleId="module:$($node.id)";$evidence=@();$symbols=@($entities|Where-Object{$_.module_id -eq $moduleId -and $_.kind -in @("class","function","signal","property","enum")}|Select-Object -First 6);foreach($symbol in $symbols){$evidence+=[ordered]@{path=$symbol.path;symbol=[string]$symbol.evidence[0].symbol}};if($evidence.Count -eq 0){$evidence=@([ordered]@{path="tools/source-intelligence/catalog.json";symbol=[string]$node.id})};$tests=@();if($moduleTestMap.ContainsKey($moduleId)){$tests=@($moduleTestMap[$moduleId])}
    $overviewNodes.Add([ordered]@{id=$node.id;path=$node.path;kind=$node.kind;boundary=$node.boundary;role=$node.role;entrypoints=@($node.entrypoints);tests=$tests;constraints=@($node.constraints);evidence=$evidence})
}
$overviewFlows=[System.Collections.Generic.List[object]]::new();foreach($flow in $catalog.flows){$overviewFlows.Add([ordered]@{id=$flow.id;label=$flow.label;trigger=[ordered]@{label=$flow.trigger.label;path=$flow.trigger.path;symbol=$flow.trigger.symbol};steps=@($flow.steps);outcome=$flow.outcome;primary=[bool]$flow.primary})}

foreach($relation in $relations){
    $evidenceKey=@($relation.evidence|ForEach-Object{"$($_.path):$($_.start_line):$($_.start_column):$($_.end_line):$($_.end_column):$($_.symbol)"}) -join ";"
    $relationKey="$($relation.from)|$($relation.to)|$($relation.type)|$($relation.status)|$($relation.resolver)|$evidenceKey"
    $relation.id="relation:"+(Get-Sha256Bytes ([Text.Encoding]::UTF8.GetBytes($relationKey))).Substring(0,24)
}

$moduleFingerprint=Get-ModuleFingerprints $inputPaths
$model=[ordered]@{schema_version=1;generator_version=$generatorVersion;repository=[ordered]@{name="Realmz Remake 2.0";commit=$commit;working_tree_dirty=$dirtyBefore;generated_at=$effectiveGeneratedAt};scope=$scopeRoots+$rootFiles;exclusions=$excludedDirectoryText+$generatedNames;files=@($fileRecords|Sort-Object path);entities=@($entities|Sort-Object id);relations=@($relations|Sort-Object from,type,to,id);flows=@($intelligenceFlows|Sort-Object id);diagnostics=@($diagnostics);search_documents=@($searchDocuments|Sort-Object id)}
Test-Model $model $fileByPath $commit

$overview=[ordered]@{generated_at=$effectiveGeneratedAt;generated_from_commit=$commit;scope=$scopeRoots+$rootFiles;nodes=@($overviewNodes);edges=@($overviewEdges);flows=@($overviewFlows)}

$chunkText=(@($chunks|Sort-Object id|ForEach-Object{Get-CanonicalJson $_}) -join [Environment]::NewLine)+[Environment]::NewLine
$intelligenceText=Get-CanonicalJson $model;$overviewText=Get-CanonicalJson $overview;$template=Get-Content -Raw $templatePath;$overviewHtmlText=$overviewText.Replace("</script","<\/script");$intelligenceHtmlText=$intelligenceText.Replace("</script","<\/script");$htmlText=$template.Replace("@@OVERVIEW_JSON@@",$overviewHtmlText).Replace("@@INTELLIGENCE_JSON@@",$intelligenceHtmlText)

$stage=Join-Path $outputRoot (".stage-" + [Guid]::NewGuid().ToString("N"));New-Item -ItemType Directory -Path $stage -Force|Out-Null
try{
    [IO.File]::WriteAllText((Join-Path $stage "codemap.json"),$overviewText,[Text.UTF8Encoding]::new($false))
    [IO.File]::WriteAllText((Join-Path $stage "intelligence.json"),$intelligenceText,[Text.UTF8Encoding]::new($false))
    [IO.File]::WriteAllText((Join-Path $stage "chunks.jsonl"),$chunkText,[Text.UTF8Encoding]::new($false))
    [IO.File]::WriteAllText((Join-Path $stage "codemap.html"),$htmlText,[Text.UTF8Encoding]::new($false))
    $outputHashes=[ordered]@{};foreach($name in @("codemap.html","codemap.json","intelligence.json","chunks.jsonl")){$outputHashes[$name]=Get-Sha256Bytes([IO.File]::ReadAllBytes((Join-Path $stage $name)))}
    $lock=[ordered]@{schema_version=1;generator_version=$generatorVersion;current_commit=$commit;working_tree_has_uncommitted_changes=$dirtyBefore;generated_at=$effectiveGeneratedAt;input_fingerprint=$inputFingerprint;scanned_scope=$scopeRoots+$rootFiles;excluded_directories=$excludedDirectoryText+$generatedNames;fingerprint_algorithm="sha256(UTF-8 path bytes, NUL, exact current file bytes, LF; lexical path order; module roots independently hashed)";module_fingerprints=$moduleFingerprint;output_hashes=$outputHashes;generated_files=$generatedNames}
    [IO.File]::WriteAllText((Join-Path $stage "codemap.lock"),(Get-CanonicalJson $lock),[Text.UTF8Encoding]::new($false))
    Test-WrittenArtifacts $stage
    foreach($name in $generatedNames){$source=Join-Path $stage $name;$destination=Join-Path $outputRoot $name;Move-Item -LiteralPath $source -Destination $destination -Force}
    Write-Host ("Source intelligence generated: {0} files, {1} entities, {2} relations, {3} flows, {4} chunks." -f $fileRecords.Count,$entities.Count,$relations.Count,$intelligenceFlows.Count,$chunks.Count)
}finally{if(Test-Path -LiteralPath $stage){Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue}}

param(
    [string]$SourcePng = "",
    [string]$SpriteCookAssetId = "",
    [string]$SpriteCookLabel = "",
    [switch]$RebuildFromCommittedSurface
)

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Drawing
$toolRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent (Split-Path -Parent $toolRoot)
$outputRoot = Join-Path $repoRoot "src/presentation/assets/ui"
$committedSurfacePath = Join-Path $outputRoot "classic-charcoal-slate.png"
$committedManifestPath = Join-Path $outputRoot "spritecook-assets.json"
$stagingRoot = Join-Path ([IO.Path]::GetTempPath()) ("realmz2-ui-surfaces-" + [Guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $stagingRoot | Out-Null

function Save-Png([Drawing.Bitmap]$bitmap, [string]$path) {
    $bitmap.Save($path, [Drawing.Imaging.ImageFormat]::Png)
    $bytes = [IO.File]::ReadAllBytes($path)
    if ($bytes.Length -lt 24 -or [Text.Encoding]::ASCII.GetString($bytes, 1, 3) -ne "PNG") {
        throw "Generated surface is not a valid PNG: $path"
    }
}

function New-SeamlessTile([Drawing.Bitmap]$source, [int]$blendWidth = 64) {
    if ($source.Width -lt $blendWidth * 2 -or $source.Height -lt $blendWidth * 2) {
        throw "The selected surface is too small for a $blendWidth-pixel edge feather."
    }
    $horizontal = [Drawing.Bitmap]$source.Clone()
    for ($y = 0; $y -lt $source.Height; $y++) {
        for ($offset = 0; $offset -lt $blendWidth; $offset++) {
            $opposite = $source.Width - 1 - $offset
            $weight = 0.25 * (1.0 + [Math]::Cos([Math]::PI * $offset / $blendWidth))
            $left = $source.GetPixel($offset, $y)
            $right = $source.GetPixel($opposite, $y)
            $horizontal.SetPixel($offset, $y, [Drawing.Color]::FromArgb(
                [int][Math]::Round($left.A * (1.0 - $weight) + $right.A * $weight),
                [int][Math]::Round($left.R * (1.0 - $weight) + $right.R * $weight),
                [int][Math]::Round($left.G * (1.0 - $weight) + $right.G * $weight),
                [int][Math]::Round($left.B * (1.0 - $weight) + $right.B * $weight)
            ))
            $horizontal.SetPixel($opposite, $y, [Drawing.Color]::FromArgb(
                [int][Math]::Round($right.A * (1.0 - $weight) + $left.A * $weight),
                [int][Math]::Round($right.R * (1.0 - $weight) + $left.R * $weight),
                [int][Math]::Round($right.G * (1.0 - $weight) + $left.G * $weight),
                [int][Math]::Round($right.B * (1.0 - $weight) + $left.B * $weight)
            ))
        }
    }
    $result = [Drawing.Bitmap]$horizontal.Clone()
    try {
        for ($x = 0; $x -lt $horizontal.Width; $x++) {
            for ($offset = 0; $offset -lt $blendWidth; $offset++) {
                $opposite = $horizontal.Height - 1 - $offset
                $weight = 0.25 * (1.0 + [Math]::Cos([Math]::PI * $offset / $blendWidth))
                $top = $horizontal.GetPixel($x, $offset)
                $bottom = $horizontal.GetPixel($x, $opposite)
                $result.SetPixel($x, $offset, [Drawing.Color]::FromArgb(
                    [int][Math]::Round($top.A * (1.0 - $weight) + $bottom.A * $weight),
                    [int][Math]::Round($top.R * (1.0 - $weight) + $bottom.R * $weight),
                    [int][Math]::Round($top.G * (1.0 - $weight) + $bottom.G * $weight),
                    [int][Math]::Round($top.B * (1.0 - $weight) + $bottom.B * $weight)
                ))
                $result.SetPixel($x, $opposite, [Drawing.Color]::FromArgb(
                    [int][Math]::Round($bottom.A * (1.0 - $weight) + $top.A * $weight),
                    [int][Math]::Round($bottom.R * (1.0 - $weight) + $top.R * $weight),
                    [int][Math]::Round($bottom.G * (1.0 - $weight) + $top.G * $weight),
                    [int][Math]::Round($bottom.B * (1.0 - $weight) + $top.B * $weight)
                ))
            }
        }
    }
    finally { $horizontal.Dispose() }
    return $result
}

try {
    $selectedAsset = $null
    $basePath = Join-Path $stagingRoot "classic-charcoal-slate.png"
    if ($RebuildFromCommittedSurface) {
        if (-not [string]::IsNullOrWhiteSpace($SourcePng) -or -not [string]::IsNullOrWhiteSpace($SpriteCookAssetId) -or -not [string]::IsNullOrWhiteSpace($SpriteCookLabel)) {
            throw "RebuildFromCommittedSurface cannot be combined with source-import arguments."
        }
        if (-not (Test-Path -LiteralPath $committedSurfacePath) -or -not (Test-Path -LiteralPath $committedManifestPath)) {
            throw "The committed selected surface and manifest are required for an offline rebuild."
        }
        $existingManifest = Get-Content -Raw -LiteralPath $committedManifestPath | ConvertFrom-Json
        $selectedAsset = [ordered]@{
            asset_id = [string]$existingManifest.selected_asset.asset_id
            label = [string]$existingManifest.selected_asset.label
            source_sha256 = [string]$existingManifest.selected_asset.source_sha256
            source_sha256_prefix = [string]$existingManifest.selected_asset.source_sha256_prefix
            mode = [string]$existingManifest.selected_asset.mode
        }
        Copy-Item -LiteralPath $committedSurfacePath -Destination $basePath
    }
    else {
        if ([string]::IsNullOrWhiteSpace($SourcePng) -or [string]::IsNullOrWhiteSpace($SpriteCookAssetId) -or [string]::IsNullOrWhiteSpace($SpriteCookLabel)) {
            throw "SourcePng, SpriteCookAssetId, and SpriteCookLabel are required when importing a selected SpriteCook surface."
        }
        $sourcePath = (Resolve-Path -LiteralPath $SourcePng).Path
        $source = [Drawing.Bitmap]::new([string]$sourcePath)
        try {
            $base = [Drawing.Bitmap]::new(512, 512, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
            $graphics = [Drawing.Graphics]::FromImage($base)
            try {
                $graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                $graphics.PixelOffsetMode = [Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                $graphics.DrawImage($source, [Drawing.Rectangle]::new(0, 0, 512, 512))
            }
            finally { $graphics.Dispose() }
            Save-Png $base $basePath
            $base.Dispose()
        }
        finally { $source.Dispose() }
        $sourceHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $sourcePath).Hash.ToLowerInvariant()
        $selectedAsset = [ordered]@{
            asset_id = $SpriteCookAssetId
            label = $SpriteCookLabel
            source_sha256 = $sourceHash
            source_sha256_prefix = $sourceHash.Substring(0, 12)
            mode = "texture"
        }
    }

    $baseSurface = [Drawing.Bitmap]::new([string]$basePath)
    try {
        $seamlessTile = New-SeamlessTile $baseSurface
        try {
            Save-Png $seamlessTile (Join-Path $stagingRoot "classic-charcoal-slate-tile.png")
            foreach ($definition in @(
                @{ Name = "classic-raised-frame.png"; Top = [Drawing.Color]::FromArgb(190, 128, 138, 139); Bottom = [Drawing.Color]::FromArgb(220, 8, 11, 13) },
                @{ Name = "classic-inset-frame.png"; Top = [Drawing.Color]::FromArgb(225, 6, 8, 10); Bottom = [Drawing.Color]::FromArgb(180, 112, 121, 122) }
            )) {
                $frame = [Drawing.Bitmap]::new($seamlessTile.Width + 16, $seamlessTile.Height + 16, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
                $frameGraphics = [Drawing.Graphics]::FromImage($frame)
                try {
                    $frameGraphics.DrawImageUnscaled($seamlessTile, 8, 8)
                    $topPen = [Drawing.Pen]::new($definition.Top, 3)
                    $bottomPen = [Drawing.Pen]::new($definition.Bottom, 3)
                    try {
                        $maximum = $frame.Width - 2
                        $frameGraphics.DrawLine($topPen, 1, 1, $maximum, 1)
                        $frameGraphics.DrawLine($topPen, 1, 1, 1, $maximum)
                        $frameGraphics.DrawLine($bottomPen, 2, $maximum, $maximum, $maximum)
                        $frameGraphics.DrawLine($bottomPen, $maximum, 2, $maximum, $maximum)
                        $innerPen = [Drawing.Pen]::new([Drawing.Color]::FromArgb(170, 31, 38, 40), 1)
                        try { $frameGraphics.DrawRectangle($innerPen, 5, 5, $frame.Width - 11, $frame.Height - 11) }
                        finally { $innerPen.Dispose() }
                    }
                    finally {
                        $topPen.Dispose()
                        $bottomPen.Dispose()
                    }
                }
                finally { $frameGraphics.Dispose() }
                Save-Png $frame (Join-Path $stagingRoot $definition.Name)
                $frame.Dispose()
            }

        }
        finally { $seamlessTile.Dispose() }
    }
    finally { $baseSurface.Dispose() }

    $surfaceNames = @(
        "classic-charcoal-slate.png",
        "classic-charcoal-slate-tile.png",
        "classic-raised-frame.png",
        "classic-inset-frame.png"
    )
    $records = @()
    foreach ($name in $surfaceNames) {
        $path = Join-Path $stagingRoot $name
        $bitmap = [Drawing.Bitmap]::new([string]$path)
        try {
            $records += [ordered]@{
                path = "res://src/presentation/assets/ui/$name"
                width = $bitmap.Width
                height = $bitmap.Height
                sha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $path).Hash.ToLowerInvariant()
            }
        }
        finally { $bitmap.Dispose() }
    }
    $manifest = [ordered]@{
        schema_version = 3
        selected_asset = $selectedAsset
        derivation = [ordered]@{
            generator = "tools/ui-assets/build-classic-surfaces.ps1"
            algorithm = "system-drawing-bicubic-512-plus-cosine-feathered-512-tile-and-528px-bevel-v2"
            seamless_strategy = "64px-cosine-opposite-edge-feather"
        }
        files = $records
    }
    $manifestPath = Join-Path $stagingRoot "spritecook-assets.json"
    [IO.File]::WriteAllText($manifestPath, (($manifest | ConvertTo-Json -Depth 6) + [Environment]::NewLine), [Text.UTF8Encoding]::new($false))

    New-Item -ItemType Directory -Path $outputRoot -Force | Out-Null
    foreach ($name in $surfaceNames + @("spritecook-assets.json")) {
        Copy-Item -LiteralPath (Join-Path $stagingRoot $name) -Destination (Join-Path $outputRoot $name) -Force
    }
    Write-Host "Built Classic slate surfaces from SpriteCook asset $($selectedAsset.asset_id)."
}
finally {
    if (Test-Path -LiteralPath $stagingRoot) {
        Remove-Item -LiteralPath $stagingRoot -Recurse -Force
    }
}

param(
    [Parameter(Mandatory = $true)]
    [string]$SourceRepository
)

$ErrorActionPreference = "Stop"
$toolRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent (Split-Path -Parent $toolRoot)
$catalogPath = Join-Path $toolRoot "catalog.json"
$catalog = Get-Content -Raw -LiteralPath $catalogPath | ConvertFrom-Json
$sourceRoot = (Resolve-Path -LiteralPath $SourceRepository).Path
$destinationRoot = Join-Path $repoRoot "src/presentation/assets/classic-controls"
$manifestPath = Join-Path $repoRoot "src/presentation/assets/classic-ui-assets.json"

$resolvedCommit = (& git -C $sourceRoot rev-parse "$($catalog.source_commit)^{commit}").Trim()
if ($LASTEXITCODE -ne 0 -or $resolvedCommit -ne $catalog.source_commit) {
    throw "The requested Remake source commit is unavailable: $($catalog.source_commit)"
}

$stagingRoot = Join-Path ([IO.Path]::GetTempPath()) ("realmz2-ui-assets-" + [Guid]::NewGuid().ToString("N"))
$archivePath = Join-Path $stagingRoot "source.zip"
$extractRoot = Join-Path $stagingRoot "source"
$outputRoot = Join-Path $stagingRoot "output"
New-Item -ItemType Directory -Path $extractRoot, $outputRoot | Out-Null

try {
    & git -C $sourceRoot archive --format=zip --output=$archivePath $catalog.source_commit -- "src/scenes/UI/HUD"
    if ($LASTEXITCODE -ne 0) {
        throw "git archive failed"
    }
    Expand-Archive -LiteralPath $archivePath -DestinationPath $extractRoot

    $records = @()
    foreach ($entry in $catalog.assets) {
        $sourcePath = Join-Path $extractRoot ($entry.source_path -replace "/", [IO.Path]::DirectorySeparatorChar)
        if (-not (Test-Path -LiteralPath $sourcePath -PathType Leaf)) {
            throw "Catalog source is missing from the recorded commit: $($entry.source_path)"
        }
        $bytes = [IO.File]::ReadAllBytes($sourcePath)
        if ($bytes.Length -lt 24 -or [Text.Encoding]::ASCII.GetString($bytes, 1, 3) -ne "PNG") {
            throw "Only validated PNG controls may be imported: $($entry.source_path)"
        }
        $width = [Net.IPAddress]::NetworkToHostOrder([BitConverter]::ToInt32($bytes, 16))
        $height = [Net.IPAddress]::NetworkToHostOrder([BitConverter]::ToInt32($bytes, 20))
        if ($width -le 0 -or $height -le 0) {
            throw "Invalid PNG dimensions: $($entry.source_path)"
        }
        $targetPath = Join-Path $outputRoot ($entry.target_path -replace "/", [IO.Path]::DirectorySeparatorChar)
        New-Item -ItemType Directory -Path (Split-Path -Parent $targetPath) -Force | Out-Null
        [IO.File]::WriteAllBytes($targetPath, $bytes)
        $sha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $targetPath).Hash.ToLowerInvariant()
        $records += [ordered]@{
            id = $entry.id
            path = "res://src/presentation/assets/classic-controls/$($entry.target_path)"
            source_repository = $catalog.source_repository
            source_commit = $catalog.source_commit
            source_path = $entry.source_path
            native_width = $width
            native_height = $height
            sha256 = $sha256
            classification = "tracked-remake-bitmap"
            classic_evidence = [ordered]@{
                status = "remake-scene-use"
                path = $catalog.contexts.($entry.context)
                note = "Semantic use is proven by the tracked Remake scene; direct extraction from a Classic resource fork is not claimed."
            }
            rendering = [ordered]@{
                filter = "nearest"
                allowed_scales = @(1, 2)
                source_pixels_modified = $false
            }
        }
    }

    $manifest = [ordered]@{
        schema_version = 1
        source_repository = $catalog.source_repository
        source_commit = $catalog.source_commit
        generated_by = "tools/ui-assets/sync-classic-ui-assets.ps1"
        assets = $records
    }
    $manifestText = ($manifest | ConvertTo-Json -Depth 8) + [Environment]::NewLine
    $stagedManifest = Join-Path $stagingRoot "classic-ui-assets.json"
    [IO.File]::WriteAllText($stagedManifest, $manifestText, [Text.UTF8Encoding]::new($false))
    $parsed = Get-Content -Raw -LiteralPath $stagedManifest | ConvertFrom-Json
    if ($parsed.assets.Count -ne $catalog.assets.Count) {
        throw "Generated asset manifest failed validation"
    }

    if (Test-Path -LiteralPath $destinationRoot) {
        Remove-Item -LiteralPath $destinationRoot -Recurse -Force
    }
    New-Item -ItemType Directory -Path $destinationRoot | Out-Null
    Copy-Item -Path (Join-Path $outputRoot "*") -Destination $destinationRoot -Recurse -Force
    Copy-Item -LiteralPath $stagedManifest -Destination $manifestPath -Force
    Write-Host "Imported $($records.Count) exact-commit Classic UI assets."
}
finally {
    if (Test-Path -LiteralPath $stagingRoot) {
        Remove-Item -LiteralPath $stagingRoot -Recurse -Force
    }
}

