    @{ Id = "font.ui.alegreya_sans.bold"; Uri = "$baseUri/alegreyasans/AlegreyaSans-Bold.ttf"; Target = "AlegreyaSans-Bold.ttf"; License = "OFL-1.1" },
    @{ Id = "license.alegreya"; Uri = "$baseUri/alegreya/OFL.txt"; Target = "licenses/Alegreya-OFL.txt"; License = "OFL-1.1" },
    @{ Id = "license.alegreya_sans"; Uri = "$baseUri/alegreyasans/OFL.txt"; Target = "licenses/AlegreyaSans-OFL.txt"; License = "OFL-1.1" }
)
New-Item -ItemType Directory -Path $stagingRoot | Out-Null

try {
    $records = @()
    foreach ($definition in $files) {
        $target = Join-Path $stagingRoot ($definition.Target -replace "/", [IO.Path]::DirectorySeparatorChar)
        New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null
        Invoke-WebRequest -UseBasicParsing -Headers @{ "User-Agent" = "Realmz2-asset-sync" } -Uri $definition.Uri -OutFile $target
        if ((Get-Item -LiteralPath $target).Length -eq 0) {
            throw "Downloaded font asset is empty: $($definition.Target)"
        }
        $records += [ordered]@{
            id = $definition.Id
            path = "res://src/presentation/assets/fonts/$($definition.Target)"
            source_repository = "google/fonts"
            source_commit = $googleFontsCommit
            sha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $target).Hash.ToLowerInvariant()
            license = $definition.License
        }
    }
    $manifest = [ordered]@{
        schema_version = 1
        source_repository = "google/fonts"
        source_commit = $googleFontsCommit
        runtime_network_dependency = $false
        assets = $records
    }
    [IO.File]::WriteAllText(
        (Join-Path $stagingRoot "font-assets.json"),
        (($manifest | ConvertTo-Json -Depth 5) + [Environment]::NewLine),
        [Text.UTF8Encoding]::new($false)
    )

    New-Item -ItemType Directory -Path $destinationRoot -Force | Out-Null
    Copy-Item -Path (Join-Path $stagingRoot "*") -Destination $destinationRoot -Recurse -Force
    Write-Host "Bundled Alegreya fonts and OFL licenses from google/fonts $googleFontsCommit."
}
finally {
    if (Test-Path -LiteralPath $stagingRoot) {
        Remove-Item -LiteralPath $stagingRoot -Recurse -Force
    }
}

$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot
$violations = @()

$coreFiles = Get-ChildItem (Join-Path $repoRoot "src\core") -Recurse -Filter "*.gd" -ErrorAction SilentlyContinue
$forbiddenPatterns = @(
    @{ Pattern = '\bextends\s+(Node|Control|Node2D|Node3D)\b'; Reason = "simulation classes must not extend Godot nodes" },
    @{ Pattern = '\b(RandomNumberGenerator|randf|randi|randfn|randomize)\b'; Reason = "simulation randomness must go through RealmzRng" },
    @{ Pattern = '\b(Time|FileAccess|DirAccess|ResourceLoader|AudioServer)\b'; Reason = "simulation must not access host time, files, resources, or audio" },
    @{ Pattern = '\b(get_tree|get_node|Engine\.get_)\b'; Reason = "simulation must not access the scene tree or engine singleton" }
)

foreach ($file in $coreFiles) {
    $content = Get-Content -Raw $file.FullName
    foreach ($rule in $forbiddenPatterns) {
        if ($content -match $rule.Pattern) {
            $violations += "$($file.FullName): $($rule.Reason)"
        }
    }
}

if ($violations.Count -gt 0) {
    $violations | ForEach-Object { Write-Error $_ }
    exit 1
}

Write-Host "Architecture boundaries verified across $($coreFiles.Count) core scripts."

class_name RealmzTestCase
extends RefCounted

var assertions: int = 0
var failures: Array[String] = []


func assert_true(value: bool, message: String) -> void:
	assertions += 1
	if not value:
		failures.append(message)


func assert_equal(actual: Variant, expected: Variant, message: String) -> void:
	assertions += 1
	if actual != expected:
		failures.append("%s (expected %s, got %s)" % [message, str(expected), str(actual)])


func assert_false(value: bool, message: String) -> void:
	assert_true(not value, message)


func assert_not_null(value: Variant, message: String) -> void:
	assertions += 1
	if value == null:
		failures.append(message)


func assert_contains(text: String, expected_fragment: String, message: String) -> void:
	assertions += 1
	if not text.contains(expected_fragment):
		failures.append("%s (expected '%s' in '%s')" % [message, expected_fragment, text])

		assert_true(operation != null and operation.error_code != &"unsupported_classic_opcode", "AOGM opcode %d dispatches to its declared runtime owner" % opcode)


func _runtime_api(content: RealmzContent, action_state: ScenarioActionState) -> RealmzRuntimeApi:
	var party := PartyState.new(content.start_map_id, content.start_coordinate, [CharacterState.new("test", "Test", 1, 1)])
	return RealmzRuntimeApi.new(content, GameState.new(party, RealmzClock.new()), RealmzRng.new(1), action_state)


func _action(id: String, return_type: StringName, instructions: Array[SafeInstructionDefinition], capabilities: Array[String] = []) -> ScenarioActionDefinition:
	return ScenarioActionDefinition.new(id, id, "test", &"public", &"test", 1, 1, 1, [], return_type, [&"action"], capabilities, &"safe", SafeProgramDefinition.new(instructions))


func _literal(value: Variant) -> SafeExpressionDefinition:
	var expression := SafeExpressionDefinition.new(SafeExpressionDefinition.Kind.LITERAL)
	expression.value = value
	return expression


func _variable(scope: StringName, name: String) -> SafeExpressionDefinition:
	var expression := SafeExpressionDefinition.new(SafeExpressionDefinition.Kind.VARIABLE)
	expression.scope = scope
	expression.name = name
	return expression


func _array(values: Array[SafeExpressionDefinition]) -> SafeExpressionDefinition:
	var expression := SafeExpressionDefinition.new(SafeExpressionDefinition.Kind.ARRAY)
	expression.set_values(values)
	return expression


func _message_texts(events: Array[DomainEvent]) -> Array[String]:
	var result: Array[String] = []
	for event: DomainEvent in events:
		if event.kind == &"message_shown":
			result.append(event.payload["text"])
	return result


func _trace_has(trace: Array[Dictionary], event_name: String) -> bool:
	for entry: Dictionary in trace:
		if entry.get("event") == event_name:
			return true
	return false


func _event_has(events: Array[DomainEvent], kind: StringName) -> bool:
	for event: DomainEvent in events:
		if event.kind == kind:
			return true
	return false


func _event_classic_id(events: Array[DomainEvent], kind: StringName) -> int:
	for event: DomainEvent in events:
		if event.kind == kind:
			return int(event.payload.get("classicId", -1))
	return -1

