func _ready() -> void:
	# The shell is structural; only its concrete controls should participate in
	# GUI hit testing. A full-window PASS control masks earlier root siblings.
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	_router.start_requested.connect(func(path: String, seed: int) -> void: start_package_requested.emit(path, seed))
	_router.refresh_requested.connect(func() -> void: refresh_campaigns_requested.emit())
	_router.intent_submitted.connect(func(intent: PlayerIntent) -> void: intent_submitted.emit(intent))
	_router.screen_changed.connect(_on_screen_changed)
	_router.system_action_requested.connect(_on_system_action_requested)
	_router.presentation_setting_changed.connect(_on_presentation_setting_changed)
	_party_roster.character_selected.connect(_on_character_selected)
	_smoke_action.pressed.connect(_on_smoke_pressed)
	resized.connect(_apply_layout)
	_build_menus()
	set_status("Choose a validated Realmz campaign")
	_apply_layout()


func present(game_view: GameView) -> void:
	var previous_campaign_id := _current_view.campaign_id if _current_view != null and _current_view.session_started else ""
	_current_view = game_view
	if game_view == null or not game_view.session_started:
		_latest_classic_text = ""
		_package_status.text = "No campaign"
		_clock_label.text = "Day —"
		_gold_label.text = "Gold —"
		_coordinates_label.text = "Map —"
		_fatigue_label.text = "Fatigue —"
		_party_roster.present(game_view)
		_router.present(game_view)
		_set_play_regions_visible(false)
		_update_command_availability()
		return
	if previous_campaign_id != game_view.campaign_id:
		_latest_classic_text = ""
	_clock_label.text = "Day %d • %02d:00" % [game_view.realmz_day, game_view.realmz_hour]
	_gold_label.text = "Gold %d" % game_view.pooled_gold
	_coordinates_label.text = "%s • %d,%d" % [game_view.party_map_id, game_view.party_coordinate.x, game_view.party_coordinate.y]
	_fatigue_label.text = "Fatigue %d" % game_view.party_fatigue
	_package_status.text = game_view.campaign_summary.title if game_view.campaign_summary != null else game_view.campaign_id
	if _selected_character_id.is_empty() and not game_view.party_members.is_empty():
		_selected_character_id = game_view.party_members[0].id
	_party_roster.present(game_view, _selected_character_id)
	_router.present(game_view)
	var play_regions_visible := not _router.full_stage_overlay_visible()
	_set_play_regions_visible(play_regions_visible)
	if game_view.combat_view != null and _router.current_screen() == &"exploration":
		_router.open_screen(&"combat")
	elif game_view.pending_interaction != null and game_view.pending_interaction.kind in [InteractionRequest.SHOP, InteractionRequest.TEMPLE, InteractionRequest.BANK] and _router.current_screen() == &"exploration":
		_router.open_screen(&"services")
	_build_menus()
	_rebuild_command_deck()


func present_step(step: SessionStep) -> void:
	if step == null:
		return
	if step.state == SessionStep.State.FAILED:
		set_status("Action failed • %s" % step.error_message, true)
		_append_narrative("Action failed: %s" % step.error_message)
		return
	_picture_stage.visible = false
	for event: DomainEvent in step.events:
		_present_event(event)


func latest_classic_text() -> String:
	return _latest_classic_text


func set_package_media(media: PackageMediaCatalog) -> void:
	_media = media
	_party_roster.set_media_catalog(media)
	_router.set_media_catalog(media)


func present_media_events(events: Array[DomainEvent], media: PackageMediaCatalog) -> void:
	set_package_media(media)
	if media == null:
		return
	for event: DomainEvent in events:
		if event.kind != &"picture_requested":
			continue
		var picture_id := int(event.payload.get("pictureId", 0))
		var asset := media.asset_by_resource("PICT", picture_id)
		if asset == null:
			_picture.texture = null
			_picture_caption.text = "PICT %d unavailable" % picture_id
			_picture_stage.visible = true
			continue
		var image := _decode_image(asset, media.read_bytes(asset))
		_picture.texture = ImageTexture.create_from_image(image) if image != null else null
		_picture.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
		_picture_caption.text = asset.label
		_picture_stage.visible = true


func apply_settings(settings: PresentationSettings) -> void:
	if settings == null:
		return
	_presentation_settings = settings
	var base_theme: Theme = load("res://src/presentation/classic_ui_theme.tres")

func _on_menu_item_pressed(item_id: int, menu: MenuButton) -> void:
	var entry: Dictionary = _menu_actions.get(menu.get_instance_id(), {}).get(item_id, {})
	if entry.is_empty():
		return
	if entry.has("route"):
		_router.open_screen(StringName(entry["route"]))
	elif entry.has("command"):
		_activate_command(StringName(entry["command"]))
	elif entry.has("system"):
		_on_system_action_requested(StringName(entry["system"]), null)


func _rebuild_command_deck() -> void:
	if not is_node_ready() or _profile == null:
		return
	for child: Node in _command_grid.get_children():
		_command_grid.remove_child(child)
		child.queue_free()
	_simulation_buttons.clear()
	var context := &"encounter" if _current_view != null and _current_view.pending_interaction != null else _router.current_screen()
	for definition: Dictionary in ClassicCommandCatalog.for_context(context):
		var asset_id := StringName(definition.get("asset_id", &""))
		var button: BaseButton
		if not asset_id.is_empty() and ClassicUiAssetCatalog.texture(asset_id) != null:
			var bitmap := ClassicBitmapButton.new()
			bitmap.configure(definition, _profile.bitmap_scale)
			bitmap.command_requested.connect(_activate_command)
			button = bitmap
		else:
			var text_button := Button.new()
			text_button.text = String(definition.get("label", "Command"))
			text_button.custom_minimum_size = Vector2(54.0, 54.0)
			text_button.tooltip_text = String(definition.get("tooltip", ""))
			text_button.pressed.connect(_activate_command.bind(StringName(definition["id"])))
			button = text_button
		button.set_meta("focus_key", "command:%s" % definition["id"])
		_command_grid.add_child(button)
		_simulation_buttons[StringName(definition["id"])] = button
	_update_command_availability()


func _update_command_availability() -> void:
	for command_id: StringName in _simulation_buttons:
		var button := _simulation_buttons[command_id] as BaseButton
		var definition := ClassicCommandCatalog.command(command_id)
		var availability_id := StringName(definition.get("availability", &""))
		var reason := ""
		if _current_view == null or not _current_view.session_started:
			reason = "Begin a campaign first."
		elif _current_view.pending_interaction != null and not String(command_id).begins_with("encounter_"):
			reason = "Resolve the current interaction first."
		elif String(command_id).begins_with("encounter_"):
			reason = "Choose from the active encounter response controls."
		elif not availability_id.is_empty():
			reason = _availability_reason(availability_id)
		button.disabled = not reason.is_empty()
		button.tooltip_text = reason if not reason.is_empty() else String(definition.get("tooltip", ""))
		button.queue_redraw()


func _activate_command(command_id: StringName) -> void:
	match command_id:
		&"search": intent_submitted.emit(PlayerIntent.new(PlayerIntent.Kind.SEARCH))
		&"camp": intent_submitted.emit(PlayerIntent.camp())
		&"inventory": _router.open_screen(&"inventory")
		&"spells": _router.open_screen(&"spells")
		&"maps": _router.open_screen(&"journal")
		&"settings": _router.open_screen(&"system")
		&"save": save_requested.emit("quick")


func _on_screen_changed(screen_id: StringName) -> void:
	var play_regions_visible := _current_view != null and _current_view.session_started and not _router.full_stage_overlay_visible()
	_set_play_regions_visible(play_regions_visible)
	set_status(String(screen_id).replace("_", " ").capitalize())
	_rebuild_command_deck()
	route_changed.emit(screen_id)


func _set_play_regions_visible(visible: bool) -> void:
	_stage_frame.visible = visible
	_bottom_region.visible = visible
	play_stage_visibility_changed.emit(visible)


func _on_system_action_requested(action_id: StringName, value: Variant) -> void:
	match action_id:
		&"save": save_requested.emit("quick" if value == null else String(value))
		&"load": load_requested.emit("quick" if value == null else String(value))
		&"campaigns": show_campaign_selection()
		&"quit": quit_requested.emit()


func _on_presentation_setting_changed(setting_id: StringName, value: Variant) -> void:
	match setting_id:
		&"topology_debug": topology_debug_changed.emit(bool(value))
		&"dungeon_3d": dungeon_3d_changed.emit(bool(value))
		&"master_volume": master_volume_changed.emit(float(value))
		&"text_scale": text_scale_changed.emit(float(value))
		&"ui_scale_mode": ui_scale_mode_changed.emit(String(value))
		&"window_mode": window_mode_changed.emit(String(value))
		&"reduced_motion": reduced_motion_changed.emit(bool(value))


func _on_character_selected(character_id: String) -> void:
	_selected_character_id = character_id
	_router.open_screen(&"character")


func _on_smoke_pressed() -> void:
	_smoke_action.release_focus()
	if _current_view == null or not _current_view.session_started:
		set_status("MCP input verified • no package loaded")
		return
	intent_submitted.emit(PlayerIntent.new(PlayerIntent.Kind.SEARCH))


func _present_event(event: DomainEvent) -> void:
	match event.kind:
		&"message_shown":
			var text := String(event.payload.get("text", "Message"))
			_latest_classic_text = text
			_append_narrative(text)
			set_status("Continue when ready" if bool(event.payload.get("classicClick", false)) else text)
		&"party_created":
			set_status("Party created • the adventure begins")
			_append_narrative("The party enters the realm.")
		&"party_moved": set_status("%s • %d,%d" % [_current_view.party_map_id if _current_view != null else "Map", int(event.payload.get("x", 0)), int(event.payload.get("y", 0))])
		&"movement_blocked": set_status("That way is blocked")
		&"search_completed": _append_narrative("The party searches the area.")
		&"party_camped": _append_narrative("The party camps and recovers.")
		&"door_opened": _append_narrative("A door opens.")
		&"secret_discovered": _append_narrative("A secret is revealed.")
		&"battle_started": _append_narrative("Battle begins.")
		&"battle_completed": _append_narrative("Battle completed • %s" % event.payload.get("outcome", "resolved"))


func _append_narrative(text: String) -> void:
	if _narrative.text.is_empty() or _narrative.text == "Choose a validated Realmz campaign to begin.":
		_narrative.text = text
	else:
		_narrative.append_text("\n\n%s" % text)
	_narrative.scroll_to_line(_narrative.get_line_count())


func _availability_reason(action_id: StringName) -> String:
	if _current_view == null or not _current_view.session_started:
		return "Begin a campaign first."
	var availability := _current_view.availability(action_id)
	return "" if availability.enabled else availability.reason


func _session_reason() -> String:
	return "" if _current_view != null and _current_view.session_started else "Begin a campaign first."


func _decode_image(asset: PackageMediaAsset, bytes: PackedByteArray) -> Image:
	if bytes.is_empty():
		return null
	var image := Image.new()

var extension := asset.path.get_extension().to_lower()
var error := ERR_UNAVAILABLE
if asset.mime_type.to_lower() == "image/png" or extension == "png":
	error = image.load_png_from_buffer(bytes)
elif asset.mime_type.to_lower() in ["image/jpeg", "image/jpg"] or extension in ["jpg", "jpeg"]:
	error = image.load_jpg_from_buffer(bytes)
elif asset.mime_type.to_lower() == "image/webp" or extension == "webp":
	error = image.load_webp_from_buffer(bytes)
return image if error == OK else null

class_name ClassicAudioPresenter
extends Node

signal sound_observed(sound_id: int)

const CHANNEL_COUNT: int = 4

var last_sound_id: int = 0
var master_volume: float = 1.0
var _players: Array[AudioStreamPlayer] = []
var _channel_index: int = -1
var _pending_sounds: Array[Dictionary] = []
var _processing_sounds: bool = false


func _ready() -> void:
	for index: int in range(CHANNEL_COUNT):
		var player := AudioStreamPlayer.new()
		player.name = "ClassicSoundChannel%d" % (index + 1)
		_players.append(player)
		add_child(player)
	_apply_volume()


func present_events(events: Array[DomainEvent], media: PackageMediaCatalog) -> void:
	for event: DomainEvent in events:
		if event.kind != &"sound_requested":
			continue
		last_sound_id = int(event.payload.get("soundId", 0))
		sound_observed.emit(last_sound_id)
		if media == null:
			continue
		var asset := media.sound_by_resource_id(last_sound_id)
		if asset == null:
			continue
		var bytes := media.read_bytes(asset)
		var stream := _decode_stream(asset, bytes)
		if stream == null:
			continue
		_pending_sounds.append({"stream": stream, "waitForCompletion": bool(event.payload.get("waitForCompletion", false))})
	_drain_sound_queue()


func set_master_volume(value: float) -> void:
	master_volume = clampf(value, 0.0, 1.0)
	_apply_volume()


func _apply_volume() -> void:
	for player: AudioStreamPlayer in _players:
		player.volume_db = -80.0 if master_volume <= 0.0 else linear_to_db(master_volume)


func _drain_sound_queue() -> void:
	if _processing_sounds:
		return
	_processing_sounds = true
	while not _pending_sounds.is_empty():
		var request: Dictionary = _pending_sounds.pop_front()
		var player := _next_channel()
		if player == null:
			continue
		player.stop()
		player.stream = request["stream"] as AudioStream
		player.play()
		if bool(request["waitForCompletion"]) and player.playing:
			await player.finished
	_processing_sounds = false


func _next_channel() -> AudioStreamPlayer:
	if _players.is_empty():
		return null
	_channel_index = (_channel_index + 1) % _players.size()
	return _players[_channel_index]


func _decode_stream(asset: PackageMediaAsset, bytes: PackedByteArray) -> AudioStream:
	if bytes.is_empty():
		return null
	var mime := asset.mime_type.to_lower()
	var extension := asset.path.get_extension().to_lower()
	if mime == "audio/wav" or mime == "audio/x-wav" or extension == "wav":
		return AudioStreamWAV.load_from_buffer(bytes)
	if mime in ["audio/mpeg", "audio/mp3"] or extension == "mp3":
		return AudioStreamMP3.load_from_buffer(bytes)
	if mime in ["audio/ogg", "audio/vorbis"] or extension == "ogg":
		return AudioStreamOggVorbis.load_from_buffer(bytes)
	return null

class_name ClassicBitmapButton
extends TextureButton

signal command_requested(command_id: StringName)

const FOCUS_COLOR := Color("f8e36f")
const HOVER_COLOR := Color("80d6e7")
const DISABLED_OVERLAY := Color(0.04, 0.05, 0.055, 0.64)

var command_id: StringName
var _native_size := Vector2i(50, 50)
var _art_scale: int = 1


func _ready() -> void:
	texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
	ignore_texture_size = true
	stretch_mode = TextureButton.STRETCH_KEEP_ASPECT_CENTERED
	focus_mode = Control.FOCUS_ALL
	mouse_entered.connect(queue_redraw)
	mouse_exited.connect(queue_redraw)
	focus_entered.connect(queue_redraw)
	focus_exited.connect(queue_redraw)
	button_down.connect(queue_redraw)
	button_up.connect(queue_redraw)
	pressed.connect(func() -> void: command_requested.emit(command_id))


func configure(definition: Dictionary, art_scale: int = 1) -> void:
	command_id = StringName(definition.get("id", &""))
	var asset_id := StringName(definition.get("asset_id", &""))
	texture_normal = ClassicUiAssetCatalog.texture(asset_id)
	_native_size = ClassicUiAssetCatalog.native_size(asset_id)
	if _native_size.x <= 0 or _native_size.y <= 0:
		_native_size = Vector2i(50, 50)
	tooltip_text = String(definition.get("tooltip", ""))
	var accelerator := String(definition.get("accelerator", ""))
	if not accelerator.is_empty():
		tooltip_text += " [%s]" % accelerator
	set_art_scale(art_scale)


func set_art_scale(value: int) -> void:
	_art_scale = 2 if value >= 2 else 1
	custom_minimum_size = Vector2(_native_size * _art_scale) + Vector2(6.0, 6.0)
	queue_redraw()


func _draw() -> void:
	var rect := Rect2(Vector2(1.0, 1.0), size - Vector2(2.0, 2.0))
	if disabled:
		draw_rect(rect, DISABLED_OVERLAY, true)
	if button_pressed:
		draw_rect(rect.grow(-1.0), Color(0.95, 0.76, 0.24, 0.18), true)
	if has_focus():
		draw_rect(rect, FOCUS_COLOR, false, 2.0)
	elif is_hovered() and not disabled:
		draw_rect(rect, HOVER_COLOR, false, 1.0)

class_name ClassicMapPresenter
extends Control

signal movement_requested(direction: Vector2i)

const MOUSE_REPEAT_DELAY: float = 0.28
const MOUSE_REPEAT_INTERVAL: float = 0.11
const DETACHED_VIEW_DIAMETER: int = 25

@export var cell_size: float = 32.0
@export var map_origin: Vector2 = Vector2(0.0, 24.0)
@export var minimap_size: float = 94.0
@export var show_debug_facts: bool = false

var _view: GameView
var _media: PackageMediaCatalog
var _atlas_assets: Dictionary = {}
var _atlas_textures: Dictionary = {}
var _overlay_textures: Dictionary = {}
var _party_rect: Rect2
var _minimap_rect: Rect2
var _held_direction: Vector2i = Vector2i.ZERO
var _mouse_repeat_remaining: float = 0.0


func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_STOP
	set_process(true)


func _process(delta: float) -> void:
	if _held_direction == Vector2i.ZERO or not visible:
		return
	_mouse_repeat_remaining -= delta
	if _mouse_repeat_remaining <= 0.0:
		movement_requested.emit(_held_direction)
		_mouse_repeat_remaining = MOUSE_REPEAT_INTERVAL


func _gui_input(event: InputEvent) -> void:
	if event is InputEventMouseButton and event.button_index == MOUSE_BUTTON_LEFT:
		if event.pressed:
			_held_direction = _movement_direction_at(event.position)
			if _held_direction != Vector2i.ZERO:
				movement_requested.emit(_held_direction)
				_mouse_repeat_remaining = MOUSE_REPEAT_DELAY
				accept_event()
		else:
			_held_direction = Vector2i.ZERO
			_mouse_repeat_remaining = 0.0
	elif event is InputEventMouseMotion and event.button_mask & MOUSE_BUTTON_MASK_LEFT:
		_held_direction = _movement_direction_at(event.position)


func present(game_view: GameView) -> void:
	_view = game_view
	visible = game_view != null and game_view.session_started and game_view.map_view != null
	if not visible:
		_held_direction = Vector2i.ZERO
	queue_redraw()


func set_media_catalog(media: PackageMediaCatalog) -> void:
	_media = media
	_atlas_assets.clear()
	_atlas_textures.clear()
	_overlay_textures.clear()
	if _media == null:
		queue_redraw()
		return
	for asset: PackageMediaAsset in _media.assets():
		if not asset.is_tileset() and not asset.is_picture():
			continue
		var texture := _load_image_texture(asset)
		if texture == null:
			continue
		if asset.is_tileset():
			_atlas_assets[asset.id] = asset
			_atlas_textures[asset.id] = texture
		else:
			_overlay_textures[asset.id] = texture
	queue_redraw()


func _draw() -> void:
	if _view == null or _view.map_view == null:
		return
	var map_view := _view.map_view
	var font := ThemeDB.fallback_font
	var viewport_cells := viewport_cells_for(size, map_origin.y, cell_size)
	var draw_origin := map_draw_origin_for(size, map_origin, cell_size, viewport_cells)
	var camera := camera_top_left(map_view.party_coordinate, Vector2i(map_view.width, map_view.height), viewport_cells)
	var camera_end := camera + viewport_cells
	for cell: MapCellView in map_view.cells():
		if cell.coordinate.x < camera.x or cell.coordinate.y < camera.y or cell.coordinate.x >= camera_end.x or cell.coordinate.y >= camera_end.y:
			continue
		var rect := Rect2(draw_origin + Vector2(cell.coordinate - camera) * cell_size, Vector2.ONE * cell_size)
		_draw_cell(cell, rect, map_view.level_type, map_view.dark)
		if show_debug_facts:
			draw_rect(rect, Color(0.22, 0.25, 0.30), false, 1.0)
			_draw_edges(cell, rect)
			_draw_features(cell, rect)
			if cell.has_trigger:
				var center := rect.get_center()
				draw_colored_polygon(PackedVector2Array([center + Vector2(0, -6), center + Vector2(6, 0), center + Vector2(0, 6), center + Vector2(-6, 0)]), Color(0.95, 0.72, 0.26))
			if cell.in_random_region:
				draw_rect(rect.grow(-4.0), Color(0.48, 0.29, 0.58, 0.9), false, 2.0)
			var facts := "%s%s%s" % ["M" if cell.passable else "X", "L" if cell.blocks_los else "", "R" if cell.in_random_region else ""]
			draw_string(font, rect.position + Vector2(7, 17), facts, HORIZONTAL_ALIGNMENT_LEFT, -1, 12, Color(0.78, 0.82, 0.88))
	_party_rect = Rect2(draw_origin + Vector2(map_view.party_coordinate - camera) * cell_size, Vector2.ONE * cell_size)
	draw_circle(_party_rect.get_center(), 10.0, Color(0.92, 0.78, 0.34))
	draw_circle(_party_rect.get_center(), 5.0, Color(0.17, 0.12, 0.06))
	_draw_movement_cues(map_view, _party_rect)
	draw_string(font, Vector2(8.0, 17.0), "%s • %s" % [map_view.map_name, String(map_view.level_type)], HORIZONTAL_ALIGNMENT_LEFT, -1, 16, Color(0.86, 0.75, 0.42))
	var input_hint := "Click map • numpad / arrows / WASD" if map_view.level_type == &"land" else "Click map • arrows / WASD"
	draw_string(font, Vector2(size.x - 258.0, 17.0), input_hint, HORIZONTAL_ALIGNMENT_RIGHT, 250.0, 12, Color(0.66, 0.69, 0.73))
	_draw_minimap(map_view, font)


static func camera_top_left(party_coordinate: Vector2i, map_size: Vector2i, viewport_cells: Vector2i) -> Vector2i:
	var maximum := Vector2i(maxi(map_size.x - viewport_cells.x, 0), maxi(map_size.y - viewport_cells.y, 0))
	return Vector2i(
		clampi(party_coordinate.x - viewport_cells.x / 2, 0, maximum.x),
		clampi(party_coordinate.y - viewport_cells.y / 2, 0, maximum.y)
	)


static func viewport_cells_for(control_size: Vector2, header_height: float, native_cell_size: float) -> Vector2i:
	return Vector2i(
		mini(DETACHED_VIEW_DIAMETER, maxi(1, floori(control_size.x / native_cell_size))),
		mini(DETACHED_VIEW_DIAMETER, maxi(1, floori((control_size.y - header_height) / native_cell_size)))
	)


static func map_draw_origin_for(control_size: Vector2, minimum_origin: Vector2, native_cell_size: float, viewport_cells: Vector2i) -> Vector2:
	var map_pixel_size := Vector2(viewport_cells) * native_cell_size
	var available_height := maxf(control_size.y - minimum_origin.y, 0.0)
	return Vector2(
		maxf(minimum_origin.x, floorf((control_size.x - map_pixel_size.x) * 0.5)),
		minimum_origin.y + maxf(0.0, floorf((available_height - map_pixel_size.y) * 0.5))
	)


func _draw_cell(cell: MapCellView, rect: Rect2, level_type: StringName, dark: bool) -> void:
	if not cell.visible:
		draw_rect(rect, _cell_color(cell, level_type, dark), true)
		return
	var atlas_asset: PackageMediaAsset = _atlas_assets.get(cell.tileset_id) as PackageMediaAsset
	var atlas_texture: Texture2D = _atlas_textures.get(cell.tileset_id) as Texture2D
	if level_type == &"dungeon" and atlas_asset != null and atlas_texture != null and atlas_asset.id == "dungeon-top-down-302":
		_draw_dungeon_atlas_cell(cell, rect, atlas_asset, atlas_texture)
		if dark:
			draw_rect(rect, Color(0.0, 0.0, 0.0, 0.45), true)
		return
	var region := Rect2i() if atlas_asset == null else atlas_asset.region_for(cell.render_tile)
	if atlas_texture == null or not region.has_area():
		draw_rect(rect, _cell_color(cell, level_type, false), true)
	else:
		draw_texture_rect_region(atlas_texture, rect, Rect2(region))
	var overlay_texture: Texture2D = _overlay_textures.get(cell.overlay_asset_id) as Texture2D

	if overlay_texture != null:
		draw_texture_rect(overlay_texture, rect, false)
	if dark:
		draw_rect(rect, Color(0.0, 0.0, 0.0, 0.45), true)


func _draw_dungeon_atlas_cell(cell: MapCellView, rect: Rect2, atlas_asset: PackageMediaAsset, atlas_texture: Texture2D) -> void:
	_draw_atlas_region(rect, atlas_asset, atlas_texture, 16)
	if cell.terrain_id == "classic.dungeon.wall":
		_draw_atlas_region(rect, atlas_asset, atlas_texture, 1)
	if cell.has_feature(&"door"):
		_draw_atlas_region(rect, atlas_asset, atlas_texture, 3 if cell.feature_orientation(&"door") == &"vertical" else 2)
	var feature_tiles: Dictionary = {
		&"stairs": 4,
		&"column": 5,
		&"note": 6,
		&"secret": 7,
	}
	for feature_kind: StringName in feature_tiles:
		if cell.has_feature(feature_kind):
			_draw_atlas_region(rect, atlas_asset, atlas_texture, int(feature_tiles[feature_kind]))


func _draw_atlas_region(rect: Rect2, atlas_asset: PackageMediaAsset, atlas_texture: Texture2D, tile_id: int) -> void:
	var region := atlas_asset.region_for(tile_id)
	if region.has_area():
		draw_texture_rect_region(atlas_texture, rect, Rect2(region))


func _load_image_texture(asset: PackageMediaAsset) -> Texture2D:
	var bytes := _media.read_bytes(asset)
	if bytes.is_empty():
		return null
	var image := Image.new()
	var load_error := ERR_FILE_UNRECOGNIZED
	match asset.mime_type:
		"image/png":
			load_error = image.load_png_from_buffer(bytes)
		"image/jpeg":
			load_error = image.load_jpg_from_buffer(bytes)
		"image/webp":
			load_error = image.load_webp_from_buffer(bytes)
	if load_error != OK:
		return null
	if asset.width > 0 and asset.height > 0 and (image.get_width() != asset.width or image.get_height() != asset.height):
		return null
	return ImageTexture.create_from_image(image)


func _cell_color(cell: MapCellView, level_type: StringName, dark: bool = false) -> Color:
	var color: Color
	if not cell.visible:
		color = Color(0.025, 0.03, 0.04)
	elif not cell.passable:
		color = Color(0.16, 0.17, 0.20)
	elif cell.terrain_id.ends_with(".2"):
		color = Color(0.34, 0.50, 0.31)
	elif level_type == &"dungeon":
		color = Color(0.28, 0.27, 0.24)
	else:
		color = Color(0.20, 0.38, 0.27)
	return color.darkened(0.45) if dark else color


func _draw_edges(cell: MapCellView, rect: Rect2) -> void:
	var edge_points := {
		&"north": [rect.position, rect.position + Vector2(rect.size.x, 0)],
		&"east": [rect.position + Vector2(rect.size.x, 0), rect.end],
		&"south": [rect.position + Vector2(0, rect.size.y), rect.end],
		&"west": [rect.position, rect.position + Vector2(0, rect.size.y)],
	}
	for direction: StringName in edge_points:
		var kind := cell.edge_kind(direction)
		if kind == &"open":
			continue
		var points: Array = edge_points[direction]
		var color := Color(0.84, 0.75, 0.52) if kind == &"door" else Color(0.64, 0.40, 0.72) if kind == &"secret" else Color(0.62, 0.65, 0.70)
		draw_line(points[0], points[1], color, 4.0 if cell.edge_is_passable(direction) else 7.0)


func _draw_features(cell: MapCellView, rect: Rect2) -> void:
	var center := rect.get_center()
	if cell.has_feature(&"door"):
		draw_line(center + Vector2(-13, 0), center + Vector2(13, 0), Color(0.84, 0.63, 0.30), 5.0)
	if cell.has_feature(&"secret"):
		draw_string(ThemeDB.fallback_font, center + Vector2(-5, 6), "S", HORIZONTAL_ALIGNMENT_LEFT, -1, 18, Color(0.71, 0.46, 0.82))
	if cell.has_feature(&"stairs"):
		for offset: int in [-8, 0, 8]:
			draw_line(center + Vector2(-12, offset), center + Vector2(12, offset), Color(0.72, 0.72, 0.68), 2.0)
	if cell.has_feature(&"column"):
		draw_circle(center, 10.0, Color(0.64, 0.64, 0.62))


func _draw_minimap(map_view: MapView, font: Font) -> void:
	var scale := minf(minimap_size / float(map_view.width), minimap_size / float(map_view.height))
	var map_pixel_size := Vector2(map_view.width, map_view.height) * scale
	var origin := Vector2(size.x - map_pixel_size.x - 8.0, size.y - map_pixel_size.y - 8.0)
	_minimap_rect = Rect2(origin - Vector2.ONE * 4.0, map_pixel_size + Vector2.ONE * 8.0)
	draw_rect(_minimap_rect, Color(0.035, 0.04, 0.05, 0.9), true)
	draw_string(font, origin - Vector2(0, 7), "Map", HORIZONTAL_ALIGNMENT_LEFT, -1, 11, Color(0.72, 0.76, 0.82))
	for coordinate: Vector2i in map_view.visited_coordinates():
		var rect := Rect2(origin + Vector2(coordinate) * scale, Vector2.ONE * maxf(scale, 1.0))
		draw_rect(rect, Color(0.28, 0.48, 0.32), true)
	var party_center := origin + (Vector2(map_view.party_coordinate) + Vector2.ONE * 0.5) * scale
	draw_circle(party_center, maxf(2.0, scale * 1.5), Color(0.94, 0.78, 0.28))


