func initiative_order(characters: Array[CharacterState], monsters: Array[MonsterState], surprise: int, rng: RealmzRng) -> Array[String]:
	var order: Array[String] = []
	for character: CharacterState in characters:
		if character.current_health > 0:
			order.append(character.id)
	for monster: MonsterState in monsters:
		if monster.current_health > 0:
			order.append(monster.id)
	if surprise > 0:
		return _party_first(order, characters)
	if surprise < 0:
		return _monsters_first(order, monsters)
	for index: int in range(order.size() - 1, 0, -1):
		var swap_index := rng.draw_between(0, index, &"combat.initiative.slot")
		var held := order[index]
		order[index] = order[swap_index]
		order[swap_index] = held
	for left: int in order.size():
		for right: int in range(left, order.size() - 1):
			if _agility(order[right + 1], characters, monsters) > _agility(order[right], characters, monsters):
				var held := order[right]
				order[right] = order[right + 1]
				order[right + 1] = held
	return order

func _agility(id: String, characters: Array[CharacterState], monsters: Array[MonsterState]) -> int:
	for character: CharacterState in characters:
		if character.id == id:
			return character.agility
	for monster: MonsterState in monsters:
		if monster.id == id:
			return monster.agility
	return 0

func _monsters_first(order: Array[String], monsters: Array[MonsterState]) -> Array[String]:
	var monster_ids: Dictionary = {}
	for monster: MonsterState in monsters:
		monster_ids[monster.id] = true
	var first: Array[String] = []
	var last: Array[String] = []
	for id: String in order:
		if monster_ids.has(id):
			first.append(id)
		else:
			last.append(id)
	first.append_array(last)
	return first

func _finish_if_resolved(state: GameState, content: RealmzContent, events: Array[DomainEvent]) -> bool:
	var combat := state.combat
	var enemies_alive := false
	for monster: MonsterState in combat.monsters():
		if monster.current_health > 0 and monster.traitor:
			enemies_alive = true
			break
	var party_alive := false
	for character: CharacterState in state.party.characters():
		if character.current_health > 0:
			party_alive = true
			break
	if enemies_alive and party_alive:
		return false
	combat.completed = true
	combat.outcome = &"victory" if party_alive else &"defeat"
	state.last_battle_outcome = combat.outcome
	if combat.outcome == &"victory":
		var experience := 0
		for monster: MonsterState in combat.monsters():
			var definition := content.monster_by_id(monster.definition_id)
			if definition != null and monster.traitor:
				experience += maxi(0, definition.experience)
		for character: CharacterState in state.party.characters():
			if character.current_health > 0:
				character.experience += experience
		events.append(DomainEvent.new(&"battle_rewards_granted", {"experiencePerSurvivor": experience}))
	events.append(DomainEvent.new(&"battle_completed", {"battleId": combat.battle_id, "outcome": String(combat.outcome)}))
	return true

func _request_monster_death_macro(monster: MonsterState, definition: MonsterDefinition, events: Array[DomainEvent]) -> bool:
	if monster == null or definition == null or definition.death_macro <= 0:
		return false
	events.append(DomainEvent.new(&"monster_death_macro_requested", {
		"combatantId": monster.id,
		"definitionId": monster.definition_id,
		"classicMonsterId": definition.classic_id,
		"programId": "xap:%d" % definition.death_macro,
		"macroId": definition.death_macro,
		"traitor": monster.traitor,
	}))
	return true

func _process_monster_turns(state: GameState, content: RealmzContent, rng: RealmzRng, events: Array[DomainEvent]) -> void:
	var combat := state.combat
	var guard := combat.turn_order().size()
	while guard > 0 and not combat.completed:
		var actor_id := combat.active_actor_id()
		var monster := combat.monster_by_id(actor_id)
		if monster == null:
			break
		if monster.current_health > 0:
			var definition := content.monster_by_id(monster.definition_id)
			var character_targets: Array[CharacterState] = []
			if monster.traitor:
				for character: CharacterState in state.party.characters():
					if character.current_health > 0:
						character_targets.append(character)
			var monster_targets: Array[MonsterState] = []
			for candidate: MonsterState in combat.monsters():
				if candidate.id != monster.id and candidate.current_health > 0 and candidate.traitor != monster.traitor:
					monster_targets.append(candidate)
			var target_count := character_targets.size() + monster_targets.size()
			if target_count == 0:
				_finish_if_resolved(state, content, events)
				break
			var target_index := rng.draw_between(0, target_count - 1, &"combat.monster-target")
			var choice := _rules.monsters.choose_action(monster, definition, rng)
			if choice in [&"advance", &"missile"]:
				if target_index < character_targets.size():
					var character_target := character_targets[target_index]
					var character_resolution := _rules.combat.resolve_monster_attack(monster, definition, 0, character_target, rng)
					events.append(DomainEvent.new(&"combat_attack_resolved", {"actorId": monster.id, "targetId": character_target.id, "action": String(choice), "hit": character_resolution.hit, "damage": character_resolution.damage, "defeated": character_resolution.killed, "chance": character_resolution.chance, "roll": character_resolution.roll}))
				else:
					var monster_target := monster_targets[target_index - character_targets.size()]
					var monster_resolution := _rules.combat.resolve_monster_attack_monster(monster, definition, 0, monster_target, rng)
					events.append(DomainEvent.new(&"combat_attack_resolved", {"actorId": monster.id, "targetId": monster_target.id, "action": String(choice), "hit": monster_resolution.hit, "damage": monster_resolution.damage, "defeated": monster_resolution.killed, "chance": monster_resolution.chance, "roll": monster_resolution.roll}))
					if monster_resolution.killed:
						var target_definition := content.monster_by_id(monster_target.definition_id)
						if _request_monster_death_macro(monster_target, target_definition, events):
							combat.advance_turn()
							return
			else:
				events.append(DomainEvent.new(&"combat_monster_action", {"actorId": monster.id, "action": String(choice)}))
		combat.advance_turn()
		if _finish_if_resolved(state, content, events):
			break
		guard -= 1

func _party_first(order: Array[String], characters: Array[CharacterState]) -> Array[String]:
	var party_ids: Dictionary = {}
	for character: CharacterState in characters:
		party_ids[character.id] = true
	var first: Array[String] = []
	var last: Array[String] = []
	for id: String in order:
		if party_ids.has(id):
			first.append(id)
		else:
			last.append(id)
	first.append_array(last)
	return first

func start_battle(state: GameState, content: RealmzContent, battle: BattleDefinition, rng: RealmzRng, surprise: int = 0) -> CombatFlowResult:
	if state == null or content == null or battle == null or rng == null:
		return CombatFlowResult.failed(&"invalid_battle", "Battle setup requires validated state, content, and randomness.")
	if state.combat != null and not state.combat.completed:
		return CombatFlowResult.failed(&"battle_already_active", "A Realmz battle is already active.")
	var authored_monsters: Array[MonsterState] = []
	for slot: BattleMonsterSlotDefinition in battle.monster_slots():
		var definition_id := slot.monster_id
		var definition := content.monster_by_id(definition_id)
		if definition == null:
			return CombatFlowResult.failed(&"unknown_monster", "Battle '%s' references unavailable monster '%s'." % [battle.id, definition_id])
		var instance_id := state.next_instance_id("combat.monster")
		var monster := _rules.monsters.build_monster(definition, instance_id, -1, 0, state.clock.day(), rng)
		if monster == null:
			return CombatFlowResult.failed(&"invalid_monster", "Battle '%s' could not construct monster '%s'." % [battle.id, definition_id])
		if slot.invert_traitor:
			monster.traitor = not monster.traitor
		authored_monsters.append(monster)
	if authored_monsters.is_empty():
		return CombatFlowResult.failed(&"empty_battle", "Battle '%s' has no viable monsters." % battle.id)
	var monsters: Array[MonsterState] = []
	var consumed_allies: Array[String] = []
	if not state.allies_suspended:
		for ally: MonsterState in state.party.allies():
			if ally.current_health <= 0:
				continue
			ally.traitor = false
			monsters.append(ally)
			consumed_allies.append(ally.id)
		state.party.set_allies([])
	monsters.append_array(authored_monsters)
	var combat := CombatState.new(battle.id, monsters, battle.macro_id)
	combat.set_turn_order(_rules.combat.initiative_order(state.party.characters(), monsters, surprise, rng))
	state.combat = combat
	var events: Array[DomainEvent] = [DomainEvent.new(&"battle_started", {"battleId": battle.id, "classicId": battle.classic_id, "distance": battle.distance, "surprise": surprise, "turnOrder": combat.turn_order(), "consumedAllyIds": consumed_allies})]
	_process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func submit_action(state: GameState, content: RealmzContent, actor_id: String, action: StringName, target_id: String, rng: RealmzRng) -> CombatFlowResult:
	var combat := state.combat
	if combat == null or combat.completed:
		return CombatFlowResult.failed(&"no_active_battle", "No Realmz battle is accepting combat actions.")
	if combat.active_actor_id() != actor_id:
		return CombatFlowResult.failed(&"wrong_combat_actor", "Combat action actor '%s' does not own the current turn." % actor_id)
	var actor := state.party.character_by_id(actor_id)
	if actor == null or actor.current_health <= 0:
		return CombatFlowResult.failed(&"invalid_combat_actor", "The current combat actor is unavailable.")
	var events: Array[DomainEvent] = []
	match action:
		&"attack":
			var target := combat.monster_by_id(target_id)
			if target == null or target.current_health <= 0 or not target.traitor:
				return CombatFlowResult.failed(&"invalid_combat_target", "The selected monster is unavailable.")
			var definition := content.monster_by_id(target.definition_id)
			var damage_bonus := _rules.inventory.equipped_damage_bonus(actor, content.item_definitions())
			var resolution := _rules.combat.resolve_character_attack(actor, target, definition, damage_bonus, rng, state.clock.day())
			events.append(DomainEvent.new(&"combat_attack_resolved", {"actorId": actor.id, "targetId": target.id, "hit": resolution.hit, "damage": resolution.damage, "defeated": resolution.killed, "chance": resolution.chance, "roll": resolution.roll}))
			if resolution.killed and _request_monster_death_macro(target, definition, events):
				combat.advance_turn()
				return CombatFlowResult.succeeded(events)
		&"defend", &"pass":
			events.append(DomainEvent.new(&"combat_turn_passed", {"actorId": actor.id, "action": String(action)}))
		&"retreat":
			combat.completed = true
			combat.outcome = &"retreated"
			state.last_battle_outcome = combat.outcome
			events.append(DomainEvent.new(&"battle_completed", {"battleId": combat.battle_id, "outcome": String(combat.outcome)}))
			return CombatFlowResult.succeeded(events, true)
		_:
			return CombatFlowResult.failed(&"unknown_combat_action", "Combat action '%s' is not available." % action)
	combat.advance_turn()
	if _finish_if_resolved(state, content, events):
		return CombatFlowResult.succeeded(events, true)
	_process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func cast_spell(state: GameState, content: RealmzContent, caster_id: String, target_id: String, spell_id: String, power_level: int, rng: RealmzRng) -> CombatFlowResult:
	var combat := state.combat
	if combat == null or combat.completed or combat.active_actor_id() != caster_id:
		return CombatFlowResult.failed(&"invalid_spell_turn", "The caster does not own an active combat turn.")
	var caster := state.party.character_by_id(caster_id)
	var target := combat.monster_by_id(target_id)
	var spell := content.spell_by_id(spell_id)
	if caster == null or target == null or target.current_health <= 0 or not target.traitor or spell == null or power_level < 1:
		return CombatFlowResult.failed(&"invalid_spell_target", "The spell, caster, power, or target is unavailable.")
	if not caster.known_spells().has(spell.id):
		return CombatFlowResult.failed(&"spell_not_known", "The caster does not know '%s'." % spell.id)
	var target_definition := content.monster_by_id(target.definition_id)
	var resolution := _rules.magic.resolve_character_spell(caster, target, target_definition, spell, power_level, caster.level, rng)
	if resolution == null or not resolution.cast:
		return CombatFlowResult.failed(&"spell_cast_failed", "The spell could not be cast with the available spell points.")
	var events: Array[DomainEvent] = [DomainEvent.new(&"combat_spell_resolved", {"actorId": caster.id, "targetId": target.id, "spellId": spell.id, "power": power_level, "resisted": resolution.resisted, "saved": resolution.saved, "damage": resolution.damage, "duration": resolution.duration, "defeated": resolution.target_defeated})]
	combat.advance_turn()
	if resolution.target_defeated and _request_monster_death_macro(target, target_definition, events):
		return CombatFlowResult.succeeded(events)
	if _finish_if_resolved(state, content, events):
		return CombatFlowResult.succeeded(events, true)
	_process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func continue_after_monster_death_macro(state: GameState, content: RealmzContent, rng: RealmzRng) -> CombatFlowResult:
	if state == null or content == null or rng == null or state.combat == null:
		return CombatFlowResult.failed(&"invalid_death_macro_continuation", "Monster death-macro continuation requires an active battle.")
	var events: Array[DomainEvent] = []
	if state.combat.completed or _finish_if_resolved(state, content, events):
		return CombatFlowResult.succeeded(events, true)
	_process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func ally_selection_payload(state: GameState, content: RealmzContent) -> Dictionary:
	if state == null or content == null or state.combat == null or not state.combat.completed or state.allies_suspended:
		return {}
	var candidates: Array[Dictionary] = []
	for monster: MonsterState in state.combat.monsters():
		if candidates.size() >= 32 or monster.current_health <= 0 or monster.traitor:
			continue
		var definition := content.monster_by_id(monster.definition_id)
		if definition == null or definition.can_summon == 0:
			continue
		candidates.append({
			"id": monster.id,
			"name": monster.name,
			"currentHealth": monster.current_health,
			"maximumHealth": monster.maximum_health,
			"classicMonsterId": definition.classic_id,
			"required": definition.can_summon < 0,
			"canSummon": definition.can_summon,
		})
	# bodycount.c promotes mandatory allies and then orders optional survivors by stamina.
	for _pass: int in range(maxi(0, candidates.size() - 1)):
		for index: int in range(maxi(0, candidates.size() - 1)):
			var current: Dictionary = candidates[index]
			var following: Dictionary = candidates[index + 1]
			if int(current["currentHealth"]) < int(following["currentHealth"]) or int(following["canSummon"]) < 0:
				candidates[index] = following
				candidates[index + 1] = current
	var required_ids: Array[String] = []
	for candidate: Dictionary in candidates:
		if candidate["required"]:
			required_ids.append(candidate["id"])
	var maximum := mini(18, 4 + required_ids.size())
	var selected_ids: Array[String] = required_ids.duplicate()
	for index: int in range(mini(10, candidates.size())):
		var candidate_id: String = candidates[index]["id"]
		if selected_ids.size() < maximum and not selected_ids.has(candidate_id):
			selected_ids.append(candidate_id)
	return {
		"prompt": "Choose the allies who will continue with the party.",
		"candidates": candidates,
		"requiredIds": required_ids,
		"maximum": maximum,
		"selectedIds": selected_ids,
	}

func apply_ally_selection(state: GameState, content: RealmzContent, selected_value: Variant) -> CombatFlowResult:
	var payload := ally_selection_payload(state, content)
	if payload.is_empty() or not selected_value is Array:
		return CombatFlowResult.failed(&"invalid_ally_selection", "The post-battle ally selection is unavailable.")
	var selected_ids: Array[String] = []
	for value: Variant in selected_value:
		if not value is String or value.is_empty() or selected_ids.has(value):
			return CombatFlowResult.failed(&"invalid_ally_selection", "Selected allies must be unique stable IDs.")
		selected_ids.append(value)
	if selected_ids.size() > int(payload["maximum"]):
		return CombatFlowResult.failed(&"invalid_ally_selection", "The ally selection exceeds the Classic body-count limit.")
	var candidate_ids: Array[String] = []
	for candidate: Dictionary in payload["candidates"]:
		candidate_ids.append(candidate["id"])
	for required_id: String in payload["requiredIds"]:
		if not selected_ids.has(required_id):
			return CombatFlowResult.failed(&"required_ally_missing", "A scenario-mandatory ally cannot be left behind.")
	for selected_id: String in selected_ids:
		if not candidate_ids.has(selected_id):
			return CombatFlowResult.failed(&"invalid_ally_selection", "The ally selection contains an unavailable combatant.")
	var retained: Array[MonsterState] = []
	for selected_id: String in selected_ids:
		var monster := state.combat.monster_by_id(selected_id)
		if monster == null:
			return CombatFlowResult.failed(&"invalid_ally_selection", "The selected combatant is unavailable.")
		monster.traitor = false
		retained.append(monster)
	state.party.set_allies(retained)
	return CombatFlowResult.succeeded([DomainEvent.new(&"allies_selected", {"battleId": state.combat.battle_id, "allyIds": selected_ids, "maximum": payload["maximum"]})], true)

static func from_data(data: Variant) -> GameState:
	if not data is Dictionary:
		return null
	for field: String in ["party", "clock", "searchedCells", "worldOverlays"]:
		if not data.has(field):
			return null
	var party_state := PartyState.from_data(data["party"])
	var realmz_clock := RealmzClock.from_data(data["clock"])
	var world_state := WorldState.from_data(data["worldOverlays"])
	if party_state == null or realmz_clock == null or world_state == null or not data["searchedCells"] is Array:
		return null
	var state := GameState.new(party_state, realmz_clock, world_state)
	if data.has("combat") and data["combat"] != null:
		state.combat = CombatState.from_data(data["combat"])
		if state.combat == null:
			return null
	for key: Variant in data["searchedCells"]:
		if not key is String or key.is_empty():
			return null
		state._searched_cells[key] = true
	if data.has("randomEncountersEnabled"):
		for field: String in ["randomEncountersEnabled", "campingAllowed", "lastBattleOutcome", "questValues", "selectedCharacterIds", "timedEncounterOverrides", "instanceCounter", "eliminatedSimpleOptions", "shopOverrides", "shopInflationOverrides", "encounterAttempts", "thiefEncounterTypeFlags", "scenarioProgramOverrides"]:
			if not data.has(field):
				return null
		if not data["randomEncountersEnabled"] is bool or not data["campingAllowed"] is bool or not data["lastBattleOutcome"] is String or not data["questValues"] is Dictionary or not data["selectedCharacterIds"] is Array or not data["timedEncounterOverrides"] is Dictionary:
			return null
		if data.has("partySetupCompleted") and not data["partySetupCompleted"] is bool:
			return null
		var counter := _integer(data["instanceCounter"])
		if counter < 0:
			return null
		state.random_encounters_enabled = data["randomEncountersEnabled"]
		state.camping_allowed = data["campingAllowed"]
		if data.has("partyInBoat") and (not data["partyInBoat"] is bool or not data.get("partyCamping") is bool):
			return null
		state.party_in_boat = bool(data.get("partyInBoat", false))
		state.party_camping = bool(data.get("partyCamping", false))
		if data.has("priestTurningAllowed") and not data["priestTurningAllowed"] is bool:
			return null
		state.priest_turning_allowed = bool(data.get("priestTurningAllowed", true))
		if data.has("alliesSuspended") and not data["alliesSuspended"] is bool:
			return null
		state.allies_suspended = bool(data.get("alliesSuspended", false))
		for field: String in ["characterSpellcasting", "monsterSpellcasting", "spellCharging"]:
			if data.has(field) and not data[field] is bool:
				return null
		state.character_spellcasting = bool(data.get("characterSpellcasting", false))
		state.monster_spellcasting = bool(data.get("monsterSpellcasting", false))
		state.spell_charging = bool(data.get("spellCharging", false))
		if data.has("lastMoveX") or data.has("lastMoveY"):
			var last_x := _signed_integer(data.get("lastMoveX"))
			var last_y := _signed_integer(data.get("lastMoveY"))
			var last_direction := Vector2i(last_x, last_y)
			if last_direction != Vector2i.ZERO and not MapTopology.is_cardinal_direction(last_direction) and not MapTopology.is_diagonal_direction(last_direction):
				return null
			state.last_move_direction = last_direction
		if data.has("activeShopId") or data.has("shopAcceptRanges"):
			if not data.get("activeShopId") is String or not data.get("shopAcceptRanges") is Array:
				return null
			var accept_ranges: Array[int] = []
			for value: Variant in data["shopAcceptRanges"]:
				var accepted := _signed_integer(value)
				if accepted < -32_768 or accepted > 32_767:
					return null
				accept_ranges.append(accepted)
			if not String(data["activeShopId"]).is_empty() and not state.set_active_shop(data["activeShopId"], accept_ranges):
				return null
			if String(data["activeShopId"]).is_empty() and not accept_ranges.is_empty():
				return null
		state.last_battle_outcome = StringName(data["lastBattleOutcome"])
		state.party_setup_completed = bool(data.get("partySetupCompleted", false))
		for key: Variant in data["questValues"]:
			if not key is String or not key.is_valid_int():
				return null
			var quest_id: int = String(key).to_int()
			var loaded_quest_value := _signed_integer(data["questValues"][key])
			if quest_id < 0 or quest_id >= 100 or loaded_quest_value < -32_768 or loaded_quest_value > 32_767:
				return null
			state._quest_values[quest_id] = loaded_quest_value
		var selected: Array[String] = []
		for id: Variant in data["selectedCharacterIds"]:
			if not id is String:
				return null
			selected.append(id)
		if not state.set_selected_character_ids(selected):
			return null
		for key: Variant in data["timedEncounterOverrides"]:
			if not key is String or not key.is_valid_int() or not data["timedEncounterOverrides"][key] is Dictionary:
				return null
			state._timed_encounter_overrides[String(key).to_int()] = data["timedEncounterOverrides"][key].duplicate(true)
		state._instance_counter = counter
		if not data["eliminatedSimpleOptions"] is Array or not data["shopOverrides"] is Dictionary:
			return null
		for key: Variant in data["eliminatedSimpleOptions"]:
			if not key is String or key.is_empty():
				return null
			state._eliminated_simple_options[key] = true
		for key: Variant in data["shopOverrides"]:
			var quantity := _integer(data["shopOverrides"][key])
			if not key is String or key.is_empty() or quantity < 0 or quantity > 32_767:
				return null
			state._shop_overrides[key] = quantity
		if not data["shopInflationOverrides"] is Dictionary:
			return null
		for key: Variant in data["shopInflationOverrides"]:
			var inflation := _integer(data["shopInflationOverrides"][key])
			if not key is String or key.is_empty() or inflation < 0 or inflation > 32_767:
				return null
			state._shop_inflation_overrides[key] = inflation
		if not data["encounterAttempts"] is Dictionary or not data["thiefEncounterTypeFlags"] is Dictionary:
			return null
		for key: Variant in data["encounterAttempts"]:
			var count := _integer(data["encounterAttempts"][key])
			if not key is String or key.is_empty() or count < 0 or count > 32_767:
				return null
			state._encounter_attempts[key] = count
		for key: Variant in data["thiefEncounterTypeFlags"]:
			var flags: Variant = data["thiefEncounterTypeFlags"][key]
			if not key is String or not String(key).is_valid_int() or not flags is Array or flags.size() != 10:
				return null
			var copied: Array[bool] = []
			for flag: Variant in flags:
				if not flag is bool:
					return null
				copied.append(flag)
			state._thief_encounter_type_flags[key] = copied
		if not data["scenarioProgramOverrides"] is Dictionary:
			return null
		for key: Variant in data["scenarioProgramOverrides"]:
			var target: Variant = data["scenarioProgramOverrides"][key]
			if not key is String or key.is_empty() or not target is String or target.is_empty():
				return null
			state._scenario_program_overrides[key] = target
	return state

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

static func _signed_integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

static func _sorted_dictionary(source: Dictionary) -> Dictionary:
	var result: Dictionary = {}
	var keys: Array = source.keys()
	keys.sort()
	for key: Variant in keys:
		result[key] = source[key]
	return result

func consume_random_door(index: int) -> void:
	if index >= 0 and index < _random_door_percents.size() and _random_door_percents[index] > 0:
		_random_door_percents[index] = 0

static func from_data(data: Variant) -> RandomRegionState:
	if not data is Dictionary:
		return null
	for field: String in ["id", "chanceTenThousand", "battleMinimum", "battleMaximum", "randomDoorPercent"]:
		if not data.has(field):
			return null
	if not data["id"] is String or data["id"].is_empty():
		return null
	var chance := _signed_integer(data["chanceTenThousand"])
	var battle_min := _signed_integer(data["battleMinimum"])
	var battle_max := _signed_integer(data["battleMaximum"])
	if chance == -100_000 or battle_min == -100_000 or battle_max == -100_000 or not data["randomDoorPercent"] is Array or data["randomDoorPercent"].size() != 3:
		return null
	var door_percents: Array[int] = []
	for value: Variant in data["randomDoorPercent"]:
		var percent := _signed_integer(value)
		if percent == -100_000:
			return null
		door_percents.append(percent)
	return RandomRegionState.new(data["id"], chance, battle_min, battle_max, door_percents)

static func _signed_integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

func set_active_shop(shop_id: String, accept_ranges: Array[int]) -> bool:
	if shop_id.is_empty() or accept_ranges.size() != 4:
		return false
	active_shop_id = shop_id
	_shop_accept_ranges = accept_ranges.duplicate()
	return true

static func from_data(data: Variant) -> MonsterState:
	if not data is Dictionary:
		return null
	for field: String in ["id", "definitionId", "name", "hitDice", "currentHealth", "maximumHealth", "agility", "armor", "magicResistance", "spellPoints", "maximumSpellPoints", "traitor", "weaponId", "conditions"]:
		if not data.has(field):
			return null
	if not data["id"] is String or data["id"].is_empty() or not data["definitionId"] is String or data["definitionId"].is_empty() or not data["name"] is String or not data["traitor"] is bool or not data["weaponId"] is String:
		return null
	var values: Dictionary = {}
	for field: String in ["hitDice", "currentHealth", "maximumHealth", "agility", "armor", "magicResistance", "spellPoints", "maximumSpellPoints"]:
		var value := _integer(data[field])
		if value == -100_000:
			return null
		values[field] = value
	if values["hitDice"] < 0 or values["maximumHealth"] < 1 or values["currentHealth"] > values["maximumHealth"] or values["maximumSpellPoints"] < 0 or values["spellPoints"] < 0 or values["spellPoints"] > values["maximumSpellPoints"]:
		return null
	var loaded_conditions := ConditionSet.from_data(data["conditions"], ConditionSet.CHARACTER_COUNT)
	if loaded_conditions == null:
		return null
	var result := MonsterState.new(data["id"], data["definitionId"], data["name"], values["currentHealth"], values["maximumHealth"], values["hitDice"], values["agility"], values["armor"], values["magicResistance"], values["maximumSpellPoints"], data["traitor"])
	result.spell_points = values["spellPoints"]
	result.icon_id = _integer(data.get("iconId", 0))
	if result.icon_id == -100_000:
		return null
	result.surrender_percent = _integer(data.get("surrenderPercent", 0))
	if result.surrender_percent == -100_000:
		return null
	result.weapon_id = data["weaponId"]
	result.conditions = loaded_conditions
	return result

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

func record_encounter_attempt(kind: StringName, encounter_id: int) -> int:
	var key := "%s:%d" % [String(kind), encounter_id]
	var next := mini(32_767, int(_encounter_attempts.get(key, 0)) + 1)
	_encounter_attempts[key] = next
	return next

func thief_encounter_type_flags(encounter: ThiefEncounterDefinition) -> Array[bool]:
	var key := str(encounter.id)
	if not _thief_encounter_type_flags.has(key):
		return encounter.type_flags()
	var result: Array[bool] = []
	for value: Variant in _thief_encounter_type_flags[key]:
		result.append(bool(value))
	return result

func set_thief_encounter_type_flags(encounter: ThiefEncounterDefinition, flags: Array[bool]) -> bool:
	if encounter == null or flags.size() != 10:
		return false
	_thief_encounter_type_flags[str(encounter.id)] = flags.duplicate()
	return true

func set_scenario_program_override(source_program_id: String, target_program_id: String) -> bool:
	if source_program_id.is_empty() or target_program_id.is_empty():
		return false
	_scenario_program_overrides[source_program_id] = target_program_id
	return true

func shop_quantity(shop: ShopDefinition, stock_index: int) -> int:
	var key := "%s:%d" % [shop.id, stock_index]
	return int(_shop_overrides.get(key, shop.quantity(stock_index)))

func set_shop_quantity(shop: ShopDefinition, stock_index: int, quantity: int) -> bool:
	if shop == null or stock_index < 0 or stock_index >= shop.item_ids().size():
		return false
	_shop_overrides["%s:%d" % [shop.id, stock_index]] = clampi(quantity, 0, 32_767)
	return true

