func _read_envelope(path: String) -> SaveEnvelope:
	if not FileAccess.file_exists(path):
		return null
	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		return null
	var parser := JSON.new()
	var parse_error := parser.parse(file.get_as_text())
	file.close()
	if parse_error != OK:
		return null
	return SaveEnvelope.from_data(parser.data)

static func for_viewport(size: Vector2, scale_mode: String) -> UiLayoutProfile:
	var scale := UiLayoutProfile.scale_for(size, scale_mode)
	var effective_width := size.x / scale
	var art_scale := 2 if size.x >= 1600.0 and size.y >= 900.0 and scale_mode in [PresentationSettings.UI_SCALE_AUTO, PresentationSettings.UI_SCALE_150] else 1
	if effective_width < 960.0:
		return UiLayoutProfile.new(COMPACT, scale, 208.0 * scale, 156.0 * scale, 208.0 * scale, 1)
	if effective_width < 1280.0:
		return UiLayoutProfile.new(STANDARD, scale, 256.0 * scale, 176.0 * scale, 256.0 * scale, art_scale)
	return UiLayoutProfile.new(WIDE, scale, 288.0 * scale, 190.0 * scale, 288.0 * scale, art_scale)

static func from_data(data: Variant) -> PresentationSettings:
	if not data is Dictionary:
		return null
	var schema_value: Variant = data.get("schemaVersion")
	if not schema_value is int and not schema_value is float:
		return null
	var schema_version := int(schema_value)
	if float(schema_version) != float(schema_value):
		return null
	if data.get("kind") != "realmz2.presentation-settings" or schema_version not in [1, 2, SCHEMA_VERSION]:
		return null
	if not data.get("masterVolume") is float or not data.get("topologyDebug") is bool or not data.get("textScale") is float or not data.get("reducedMotion") is bool:
		return null
	if schema_version >= 2 and not data.get("dungeon3d") is bool:
		return null
	if schema_version == SCHEMA_VERSION:
		if not data.get("uiScaleMode") is String or not data.get("windowMode") is String:
			return null
		if data["uiScaleMode"] not in [UI_SCALE_AUTO, UI_SCALE_100, UI_SCALE_125, UI_SCALE_150]:
			return null
		if data["windowMode"] not in [WINDOWED, BORDERLESS_FULLSCREEN]:
			return null
	var volume: float = data["masterVolume"]
	var scale: float = data["textScale"]
	if volume < 0.0 or volume > 1.0 or scale < 0.8 or scale > 1.5:
		return null
	var settings := PresentationSettings.new()
	settings.master_volume = volume
	settings.topology_debug = data["topologyDebug"]
	settings.text_scale = scale
	settings.reduced_motion = data["reducedMotion"]
	settings.dungeon_3d = bool(data.get("dungeon3d", false))
	settings.ui_scale_mode = String(data.get("uiScaleMode", UI_SCALE_AUTO))
	settings.window_mode = String(data.get("windowMode", WINDOWED))
	return settings

func load_settings() -> PresentationSettings:
	last_error = ""
	if not FileAccess.file_exists(settings_path):
		return PresentationSettings.new()
	var text := FileAccess.get_file_as_string(settings_path)
	var parsed: Variant = JSON.parse_string(text)
	var settings := PresentationSettings.from_data(parsed)
	if settings == null:
		last_error = "Presentation settings are malformed; defaults were restored."
		return PresentationSettings.new()
	return settings

func save_settings(settings: PresentationSettings) -> bool:
	last_error = ""
	if settings == null:
		last_error = "Presentation settings are missing."
		return false
	var directory := settings_path.get_base_dir()
	if not directory.is_empty() and DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path(directory)) != OK:
		last_error = "Could not create the presentation settings directory."
		return false
	var temporary_path := settings_path + ".tmp"
	var file := FileAccess.open(temporary_path, FileAccess.WRITE)
	if file == null:
		last_error = "Could not open the temporary presentation settings file."
		return false
	file.store_string(CanonicalJson.encode(settings.to_data()))
	file.flush()
	file.close()
	var readback := PresentationSettings.from_data(JSON.parse_string(FileAccess.get_file_as_string(temporary_path)))
	if readback == null:
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		last_error = "Presentation settings failed readback validation."
		return false
	if FileAccess.file_exists(settings_path) and DirAccess.remove_absolute(ProjectSettings.globalize_path(settings_path)) != OK:
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		last_error = "Could not replace the previous presentation settings."
		return false
	if DirAccess.rename_absolute(ProjectSettings.globalize_path(temporary_path), ProjectSettings.globalize_path(settings_path)) != OK:
		last_error = "Could not commit presentation settings."
		return false
	return true

func present_media_events(events: Array[DomainEvent], media: PackageMediaCatalog) -> void:
	set_package_media(media)
	if media == null:
		return
	for event: DomainEvent in events:
		if event.kind != &"picture_requested":
			continue
		var picture_id := int(event.payload.get("pictureId", 0))
		var asset := media.asset_by_resource("PICT", picture_id)
		if asset == null:
			_picture.texture = null
			_picture_caption.text = "PICT %d unavailable" % picture_id
			_picture_stage.visible = true
			continue
		var image := _decode_image(asset, media.read_bytes(asset))
		_picture.texture = ImageTexture.create_from_image(image) if image != null else null
		_picture.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
		_picture_caption.text = asset.label
		_picture_stage.visible = true

func present_step(step: SessionStep) -> void:
	if step == null:
		return
	if step.state == SessionStep.State.FAILED:
		set_status("Action failed • %s" % step.error_message, true)
		_append_narrative("Action failed: %s" % step.error_message)
		return
	_picture_stage.visible = false
	for event: DomainEvent in step.events:
		_present_event(event)

func show_campaign_selection() -> void:
	_router.show_campaign_selection()
	_set_play_regions_visible(false)

func _fill_menu(menu: MenuButton, entries: Array[Dictionary]) -> void:
	var popup := menu.get_popup()
	popup.clear()
	var actions: Dictionary = {}
	for index: int in entries.size():
		var entry := entries[index]
		popup.add_item(String(entry["label"]), index)
		actions[index] = entry
		var reason := String(entry.get("disabled_reason", ""))
		if not reason.is_empty():
			popup.set_item_disabled(index, true)
			popup.set_item_tooltip(index, reason)
	_menu_actions[menu.get_instance_id()] = actions
	if not _menus_connected.has(menu.get_instance_id()):
		popup.id_pressed.connect(_on_menu_item_pressed.bind(menu))
		_menus_connected[menu.get_instance_id()] = true

func _on_menu_item_pressed(item_id: int, menu: MenuButton) -> void:
	var entry: Dictionary = _menu_actions.get(menu.get_instance_id(), {}).get(item_id, {})
	if entry.is_empty():
		return
	if entry.has("route"):
		_router.open_screen(StringName(entry["route"]))
	elif entry.has("command"):
		_activate_command(StringName(entry["command"]))
	elif entry.has("system"):
		_on_system_action_requested(StringName(entry["system"]), null)

func _rebuild_command_deck() -> void:
	if not is_node_ready() or _profile == null:
		return
	for child: Node in _command_grid.get_children():
		_command_grid.remove_child(child)
		child.queue_free()
	_simulation_buttons.clear()
	var context := &"encounter" if _current_view != null and _current_view.pending_interaction != null else _router.current_screen()
	for definition: Dictionary in ClassicCommandCatalog.for_context(context):
		var asset_id := StringName(definition.get("asset_id", &""))
		var button: BaseButton
		if not asset_id.is_empty() and ClassicUiAssetCatalog.texture(asset_id) != null:
			var bitmap := ClassicBitmapButton.new()
			bitmap.configure(definition, _profile.bitmap_scale)
			bitmap.command_requested.connect(_activate_command)
			button = bitmap
		else:
			var text_button := Button.new()
			text_button.text = String(definition.get("label", "Command"))
			text_button.custom_minimum_size = Vector2(54.0, 54.0)
			text_button.tooltip_text = String(definition.get("tooltip", ""))
			text_button.pressed.connect(_activate_command.bind(StringName(definition["id"])))
			button = text_button
		button.set_meta("focus_key", "command:%s" % definition["id"])
		_command_grid.add_child(button)
		_simulation_buttons[StringName(definition["id"])] = button
	_update_command_availability()

func _update_command_availability() -> void:
	for command_id: StringName in _simulation_buttons:
		var button := _simulation_buttons[command_id] as BaseButton
		var definition := ClassicCommandCatalog.command(command_id)
		var availability_id := StringName(definition.get("availability", &""))
		var reason := ""
		if _current_view == null or not _current_view.session_started:
			reason = "Begin a campaign first."
		elif _current_view.pending_interaction != null and not String(command_id).begins_with("encounter_"):
			reason = "Resolve the current interaction first."
		elif String(command_id).begins_with("encounter_"):
			reason = "Choose from the active encounter response controls."
		elif not availability_id.is_empty():
			reason = _availability_reason(availability_id)
		button.disabled = not reason.is_empty()
		button.tooltip_text = reason if not reason.is_empty() else String(definition.get("tooltip", ""))
		button.queue_redraw()

func _on_screen_changed(screen_id: StringName) -> void:
	var play_regions_visible := _current_view != null and _current_view.session_started and not _router.full_stage_overlay_visible()
	_set_play_regions_visible(play_regions_visible)
	set_status(String(screen_id).replace("_", " ").capitalize())
	_rebuild_command_deck()
	route_changed.emit(screen_id)

