		start_requested.emit(path, int(_seed.value))

func _render_characters() -> void:
	if _view.party_members.is_empty():
		_add_empty_state("No characters", "Begin a campaign or import an eligible vault character.")
		return
	for character: CharacterView in _view.party_members:
		var detail := "HP %d/%d • SP %d/%d • Armor %d • Move %d/%d\nBrawn %d • Knowledge %d • Judgment %d • Agility %d • Vitality %d • Luck %d\nTo hit %d • Dodge %d • Missile %d • Hand to hand %d • Magic resistance %d\nLoad %d/%d • Experience %d" % [character.current_health, character.maximum_health, character.spell_points, character.maximum_spell_points, character.armor, character.movement, character.maximum_movement, character.brawn, character.knowledge, character.judgment, character.agility, character.vitality, character.luck, character.to_hit, character.dodge, character.missile, character.hand_to_hand, character.magic_resistance, character.carried_load, character.maximum_load, character.experience]
		_add_card(character.name, "Level %d • %s / %s" % [character.level, character.race_name, character.caste_name], detail)
		var conditions: Array[String] = []
		for index: int in character.condition_values.size():
			if character.condition_values[index] != 0:
				conditions.append("%d:%d" % [index, character.condition_values[index]])
		_add_label(_body, "Conditions: %s" % ["None" if conditions.is_empty() else ", ".join(conditions)], MUTED, 13)

