	if not definition.is_empty():
		return String(definition["label"])
	return "Realmz"

func _assign_focus_keys(parent: Node, next_index: int = 0) -> int:
	for child: Node in parent.get_children():
		if child is Control and (child as Control).focus_mode != Control.FOCUS_NONE:
			if not child.has_meta("focus_key"):
				child.set_meta("focus_key", "%s:%d" % [_screen_id, next_index])
			next_index += 1
		next_index = _assign_focus_keys(child, next_index)
	return next_index

func _store_focus() -> void:
	var owner := get_viewport().gui_get_focus_owner()
	if owner != null and is_ancestor_of(owner) and owner.has_meta("focus_key"):
		_focus_keys[_screen_id] = String(owner.get_meta("focus_key"))

func _restore_focus() -> void:
	var wanted := String(_focus_keys.get(_screen_id, ""))
	if not wanted.is_empty():
		var focus_match := _find_focus_key(_body, wanted)
		if focus_match != null:
			focus_match.grab_focus()
			return
	_focus_first(_body)

func _find_focus_key(parent: Node, key: String) -> Control:
	for child: Node in parent.get_children():
		if child is Control and child.has_meta("focus_key") and String(child.get_meta("focus_key")) == key:
			return child
		var nested := _find_focus_key(child, key)
		if nested != null:
			return nested
	return null

func _focus_first(parent: Node) -> void:
	for child: Node in parent.get_children():
		if child is Control:
			var control := child as Control
			if control.visible and control.focus_mode != Control.FOCUS_NONE and not (control is BaseButton and (control as BaseButton).disabled):
				control.grab_focus()
				return
		_focus_first(child)
		var owner := get_viewport().gui_get_focus_owner()
		if owner != null and parent.is_ancestor_of(owner):
			return

func _campaign_precedes(left: PackageDiscoveryResult, right: PackageDiscoveryResult) -> bool:
	if left.ready != right.ready:
		return left.ready
	return _display_name(left).naturalnocasecmp_to(_display_name(right)) < 0

func _render_combat() -> void:
	if _view.combat_view == null:
		_add_empty_state("No battle is active", "Battle information appears here when combat begins. Tactical movement remains unavailable until the session exposes positions.")
		return
	var combat := _view.combat_view
	_add_card("Battle %s" % combat.battle_id, "Round %d • Active %s" % [combat.round_number, combat.active_actor_id], "Outcome: %s" % ["In progress" if combat.outcome == &"" else String(combat.outcome)])
	_add_section_heading("Turn order", " → ".join(combat.turn_order))
	for monster: MonsterView in combat.monsters:
		_add_content_card(monster.icon_resource_type, monster.icon_id, monster.name, "Enemy" if monster.traitor else "Ally", "HP %d/%d" % [monster.current_health, monster.maximum_health])
	var legal := HBoxContainer.new()
	for action: StringName in combat.legal_actions:
		var button := Button.new()
		button.text = String(action).capitalize()
		_apply_availability(button, &"choose_combat_action")
		legal.add_child(button)
	_body.add_child(legal)
	_add_disabled_action(_body, "Tactical movement unavailable — no combat positions are exposed", &"combat_move")

func _label(text: String, color: Color = Color.WHITE, size: int = 15) -> Label:
	var label := Label.new()
	label.text = text
	label.add_theme_color_override("font_color", color)
	label.add_theme_font_size_override("font_size", int(round(float(size) * _settings.text_scale)))
	return label

static func texture(asset_id: StringName) -> Texture2D:
	var record := ClassicUiAssetCatalog.definition(asset_id)
	if record.is_empty():
		return null
	return load(String(record.get("path", ""))) as Texture2D

static func native_size(asset_id: StringName) -> Vector2i:
	var record := ClassicUiAssetCatalog.definition(asset_id)
	return Vector2i(int(record.get("native_width", 0)), int(record.get("native_height", 0)))

static func _ensure_loaded() -> void:
	if not _definitions.is_empty():
		return
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(MANIFEST_PATH))
	if not parsed is Dictionary:
		push_error("Classic UI asset manifest is unavailable or malformed.")
		return
	for value: Variant in (parsed as Dictionary).get("assets", []):
		if value is Dictionary:
			var record := value as Dictionary
			_definitions[String(record.get("id", ""))] = record

static func from_map_view(map_view: MapView) -> DungeonGeometryProjection:
	if map_view == null or map_view.level_type != &"dungeon":
		return null
	var projection := DungeonGeometryProjection.new()
	projection.map_id = map_view.map_id
	projection.map_name = map_view.map_name
	projection.party_coordinate = map_view.party_coordinate
	for cell: MapCellView in map_view.cells():
		if not cell.visible:
			continue
		var cell_projection := CellProjection.new(cell)
		projection._cells.append(cell_projection)
		projection._cells_by_coordinate[cell.coordinate] = cell_projection
		for direction: StringName in DIRECTIONS:
			var edge := EdgeProjection.new(cell.coordinate, direction, cell.edge_kind(direction), cell.edge_is_passable(direction))
			projection._edges.append(edge)
			projection._edges_by_direction[_directed_edge_key(cell.coordinate, direction)] = edge
	return projection

static func definition(asset_id: StringName) -> Dictionary:
	_ensure_loaded()
	return _definitions.get(String(asset_id), {})

func set_enabled(enabled: bool) -> void:
	_enabled = enabled
	_update_visibility()

func present(game_view: GameView) -> void:
	_projection = null
	if game_view != null and game_view.session_started:
		_projection = DungeonGeometryProjection.from_map_view(game_view.map_view)
	_rebuild_geometry()
	_update_visibility()

func _render_journal() -> void:
	_add_section_heading("Acquired maps", "%d available" % _view.party_summary.acquired_map_ids.size() if _view.party_summary != null else "0 available")
	if _view.party_summary == null or _view.party_summary.acquired_map_ids.is_empty():
		_add_empty_state("No acquired maps", "Maps appear only after the session records their acquisition.")
	else:
		for map_id: String in _view.party_summary.acquired_map_ids:
			_add_card(map_id, "Acquired map", "Map viewing is not implemented in the current gameplay slice.")
	_add_section_heading("Journal entries", "%d entries" % _view.journal_entries.size())
	if _view.journal_entries.is_empty():
		_add_empty_state("The journal is empty", "No journal records were supplied by the current session.")
	else:
		for entry: JournalEntryView in _view.journal_entries:
			_add_card(entry.title, "Day %d • %s" % [entry.day, entry.map_id], entry.text)
	_add_disabled_action(_body, "Open Classic journal", &"open_journal")
	_add_disabled_action(_body, "Open acquired maps", &"open_maps")

func _rebuild_geometry() -> void:
	if _geometry_root == null:
		return
	for child: Node in _geometry_root.get_children():
		_geometry_root.remove_child(child)
		child.queue_free()
	if _projection == null:
		return
	for cell: DungeonGeometryProjection.CellProjection in _projection.cells():
		if cell.passable:
			_add_box("Floor_%d_%d" % [cell.coordinate.x, cell.coordinate.y], Vector3(cell_span * 0.94, 0.10, cell_span * 0.94), _cell_center(cell.coordinate) + Vector3(0.0, -0.08, 0.0), _floor_material)
		if cell.features.has(&"column"):
			_add_column(cell.coordinate)
		if cell.features.has(&"stairs"):
			_add_stairs(cell.coordinate)
	var built_edges: Dictionary = {}
	for edge: DungeonGeometryProjection.EdgeProjection in _projection.edges():
		if edge.kind == &"open" or built_edges.has(edge.canonical_key):
			continue
		built_edges[edge.canonical_key] = true
		if edge.kind in [&"door", &"archway"]:
			_add_door_frame(edge)
		else:
			_add_wall(edge, _secret_material if edge.kind == &"secret" else _wall_material)
	_add_party_marker()
	var target := _cell_center(_projection.party_coordinate) + Vector3(0.0, 0.65, 0.0)
	_camera.position = target + Vector3(5.6, 7.5, 7.8)
	_camera.look_at(target, Vector3.UP)

func _add_wall(edge: DungeonGeometryProjection.EdgeProjection, surface_material: Material) -> void:
	var horizontal := edge.direction in [&"north", &"south"]
	var box_dimensions := Vector3(cell_span, wall_height, wall_thickness) if horizontal else Vector3(wall_thickness, wall_height, cell_span)
	_add_box("Edge_%s" % edge.canonical_key, box_dimensions, _edge_center(edge.coordinate, edge.direction) + Vector3(0.0, wall_height * 0.5, 0.0), surface_material)

func _add_door_frame(edge: DungeonGeometryProjection.EdgeProjection) -> void:
	var horizontal := edge.direction in [&"north", &"south"]
	var center := _edge_center(edge.coordinate, edge.direction)
	var post_offset := cell_span * 0.37
	var post_size := Vector3(wall_thickness * 1.35, wall_height * 0.82, wall_thickness * 1.35)
	var left_offset := Vector3(post_offset, 0.0, 0.0) if horizontal else Vector3(0.0, 0.0, post_offset)
	_add_box("DoorPostA_%s" % edge.canonical_key, post_size, center - left_offset + Vector3(0.0, post_size.y * 0.5, 0.0), _door_material)
	_add_box("DoorPostB_%s" % edge.canonical_key, post_size, center + left_offset + Vector3(0.0, post_size.y * 0.5, 0.0), _door_material)
	var lintel_size := Vector3(cell_span, wall_thickness * 1.5, wall_thickness * 1.5) if horizontal else Vector3(wall_thickness * 1.5, wall_thickness * 1.5, cell_span)
	_add_box("DoorLintel_%s" % edge.canonical_key, lintel_size, center + Vector3(0.0, wall_height * 0.84, 0.0), _door_material)
	if edge.kind == &"door" and not edge.passable:
		var panel_size := Vector3(cell_span * 0.62, wall_height * 0.70, wall_thickness * 0.65) if horizontal else Vector3(wall_thickness * 0.65, wall_height * 0.70, cell_span * 0.62)
		_add_box("DoorPanel_%s" % edge.canonical_key, panel_size, center + Vector3(0.0, panel_size.y * 0.5, 0.0), _door_material)

func _add_stairs(coordinate: Vector2i) -> void:
	for index: int in range(3):
		var height := 0.12 * float(index + 1)
		_add_box("Stair_%d_%d_%d" % [coordinate.x, coordinate.y, index], Vector3(cell_span * 0.62, height, cell_span * 0.20), _cell_center(coordinate) + Vector3(0.0, height * 0.5, (float(index) - 1.0) * cell_span * 0.20), _feature_material)

func _add_box(node_name: String, box_size: Vector3, box_position: Vector3, surface_material: Material) -> void:
	var mesh := BoxMesh.new()
	mesh.size = box_size
	var instance := MeshInstance3D.new()
	instance.name = node_name.validate_node_name()
	instance.mesh = mesh
	instance.material_override = surface_material
	instance.position = box_position
	_geometry_root.add_child(instance)

func _render_services() -> void:
	if _view.services.is_empty():
		_add_empty_state("No active service", "Shops, temples, banks, storage, and treasure open here only when the session supplies a typed service interaction.")
		for title: String in ["Shop", "Temple", "Bank", "Storage", "Treasure"]:
			_add_card(title, "Unavailable at this location", "No service facts were supplied; Realmz 2 does not infer availability from the map or scenario name.")
		return
	for service: ServiceView in _view.services:
		_add_card(service.title, String(service.service_kind).replace("_", " ").capitalize(), "Available actions: %s" % [", ".join(service.actions)])
		for action: StringName in service.actions:
			var button := Button.new()
			button.text = String(action).capitalize()
			var reason := String(service.disabled_reasons.get(action, ""))
			button.disabled = not reason.is_empty()
			button.tooltip_text = reason
			_body.add_child(button)

func build(request: InteractionRequest) -> void:
	add_hint("Round %d" % int(request.payload.get("round", 1)))
	var actor_id := String(request.payload.get("actorId", ""))
	var targets: Variant = request.payload.get("targets", [])
	if targets is Array:
		for target: Variant in targets:
			if target is Dictionary:
				add_response("Attack %s • HP %d/%d" % [target.get("name", "Enemy"), int(target.get("currentHealth", 0)), int(target.get("maximumHealth", 0))], {"actorId": actor_id, "action": "attack", "targetId": String(target.get("id", ""))})
	add_response("Defend", {"actorId": actor_id, "action": "defend", "targetId": ""})
	add_response("Retreat", {"actorId": actor_id, "action": "retreat", "targetId": ""})
	add_response("Tactical movement unavailable", {}, false, "Combat positions are not exposed by the session yet.")

func _add_word_action(entry: Dictionary) -> void:
	var word := LineEdit.new()
	word.placeholder_text = "Speak a word"
	add_child(word)
	var button := _bitmap_button(&"encounter.speak", String(entry.get("label", "Speak")))
	button.command_requested.connect(func(_command_id: StringName) -> void: payload_submitted.emit({"action": "word", "word": word.text}))
	add_child(button)

func _add_catalog_action(request: InteractionRequest, action: String, id_field: String, values_key: String, label: String) -> void:
	var catalog := OptionButton.new()
	var values: Variant = request.payload.get(values_key, [])
	if values is Array:
		for entry: Variant in values:
			if entry is Dictionary and entry.has(id_field):
				catalog.add_item(String(entry.get("name", "Option")))
				catalog.set_item_metadata(catalog.item_count - 1, int(entry[id_field]))
	add_child(catalog)
	var asset_id := &"encounter.items" if action == "item" else &"command.spells"
	var button := _bitmap_button(asset_id, label)
	button.disabled = catalog.item_count == 0
	button.tooltip_text = "No eligible options were supplied." if button.disabled else ""
	button.command_requested.connect(func(_command_id: StringName) -> void:
		if catalog.item_count > 0:
			var payload := {"action": action}
			payload[id_field] = int(catalog.get_selected_metadata())
			payload_submitted.emit(payload)
	)
	add_child(button)

func _add_thief_action(request: InteractionRequest, entry: Dictionary) -> void:
	var picker := character_option(request.payload.get("characters", []))
	add_child(picker)
	var button := _bitmap_button(&"encounter.skills", String(entry.get("label", "Thief action")))
	button.disabled = picker.item_count == 0
	button.tooltip_text = "No eligible character was supplied." if button.disabled else ""
	button.command_requested.connect(func(_command_id: StringName) -> void:
		if picker.item_count > 0:
			payload_submitted.emit({"action": "thief", "actionIndex": int(entry.get("actionIndex", 0)), "characterId": String(picker.get_selected_metadata())})
	)
	add_child(button)

func _add_bitmap_response(asset_id: StringName, label: String, payload: Dictionary) -> void:
	var row := HBoxContainer.new()
	var button := _bitmap_button(asset_id, label)
	button.command_requested.connect(func(_command_id: StringName) -> void: payload_submitted.emit(payload))
	row.add_child(button)
	var text := Label.new()
	text.text = label
	text.vertical_alignment = VERTICAL_ALIGNMENT_CENTER
	text.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	text.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	row.add_child(text)
	add_child(row)

func _bitmap_button(asset_id: StringName, label: String) -> ClassicBitmapButton:
	var button := ClassicBitmapButton.new()
	button.configure({"id": asset_id, "asset_id": asset_id, "tooltip": label, "accelerator": ""}, 1)
	return button

func character_option(value: Variant) -> OptionButton:
	var picker := OptionButton.new()
	picker.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	if value is Array:
		for character: Variant in value:
			if character is Dictionary:
				picker.add_item(String(character.get("name", "Character")))
				picker.set_item_metadata(picker.item_count - 1, String(character.get("id", "")))
	return picker

func build(request: InteractionRequest) -> void:
	if request.kind == &"character_selection":
		_build_character_selection(request)
	else:
		_build_ally_selection(request)

func _build_character_selection(request: InteractionRequest) -> void:
	var required := int(request.payload.get("count", 1))
	add_hint("Choose %d character%s." % [required, "" if required == 1 else "s"])
	var eligible: Variant = request.payload.get("eligible", [])
	if eligible is Array:
		for entry: Variant in eligible:
			if entry is Dictionary:
				_add_character_check(entry, false, false)
	var submit := Button.new()
	submit.text = "Choose"
	submit.pressed.connect(_submit_characters.bind(required))
	add_child(submit)

func _build_ally_selection(request: InteractionRequest) -> void:
	var maximum := int(request.payload.get("maximum", 0))
	var selected: Variant = request.payload.get("selectedIds", [])
	add_hint("Choose up to %d surviving allies. Required allies stay selected." % maximum)
	var candidates: Variant = request.payload.get("candidates", [])
	if candidates is Array:
		for entry: Variant in candidates:
			if not entry is Dictionary:
				continue
			var ally_id := String(entry.get("id", ""))
			var required := bool(entry.get("required", false))
			_add_character_check(entry, required or selected is Array and selected.has(ally_id), required)
	var submit := Button.new()
	submit.text = "Continue"
	submit.pressed.connect(_submit_allies.bind(maximum))
	add_child(submit)

func _submit_characters(required: int) -> void:
	var ids := _selected_ids()
	if ids.size() != required:
		add_hint("Choose exactly %d character%s." % [required, "" if required == 1 else "s"])
		return
	payload_submitted.emit({"characterIds": ids})

func _selected_ids() -> Array[String]:
	var ids: Array[String] = []
	for check: CheckButton in _checks:
		if check.button_pressed:
			ids.append(String(check.get_meta("character_id")))
	return ids

static func _prompt_for(request: InteractionRequest, classic_text_context: String) -> String:
	var explicit_prompt := String(request.payload.get("prompt", "")).strip_edges()
	if not explicit_prompt.is_empty():
		return explicit_prompt
	if request.kind == InteractionRequest.YES_NO:
		var authored_context := classic_text_context.strip_edges()
		if not authored_context.is_empty():
			return authored_context
		return "Choose Yes or No to continue."
	return _title_for_kind(request.kind)

func build(request: InteractionRequest) -> void:
	match request.kind:
		&"encounter_choice", &"scenario_choice":
			var options: Variant = request.payload.get("options", [])
			if options is Array:
				for index: int in options.size():
					var option: Variant = options[index]
					if option is Dictionary:
						add_response(String(option.get("label", "Option %d" % (index + 1))), {"index": index})
			if request.kind == &"encounter_choice" and bool(request.payload.get("canBackOut", false)):
				add_response("Back out", {"cancelled": true})
		&"yes_no":
			add_response(String(request.payload.get("yesLabel", "Yes")), {"accepted": true})
			add_response(String(request.payload.get("noLabel", "No")), {"accepted": false})
		&"acknowledge":
			add_response("Continue", {})

func set_text_scale(value: float) -> void:
	_heading.add_theme_font_size_override("font_size", int(round(18.0 * value)))
	_prompt.add_theme_font_size_override("font_size", int(round(20.0 * value)))

func _component_for(kind: StringName) -> InteractionComponent:
	match kind:
		&"acknowledge", &"yes_no", &"encounter_choice", &"scenario_choice":
			return TextChoiceInteraction.new()
		&"character_selection", &"ally_selection":
			return SelectionInteraction.new()
		&"complex_encounter":
			return EncounterInteraction.new()
		&"shop_action":
			return ShopInteraction.new()
		&"temple_action":
			return TempleInteraction.new()
		&"bank_action":
			return BankInteraction.new()
		&"combat_action":
			return BattleInteraction.new()
	return null

func _submit_payload(payload: Dictionary) -> void:
	if _request == null:
		return
	var response := InteractionPresenter.response_for(_request, payload)
	_request = null
	visible = false
	response_submitted.emit(response)

static func response_for(request: InteractionRequest, payload: Dictionary) -> InteractionResponse:
	assert(request != null, "An interaction response requires its originating request")
	return InteractionResponse.new(request.request_id, request.kind, payload)

func _clear_options() -> void:
	_component = null
	for child: Node in _options.get_children():
		_options.remove_child(child)
		child.queue_free()

func _apply_classic_region() -> void:
	if not is_inside_tree():
		return
	set_anchors_preset(Control.PRESET_TOP_LEFT)
	if _passive_text or _request != null and _request.kind in [&"acknowledge", &"yes_no", &"encounter_choice", &"scenario_choice"]:
		position = _textbox_rect.position
		size = _textbox_rect.size
	else:
		var desired := Vector2(minf(700.0, _stage_rect.size.x - 20.0), minf(520.0, _stage_rect.size.y - 20.0))
		desired.x = maxf(300.0, desired.x)
		desired.y = maxf(260.0, desired.y)
		position = _stage_rect.position + (_stage_rect.size - desired) * 0.5
		size = desired

func _add_hint(text: String) -> void:
	var label := Label.new()
	label.text = text
	label.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	label.add_theme_color_override("font_color", Color("d5b45d"))
	_options.add_child(label)

func build(request: InteractionRequest) -> void:
	add_hint("Inflation %d%%" % int(request.payload.get("inflationPercent", 100)))
	var picker := character_option(request.payload.get("characters", []))
	add_child(picker)
	add_hint("Buy")
	var stock: Variant = request.payload.get("stock", [])
	if stock is Array:
		for entry: Variant in stock:
			if not entry is Dictionary:
				continue
			var available := int(entry.get("quantity", 0)) > 0 and picker.item_count > 0
			var payload := {"action": "buy", "stockIndex": int(entry.get("index", -1))}
			var button := Button.new()
			button.text = "%s • %d gold • %d left" % [entry.get("name", "Item"), int(entry.get("buyPrice", 0)), int(entry.get("quantity", 0))]
			button.disabled = not available
			button.tooltip_text = "No stock or eligible buyer." if not available else ""
			button.pressed.connect(func() -> void:
				if picker.item_count > 0:
					payload["characterId"] = String(picker.get_selected_metadata())
					payload_submitted.emit(payload)
			)
			add_child(button)
	add_hint("Sell")
	var characters: Variant = request.payload.get("characters", [])
	if characters is Array:
		for character: Variant in characters:
			if not character is Dictionary or not character.get("inventory", []) is Array:
				continue
			for item: Variant in character.get("inventory", []):
				if item is Dictionary:
					add_response("Sell %s (%s) • %d gold" % [item.get("name", "Item"), character.get("name", "Character"), int(item.get("sellPrice", 0))], {"action": "sell", "characterId": String(character.get("id", "")), "instanceId": String(item.get("instanceId", ""))})
	add_response("Leave shop", {"action": "leave"})

func _focus_first_control() -> void:
	var first := _first_focusable(_options)
	if first != null:
		first.grab_focus()

func _submit_allies(maximum: int) -> void:
	var ids := _selected_ids()
	if ids.size() > maximum:
		add_hint("Choose no more than %d allies." % maximum)
		return
	payload_submitted.emit({"selectedIds": ids})

func present(view: GameView, selected_character_id: String = "") -> void:
	_selected_character_id = selected_character_id
	_clear()
	if view == null or not view.session_started:
		_heading.text = "Party"
		_add_empty("No active party")
		return
	_heading.text = "Party • %d / 6" % view.party_members.size()
	for character: CharacterView in view.party_members:
		_add_character(character)
	for index: int in maxi(0, 6 - view.party_members.size()):
		_add_empty("Empty position %d" % (view.party_members.size() + index + 1))

func _on_step_committed(step: SessionStep) -> void:
	_present_current_view(false)
	_shell_presenter.present_step(step)
	_shell_presenter.present_media_events(step.events, _media)
	_audio_presenter.present_events(step.events, _media)
	var passive_classic_text := ""
	for event: DomainEvent in step.events:
		if event.kind == &"message_shown" and event.payload.has("classicClick") and not bool(event.payload.get("classicClick", false)):
			passive_classic_text = String(event.payload.get("text", ""))
	var game_view := _session_controller.view()
	_present_interaction(game_view)
	if game_view.pending_interaction == null and not passive_classic_text.is_empty():
		_interaction_presenter.present_passive_classic_text(passive_classic_text)

func set_active_route(route_id: StringName) -> void:
	_active_route = route_id
	_present_current_view()

func set_play_stage_visible(visible: bool) -> void:
	_play_stage_visible = visible
	if _session_controller != null:
		_update_spatial_visibility(_session_controller.view())

func set_dungeon_3d_enabled(enabled: bool) -> void:
	_dungeon_presenter.set_enabled(enabled)
	_present_current_view()

func _present_current_view(include_interaction: bool = true) -> void:
	var game_view := _session_controller.view()
	_map_presenter.present(game_view)
	_dungeon_presenter.present(game_view)
	_shell_presenter.present(game_view)
	_update_spatial_visibility(game_view)
	if include_interaction:
		_present_interaction(game_view)

func _update_spatial_visibility(game_view: GameView) -> void:
	var exploration_visible := should_show_spatial_stage(_active_route, game_view, _play_stage_visible)
	_map_presenter.visible = exploration_visible and not _dungeon_presenter.is_active()
	_dungeon_presenter.visible = exploration_visible and _dungeon_presenter.is_active()

static func _first_focusable(parent: Node) -> Control:
	for child: Node in parent.get_children():
		if child is Control and (child as Control).visible and (child as Control).focus_mode != Control.FOCUS_NONE and not (child is BaseButton and (child as BaseButton).disabled):
			return child as Control
