func _configure_shop(action: ClassicActionDefinition, request_id: String) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 73 requires a five-value Extra Code row.")
	var shop := _content.shop_by_classic_id(absi(action.extra_code[0]))
	if shop == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_shop", "Classic opcode 73 references unavailable shop %d." % action.extra_code[0])
	var accept_ranges: Array[int] = [action.extra_code[1], action.extra_code[2], action.extra_code[3], action.extra_code[4]]
	if not _game_state.set_active_shop(shop.id, accept_ranges):
		return ScenarioRuntimeOperationResult.failed(&"invalid_shop_configuration", "Classic opcode 73 shop restrictions are invalid.")
	if action.extra_code[0] < 0:
		return _request_shop(action.extra_code[0], request_id, accept_ranges)
	return ScenarioRuntimeOperationResult.completed(shop.id, [DomainEvent.new(&"shop_available", {"shopId": shop.id, "acceptRanges": accept_ranges})])

static func _shop_accepts_item(item: ItemDefinition, accept_ranges: Array[int]) -> bool:
	if item == null or accept_ranges.is_empty():
		return accept_ranges.is_empty()
	if accept_ranges.size() != 4:
		return false
	var first := accept_ranges[0] <= item.classic_id and item.classic_id <= accept_ranges[1]
	var second := accept_ranges[2] <= item.classic_id and item.classic_id <= accept_ranges[3]
	return first or second

func _mutate_shop(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 4:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 51 requires a five-value Extra Code row.")
	var shop := _content.shop_by_classic_id(absi(action.extra_code[0]))
	if shop == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_shop", "Classic shop mutation references unavailable shop %d." % action.extra_code[0])
	var inflation := maxi(0, _game_state.shop_inflation(shop) + action.extra_code[1])
	_game_state.set_shop_inflation(shop, inflation)
	var stock_index := -1
	if action.extra_code[2] != 0:
		var item := _content.item_by_classic_id(absi(action.extra_code[2]))
		if item == null:
			return ScenarioRuntimeOperationResult.failed(&"unknown_item", "Classic shop mutation references unavailable item %d." % action.extra_code[2])
		stock_index = shop.item_ids().find(item.id)
		if stock_index < 0:
			return ScenarioRuntimeOperationResult.failed(&"shop_item_unavailable", "Classic shop mutation item is not stocked by the shop.")
		_game_state.set_shop_quantity(shop, stock_index, _game_state.shop_quantity(shop, stock_index) + action.extra_code[3])
	return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"shop_changed", {"shopId": shop.id, "inflationPercent": inflation, "stockIndex": stock_index, "quantity": _game_state.shop_quantity(shop, stock_index) if stock_index >= 0 else 0})])

func _shop_item_price(item: ItemDefinition, shop: ShopDefinition, selling: bool) -> int:
	var multiplier := _game_state.shop_inflation(shop)
	if selling:
		multiplier = mini(multiplier, 100)
	return mini(32_000, int(float(absi(item.cost) * multiplier) / 100.0))

func _temple_request(cost_percent: int, request_id: String) -> InteractionRequest:
	var characters: Array[Dictionary] = []
	for character: CharacterState in _game_state.party.characters():
		characters.append({"id": character.id, "name": character.name, "currentHealth": character.current_health, "maximumHealth": character.maximum_health})
	return InteractionRequest.new(request_id, &"temple_action", {"costPercent": cost_percent, "characters": characters, "actions": ["heal", "leave"]})

func _resume_temple(continuation: Dictionary, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	if response.kind != &"temple_action" or not response.payload.get("action") is String:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Temple response requires an action.")
	if response.payload["action"] == "leave":
		return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"temple_closed")])
	if response.payload["action"] != "heal" or not response.payload.get("characterId") is String:
		return ScenarioRuntimeOperationResult.failed(&"unknown_temple_action", "Temple action is unavailable.")
	var character := _game_state.party.character_by_id(response.payload["characterId"])
	if character == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_character", "Temple healing target is unavailable.")
	var missing := maxi(0, character.maximum_health - character.current_health)
	var cost := maxi(1, int(float(missing * absi(int(continuation.get("costPercent", 100)))) / 100.0)) if missing > 0 else 0
	if cost > 0 and not _rules.economy.take(_game_state.party, cost, WealthState.Kind.GOLD):
		return ScenarioRuntimeOperationResult.failed(&"insufficient_gold", "The party cannot afford temple healing.")
	character.current_health = character.maximum_health
	return ScenarioRuntimeOperationResult.waiting(_temple_request(int(continuation.get("costPercent", 100)), request_id), continuation, [DomainEvent.new(&"temple_healing_applied", {"characterId": character.id, "cost": cost, "health": character.current_health})])

func _resume_banking(continuation: Dictionary, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	if response.kind != &"bank_action" or not response.payload.get("action") is String:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Bank response requires an action.")
	var action: String = response.payload["action"]
	if action == "leave":
		return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"bank_closed")])
	if not _whole_number(response.payload.get("amount")) or int(response.payload["amount"]) < 0:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Bank transfer requires a non-negative amount.")
	var amount := int(response.payload["amount"])
	match action:
		"deposit":
			if amount > _game_state.party.pooled_wealth.gold:
				return ScenarioRuntimeOperationResult.failed(&"insufficient_gold", "The party cannot deposit more gold than it carries.")
			_game_state.party.pooled_wealth.gold -= amount
			_game_state.party.banked_wealth.gold += amount
		"withdraw":
			if amount > _game_state.party.banked_wealth.gold:
				return ScenarioRuntimeOperationResult.failed(&"insufficient_banked_gold", "The party cannot withdraw more gold than it banked.")
			_game_state.party.banked_wealth.gold -= amount
			_game_state.party.pooled_wealth.gold += amount
		_:
			return ScenarioRuntimeOperationResult.failed(&"unknown_bank_action", "Bank action '%s' is unavailable." % action)
	return ScenarioRuntimeOperationResult.waiting(_bank_request(request_id), continuation, [DomainEvent.new(&"bank_transfer_completed", {"action": action, "amount": amount})])

func _character_has_classic_item(character: CharacterState, classic_item_id: int, equipped_only: bool) -> bool:
	var definition := _content.item_by_classic_id(classic_item_id)
	if definition == null:
		return false
	for instance: ItemInstance in character.inventory():
		if instance.definition_id == definition.id and (not equipped_only or instance.equipped):
			return true
	return false

func _init(programs: Array[ScenarioProgramDefinition], actions: Array[ScenarioActionDefinition]) -> void:
	for program: ScenarioProgramDefinition in programs:
		_programs[program.id] = program
	for action: ScenarioActionDefinition in actions:
		_actions[action.id] = action

func _recalculate_party_loads() -> void:
	for character: CharacterState in _game_state.party.characters():
		var total := character.money.gold + character.money.gems + character.money.jewelry * 15
		for instance: ItemInstance in character.inventory():
			var definition := _content.item_by_id(instance.definition_id)
			if definition != null:
				total += definition.instance_weight(instance.charges)
		character.carried_load = maxi(0, total)

func toggle_equipment_storage(capture: bool) -> ScenarioRuntimeOperationResult:
	if capture:
		_rules.economy.pool_party_wealth(_game_state.party)
		var changed := _game_state.party.capture_equipment()
		if changed:
			for character: CharacterState in _game_state.party.characters():
				character.carried_load = 0
		return ScenarioRuntimeOperationResult.completed(changed, [DomainEvent.new(&"equipment_stored", {"changed": changed, "source": "classic"})])
	var restored := _game_state.party.restore_equipment()
	if restored:
		_recalculate_party_loads()
	return ScenarioRuntimeOperationResult.completed(restored, [DomainEvent.new(&"equipment_restored", {"changed": restored, "source": "classic"})])

func argument_names() -> Array[String]:
	var names: Array[String] = []
	for name: Variant in _arguments.keys():
		names.append(String(name))
	names.sort()
	return names

func cause_fumble(action: ClassicActionDefinition, context: Dictionary) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 2:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 122 requires message and sound fields.")
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.completed(false, [DomainEvent.new(&"combat_fumble_skipped", {"reason": "no-active-battle", "source": "classic"})])
	var actor_id := str(context.get("combatantId", _game_state.combat.active_actor_id()))
	var character := _game_state.party.character_by_id(actor_id)
	var fumbled_definition_id := ""
	if character != null:
		for instance: ItemInstance in character.inventory():
			if not instance.equipped:
				continue
			var definition := _content.item_by_id(instance.definition_id)
			var removed := _rules.inventory.remove_item(character, instance.id, definition)
			if removed != null:
				removed.equipped = false
				_game_state.party.add_storage_item(removed)
				fumbled_definition_id = removed.definition_id
			break
	else:
		var monster := _game_state.combat.monster_by_id(actor_id)
		if monster != null and not monster.weapon_id.is_empty():
			fumbled_definition_id = monster.weapon_id
			monster.weapon_id = ""
	var changed := not fumbled_definition_id.is_empty()
	var events: Array[DomainEvent] = []
	if int(action.extra_code[1]) != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": int(action.extra_code[1]), "source": "classic"}))
	if int(action.extra_code[0]) != 0:
		var message := _content.message_by_id(absi(int(action.extra_code[0])))
		if message != null:
			events.append(DomainEvent.new(&"message_shown", {"messageId": message.id, "text": message.text, "source": "classic"}))
	events.append(DomainEvent.new(&"combatant_fumbled", {"combatantId": actor_id, "itemId": fumbled_definition_id, "changed": changed, "source": "classic"}))
	return ScenarioRuntimeOperationResult.completed(changed, events)

func _init(content: RealmzContent, game_state: GameState) -> void:
	_content = content
	_game_state = game_state

func replace_scenario_program(action: ClassicActionDefinition, context: Dictionary) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 7 requires a five-value Extra Code row.")
	var values := action.extra_code
	var source_program_id := "xap:%d" % int(values[2])
	var target_program_id := ""
	match int(values[0]):
		-1:
			target_program_id = "simple:%d:result:%d" % [int(values[1]), int(values[4])]
		-2:
			target_program_id = "complex:%d:result:%d" % [int(values[1]), int(values[4])]
		_:
			var current_trigger := _content.trigger_by_id(str(context.get("triggerId", "")))
			var current_map: MapDefinition = null
			if current_trigger != null and not current_trigger.map_id.is_empty():
				current_map = _content.world.map_by_id(current_trigger.map_id)
			if current_map == null:
				current_map = _content.world.map_by_id(_game_state.party.map_id)
			if current_map == null:
				return ScenarioRuntimeOperationResult.failed(&"missing_trigger_context", "Classic opcode 7 cannot resolve the current map.")
			var level_type := current_map.level_type
			if int(values[3]) != 0:
				if int(values[3]) not in [1, 2]:
					return ScenarioRuntimeOperationResult.failed(&"invalid_map_type", "Classic opcode 7 map type must be 1 for land or 2 for dungeon.")
				level_type = &"land" if int(values[3]) == 1 else &"dungeon"
			var target_map := _content.world.map_by_type_and_index(level_type, int(values[0]))
			if target_map == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_map", "Classic opcode 7 references unavailable %s map %d." % [String(level_type), int(values[0])])
			var target_trigger := _content.trigger_by_map_record(target_map.id, int(values[1]))
			if target_trigger == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_trigger", "Classic opcode 7 references unavailable Action Point record %d on map '%s'." % [int(values[1]), target_map.id])
			target_program_id = target_trigger.program_id
	if _content.scenario.program_by_id(source_program_id) == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_scenario_program", "Classic opcode 7 references unavailable source XAP %d." % int(values[2]))
	if _content.scenario.program_by_id(target_program_id) == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_scenario_program", "Classic opcode 7 references unavailable target program '%s'." % target_program_id)
	_game_state.set_scenario_program_override(target_program_id, source_program_id)
	return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"scenario_program_replaced", {"sourceProgramId": target_program_id, "targetProgramId": source_program_id, "source": "classic"})])

func branch_to_trigger_program(action: ClassicActionDefinition, context: Dictionary) -> ScenarioRuntimeOperationResult:
	var current_trigger := _content.trigger_by_id(str(context.get("triggerId", "")))
	if current_trigger == null:
		return ScenarioRuntimeOperationResult.failed(&"missing_trigger_context", "Classic opcode 8 requires an Action Point origin.")
	var target_trigger := _content.trigger_by_map_record(current_trigger.map_id, action.operand_id)
	if target_trigger == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_trigger", "Classic opcode 8 references unavailable Action Point record %d on map '%s'." % [action.operand_id, current_trigger.map_id])
	return ScenarioRuntimeOperationResult.completed(target_trigger.program_id, [DomainEvent.new(&"scenario_program_redirected", {"triggerId": current_trigger.id, "targetTriggerId": target_trigger.id, "source": "classic"})], {"kind": "branch-program", "programId": target_trigger.program_id, "gosub": false, "context": context.duplicate(true)})

param(
    [string]$GodotPath = ""
)

$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot

if ([string]::IsNullOrWhiteSpace($GodotPath)) {
    $candidate = Get-ChildItem "$env:LOCALAPPDATA\Microsoft\WinGet\Packages" -Recurse -Filter "Godot_v4.7.1-stable_win64_console.exe" -ErrorAction SilentlyContinue |
        Select-Object -First 1 -ExpandProperty FullName
    if (-not $candidate) {
        throw "Godot 4.7.1 console executable was not found. Pass -GodotPath explicitly."
    }
    $GodotPath = $candidate
}

$intelligenceGenerator = Join-Path $PSScriptRoot "source-intelligence\generate.ps1"
& $intelligenceGenerator
if ($LASTEXITCODE -ne 0) { throw "Source intelligence generation failed." }
if ($env:CI -eq "true") {
    $codemapStatus = @(git -C $repoRoot status --porcelain --untracked-files=all -- docs/codemap)
    if ($codemapStatus.Count -gt 0) {
        throw "Committed source-intelligence artifacts are stale. Regenerate and commit docs/codemap/."
    }
}

function Invoke-GodotGate {
    param(
        [string]$Label,
        [string[]]$GodotArguments
    )

    $previousErrorAction = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try {
        $output = & $GodotPath @GodotArguments 2>&1
        $exitCode = $LASTEXITCODE
    } finally {
        $ErrorActionPreference = $previousErrorAction
    }
    $output | ForEach-Object { Write-Host $_ }
    $combined = $output -join "`n"
    if ($exitCode -ne 0) { throw "$Label failed with exit code $exitCode." }
    if ($combined -match "SCRIPT ERROR:" -or $combined -match "Parse Error:") {
        throw "$Label emitted a GDScript error despite returning exit 0."
    }
}

Invoke-GodotGate "Godot project import/script validation" @("--headless", "--path", $repoRoot, "--editor", "--quit")
Invoke-GodotGate "Main scene smoke launch" @("--headless", "--path", $repoRoot, "--quit-after", "5")
Invoke-GodotGate "Headless test suite" @("--headless", "--path", $repoRoot, "--script", "res://tests/test_runner.gd")

& "$PSScriptRoot\verify_architecture.ps1"
if ($LASTEXITCODE -ne 0) { throw "Architecture boundary verification failed." }

& "$PSScriptRoot\verify_export_contract.ps1"
if ($LASTEXITCODE -ne 0) { throw "Release export contract verification failed." }

git -C $repoRoot diff --check
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed." }

Write-Host "Verification complete."
